/**
 * 工作流查询服务。
 *
 * <p>提供流程实例查询、任务查询、详情查询等功能。</p>
 *
 * <p>该服务基于响应式编程模型，所有查询方法均返回 {@link Mono}，
 * 内部对 MyBatis-Plus 的阻塞式 Mapper 调用统一通过
 * {@link BlockingIoSchedulers#jdbc()} 调度器承载，避免阻塞 Netty 事件循环线程。
 *
 * <h2>核心功能</h2>
 * <ul>
 *   <li>流程实例分页查询与状态过滤</li>
 *   <li>流程实例详情聚合查询（定义 + 任务 + 当前节点）</li>
 *   <li>用户待办任务分页查询</li>
 *   <li>流程定义详情查询（用于设计器加载）</li>
 *   <li>数据库持久化对象向应用 DTO 的转换</li>
 * </ul>
 *
 * @author Apex Team
 * @version 1.4.0
 * @since 1.4.0
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class WorkflowQueryService {

    /** 流程实例 Mapper，负责流程实例表的持久化查询 */
    private final ProcessInstanceMapper processInstanceMapper;

    /** 任务 Mapper，负责任务表的持久化查询 */
    private final TaskMapper taskMapper;

    /** 工作流定义 Mapper，负责流程定义表的持久化查询 */
    private final WorkflowDefinitionMapper workflowDefinitionMapper;

    /** Jackson JSON 解析器，用于解析流程定义的 DAG JSON 结构 */
    private final ObjectMapper objectMapper;

    /**
     * 分页查询流程实例列表。
     *
     * <p>按状态过滤流程实例，按创建时间倒序排列。该方法仅为便捷重载，
     * 内部委托给携带发起人过滤参数的完整版本。
     *
     * @param status 状态过滤（可选）
     * @param pageNum 页码
     * @param pageSize 每页大小
     * @return 分页结果
     */
    public Mono<PageResponse<WorkflowInstanceDTO>> listInstances(String status, int pageNum, int pageSize) {
        return listInstances(pageNum, pageSize, status, null);
    }

    /**
     * 分页查询流程实例列表（完整版本）。
     *
     * <p>支持按状态与发起人双重过滤，查询结果按创建时间倒序排列。
     * 每条实例记录会额外查询其所属工作流定义以补充流程编码信息。
     *
     * @param pageNum 页码
     * @param pageSize 每页大小
     * @param status 状态过滤（可选）
     * @param initiatorId 发起人过滤（可选）
     * @return 分页结果
     */
    public Mono<PageResponse<WorkflowInstanceDTO>> listInstances(
            int pageNum, int pageSize, String status, Long initiatorId) {
        return Mono.fromCallable(() -> {
                    log.info(
                            "开始查询工作流实例列表: pageNum={}, pageSize={}, status={}, initiatorId={}",
                            pageNum,
                            pageSize,
                            status,
                            initiatorId);

                    Page<ProcessInstancePO> page = new Page<>(pageNum, pageSize);
                    LambdaQueryWrapper<ProcessInstancePO> wrapper = new LambdaQueryWrapper<>();

                    if (status != null && !status.isEmpty()) {
                        wrapper.eq(ProcessInstancePO::getStatus, status);
                    }
                    if (initiatorId != null) {
                        wrapper.eq(ProcessInstancePO::getInitiatorId, initiatorId);
                    }
                    wrapper.orderByDesc(ProcessInstancePO::getCreateTime);

                    IPage<ProcessInstancePO> poPage = processInstanceMapper.selectPage(page, wrapper);
                    log.info("查询到 {} 条记录，总数: {}", poPage.getRecords().size(), poPage.getTotal());

                    // 转换为 DTO，需要查询工作流定义获取 processCode
                    List<WorkflowInstanceDTO> dtoList = poPage.getRecords().stream()
                            .map(po -> {
                                WorkflowDefinitionPO definition =
                                        workflowDefinitionMapper.selectById(po.getWorkflowDefinitionId());
                                return convertToInstanceDTO(po, definition);
                            })
                            .collect(Collectors.toList());

                    log.info("转换完成，返回 {} 条 DTO", dtoList.size());
                    return PageResponse.of(dtoList, poPage.getTotal(), pageNum, pageSize);
                })
                .doOnError(error -> log.error("查询工作流实例列表失败", error))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取流程实例详情（包含定义和任务）。
     *
     * <p>聚合流程实例基本信息、流程定义、任务列表与当前节点，
     * 用于详情页完整渲染。若实例不存在则返回 null。
     *
     * @param instanceId 流程实例 ID
     * @return 流程详情 DTO
     */
    public Mono<WorkflowInstanceDetailDTO> getInstanceDetail(Long instanceId) {
        return Mono.fromCallable(() -> {
                    WorkflowInstanceDetailDTO detail = new WorkflowInstanceDetailDTO();

                    // 查询流程实例
                    ProcessInstancePO processInstance = processInstanceMapper.selectById(instanceId);
                    if (processInstance == null) {
                        return null;
                    }

                    // 查询流程定义
                    WorkflowDefinitionPO workflowDefinition =
                            workflowDefinitionMapper.selectById(processInstance.getWorkflowDefinitionId());
                    detail.setInstance(convertToInstanceDTO(processInstance, workflowDefinition));
                    detail.setCurrentNodeId(processInstance.getCurrentNodeCode());

                    if (workflowDefinition != null) {
                        detail.setDefinition(convertToDefinitionDTO(workflowDefinition));
                    }

                    // 查询任务列表
                    List<TaskPO> taskList = taskMapper.selectList(new LambdaQueryWrapper<TaskPO>()
                            .eq(TaskPO::getProcessInstanceId, instanceId)
                            .orderByDesc(TaskPO::getCreateTime));
                    List<WorkflowTaskDTO> tasks =
                            taskList.stream().map(this::convertToTaskDTO).collect(Collectors.toList());
                    detail.setTasks(tasks);

                    return detail;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 查询用户待办任务。
     *
     * <p>按办理人 ID 查询状态为 PENDING 的待办任务，按创建时间倒序分页返回。
     *
     * @param assigneeId 办理人 ID
     * @param pageNum 页码
     * @param pageSize 每页大小
     * @return 分页结果
     */
    public Mono<PageResponse<WorkflowTaskDTO>> listMyTasks(Long assigneeId, int pageNum, int pageSize) {
        return com.apex.scaffold.common.context.TenantContext.withTenant(Mono.fromCallable(() -> {
                    Page<TaskPO> page = new Page<>(pageNum, pageSize);
                    LambdaQueryWrapper<TaskPO> wrapper = new LambdaQueryWrapper<>();
                    wrapper.eq(TaskPO::getAssigneeId, assigneeId)
                            .eq(TaskPO::getStatus, "PENDING")
                            .orderByDesc(TaskPO::getCreateTime);

                    com.apex.scaffold.common.context.TenantContext.currentTenantId()
                            .ifPresent(tenantId -> wrapper.eq(TaskPO::getTenantId, tenantId));
                    IPage<TaskPO> poPage = taskMapper.selectPage(page, wrapper);

                    List<WorkflowTaskDTO> dtoList = poPage.getRecords().stream()
                            .map(this::convertToTaskDTO)
                            .collect(Collectors.toList());

                    return PageResponse.of(dtoList, poPage.getTotal(), pageNum, pageSize);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc()));
    }

    /**
     * 按任务 ID 查询任务详情。
     *
     * <p>用于在工作流事件发布等场景补充任务信息（所属流程实例、节点编码等）。
     * 主键不存在时返回空 {@link Mono}。
     *
     * @param taskId 任务 ID
     * @return 任务 DTO；任务不存在时返回 {@link Mono#empty()}
     */
    public Mono<WorkflowTaskDTO> getTaskById(Long taskId) {
        return Mono.fromCallable(() -> {
                    TaskPO po = taskMapper.selectById(taskId);
                    return po == null ? null : convertToTaskDTO(po);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取流程定义详情（用于设计器加载）。
     *
     * <p>根据流程编码查询唯一的流程定义，并解析其 DAG JSON 结构。
     *
     * @param workflowCode 流程编码
     * @return 流程定义 DTO
     */
    public Mono<WorkflowDefinitionDTO> getDefinitionDetail(String workflowCode) {
        return Mono.fromCallable(() -> {
                    WorkflowDefinitionPO workflowDefinition =
                            workflowDefinitionMapper.selectOne(new LambdaQueryWrapper<WorkflowDefinitionPO>()
                                    .eq(WorkflowDefinitionPO::getWorkflowCode, workflowCode));
                    if (workflowDefinition == null) {
                        return null;
                    }
                    return convertToDefinitionDTO(workflowDefinition);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取流程定义详情（根据定义 ID）。
     *
     * <p>根据流程定义主键 ID 查询流程定义，并解析其 DAG JSON 结构。
     *
     * @param definitionId 流程定义 ID
     * @return 流程定义 DTO
     */
    public Mono<WorkflowDefinitionDTO> getDefinitionDetail(Long definitionId) {
        return Mono.fromCallable(() -> {
                    WorkflowDefinitionPO workflowDefinition = workflowDefinitionMapper.selectById(definitionId);
                    if (workflowDefinition == null) {
                        return null;
                    }
                    return convertToDefinitionDTO(workflowDefinition);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 将流程实例持久化对象转换为流程实例 DTO。
     *
     * <p>流程编码取自关联的工作流定义而非业务键；发起人姓名暂采用简化规则拼接。
     *
     * @param po 流程实例持久化对象
     * @param definition 关联的工作流定义持久化对象（可能为 null）
     * @return 流程实例 DTO
     */
    private WorkflowInstanceDTO convertToInstanceDTO(ProcessInstancePO po, WorkflowDefinitionPO definition) {
        WorkflowInstanceDTO dto = new WorkflowInstanceDTO();
        dto.setId(po.getId());
        dto.setDefinitionId(po.getWorkflowDefinitionId());
        // 从工作流定义获取 processCode，而不是使用 businessKey
        dto.setProcessCode(definition != null ? definition.getWorkflowCode() : null);
        dto.setTitle(po.getRemark() != null ? po.getRemark() : "流程实例-" + po.getId());
        dto.setStatus(po.getStatus());
        dto.setSuspended(Boolean.TRUE.equals(po.getSuspended()) || "SUSPENDED".equals(po.getStatus()));
        dto.setInitiatorId(po.getInitiatorId());
        // 简化映射，实际应关联用户表
        dto.setInitiatorName("用户-" + po.getInitiatorId());
        dto.setBusinessKey(po.getBusinessKey());
        dto.setCurrentNodeId(po.getCurrentNodeCode());
        dto.setStartTime(po.getStartTime());
        dto.setEndTime(po.getEndTime());
        dto.setCreateTime(po.getCreateTime());
        return dto;
    }

    /**
     * 将任务持久化对象转换为任务 DTO。
     *
     * <p>任务类型暂固定为 USER_TASK，办理人姓名采用简化规则拼接。
     *
     * @param po 任务持久化对象
     * @return 任务 DTO
     */
    private WorkflowTaskDTO convertToTaskDTO(TaskPO po) {
        WorkflowTaskDTO dto = new WorkflowTaskDTO();
        dto.setId(po.getId());
        dto.setInstanceId(po.getProcessInstanceId());
        dto.setTaskName(po.getTaskName());
        // 简化映射
        dto.setTaskType("USER_TASK");
        dto.setStatus(po.getStatus());
        dto.setAssigneeId(po.getAssigneeId());
        // 简化映射
        dto.setAssigneeName("用户-" + po.getAssigneeId());
        dto.setComment(po.getRemark());
        dto.setNodeId(po.getNodeCode());
        dto.setStartTime(po.getCreateTime());
        dto.setCompletedTime(po.getCompleteTime());
        dto.setCreateTime(po.getCreateTime());
        return dto;
    }

    /**
     * 将工作流定义持久化对象转换为定义 DTO。
     *
     * <p>会解析 {@code node_definition} 字段中的 DAG JSON 结构，
     * 提取其中节点列表与连线列表。解析失败时返回空的节点与连线列表。
     *
     * @param po 工作流定义持久化对象
     * @return 流程定义 DTO
     */
    private WorkflowDefinitionDTO convertToDefinitionDTO(WorkflowDefinitionPO po) {
        WorkflowDefinitionDTO dto = new WorkflowDefinitionDTO();
        dto.setId(po.getId());
        dto.setCode(po.getWorkflowCode());
        dto.setName(po.getWorkflowName());
        dto.setDescription(po.getDescription());
        dto.setVersion(po.getVersion());
        dto.setEnabled(po.getEnabled() == 1);

        // 解析 DAG JSON，增加 null 防护
        try {
            if (po.getNodeDefinition() != null && !po.getNodeDefinition().isEmpty()) {
                Map<String, Object> dag =
                        objectMapper.readValue(po.getNodeDefinition(), new TypeReference<Map<String, Object>>() {});

                // 解析节点，增加 null 检查
                if (dag != null) {
                    @SuppressWarnings("unchecked")
                    List<Map<String, Object>> nodesJson = (List<Map<String, Object>>) dag.get("nodes");
                    if (nodesJson != null) {
                        List<WorkflowDefinitionDTO.WorkflowNodeDTO> nodes =
                                nodesJson.stream().map(this::convertToNodeDTO).collect(Collectors.toList());
                        dto.setNodes(nodes);
                    } else {
                        dto.setNodes(new ArrayList<>(16));
                    }

                    // 解析连线
                    @SuppressWarnings("unchecked")
                    List<Map<String, Object>> edgesJson = (List<Map<String, Object>>) dag.get("edges");
                    if (edgesJson != null) {
                        List<WorkflowDefinitionDTO.WorkflowEdgeDTO> edges =
                                edgesJson.stream().map(this::convertToEdgeDTO).collect(Collectors.toList());
                        dto.setEdges(edges);
                    } else {
                        dto.setEdges(new ArrayList<>(16));
                    }
                } else {
                    dto.setNodes(new ArrayList<>(16));
                    dto.setEdges(new ArrayList<>(16));
                }
            } else {
                dto.setNodes(new ArrayList<>(16));
                dto.setEdges(new ArrayList<>(16));
            }
        } catch (Exception e) {
            log.error("解析 DAG JSON 失败", e);
            dto.setNodes(new ArrayList<>(16));
            dto.setEdges(new ArrayList<>(16));
        }

        return dto;
    }

    /**
     * 将节点 JSON 数据转换为节点 DTO。
     *
     * <p>从 JSON 中提取节点的标识、类型、名称、审批人配置、超时配置与坐标位置等字段。
     *
     * @param json 节点 JSON 数据
     * @return 节点 DTO
     */
    private WorkflowDefinitionDTO.WorkflowNodeDTO convertToNodeDTO(Map<String, Object> json) {
        WorkflowDefinitionDTO.WorkflowNodeDTO node = new WorkflowDefinitionDTO.WorkflowNodeDTO();
        node.setNodeId((String) json.get("nodeId"));
        node.setNodeType((String) json.get("nodeType"));
        node.setNodeName((String) json.get("nodeName"));
        node.setApproverType((String) json.get("approverType"));
        node.setApproverValue((String) json.get("approverValue"));
        node.setApprovalStrategy((String) json.get("approvalStrategy"));
        node.setTimeoutHours((Integer) json.get("timeoutHours"));
        node.setTimeoutAction((String) json.get("timeoutAction"));

        @SuppressWarnings("unchecked")
        Map<String, Object> position = (Map<String, Object>) json.get("position");
        node.setPosition(position != null ? position : new HashMap<>(16));

        return node;
    }

    /**
     * 将连线 JSON 数据转换为连线 DTO。
     *
     * <p>从 JSON 中提取连线的标识、源节点、目标节点与流转条件字段。
     *
     * @param json 连线 JSON 数据
     * @return 连线 DTO
     */
    private WorkflowDefinitionDTO.WorkflowEdgeDTO convertToEdgeDTO(Map<String, Object> json) {
        WorkflowDefinitionDTO.WorkflowEdgeDTO edge = new WorkflowDefinitionDTO.WorkflowEdgeDTO();
        edge.setEdgeId((String) json.get("edgeId"));
        edge.setSourceNodeId((String) json.get("sourceNodeId"));
        edge.setTargetNodeId((String) json.get("targetNodeId"));
        edge.setCondition((String) json.get("condition"));
        return edge;
    }
}

package com.apex.scaffold.workflow.infrastructure.persistence.po;

import com.apex.scaffold.common.persistence.po.BasePO;
import com.baomidou.mybatisplus.annotation.TableField;
import com.baomidou.mybatisplus.annotation.TableName;
import java.time.LocalDateTime;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.NoArgsConstructor;
import lombok.experimental.SuperBuilder;

/**
 * 流程实例持久化对象（PO）。
 *
 * <p>映射数据库表 {@code wf_process_instance}，存储工作流流程实例的核心信息。
 * 继承 {@link BasePO} 获得主键、创建/更新时间、乐观锁版本与逻辑删除等通用字段。</p>
 *
 * <h2>字段说明</h2>
 * <ul>
 *   <li>{@code suspended}：挂起标志，对应数据库字段 {@code suspended}（TINYINT 类型）。</li>
 *   <li>{@code formData}：表单数据 JSON，对应数据库字段 {@code form_data}。</li>
 * </ul>
 *
 * @author Apex Team
 * @version 1.3.0
 * @since 1.0.0
 * @see com.apex.scaffold.workflow.domain.model.ProcessInstance
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
@SuperBuilder
@EqualsAndHashCode(callSuper = true)
@TableName("wf_process_instance")
public class ProcessInstancePO extends BasePO {

    /** 租户 ID，用于多租户数据隔离。 */
    private String tenantId;

    /** 所属流程定义 ID，指向 {@code wf_workflow_definition} 表主键。 */
    private Long workflowDefinitionId;

    /** 业务主键，用于与业务单据关联。 */
    private String businessKey;

    /** 发起人用户 ID。 */
    private Long initiatorId;

    /** 当前所处节点标识，对应数据库字段 {@code current_node_key}。 */
    @TableField("current_node_key")
    private String currentNodeCode;

    /** 流程实例状态，取值参见领域模型 {@code ProcessInstance} 状态说明。 */
    private String status;

    /** 表单数据 JSON，保存流程运行期的业务变量。 */
    private String formData;

    /** 流程开始时间。 */
    private LocalDateTime startTime;

    /** 流程结束时间，未结束时为 {@code null}。 */
    private LocalDateTime endTime;

    /** 备注信息（兼容字段，常被复用为流程标题）。 */
    private String remark;

    /** 挂起标志，{@code true} 表示已挂起。 */
    private Boolean suspended;

    /**
     * 获取流程编码（兼容方法，实际返回 {@link #businessKey} 字段值）。
     *
     * @return 流程编码
     */
    public String getProcessCode() {
        return businessKey;
    }

    /**
     * 设置流程编码（兼容方法，实际写入 {@link #businessKey} 字段）。
     *
     * @param processCode 流程编码
     */
    public void setProcessCode(String processCode) {
        this.businessKey = processCode;
    }

    /**
     * 获取流程标题（兼容方法，实际返回 {@link #remark} 字段值）。
     *
     * @return 流程标题
     */
    public String getTitle() {
        return remark;
    }

    /**
     * 设置流程标题（兼容方法，实际写入 {@link #remark} 字段）。
     *
     * @param title 流程标题
     */
    public void setTitle(String title) {
        this.remark = title;
    }
}

package com.apex.scaffold.workflow.infrastructure.persistence.mapper;

import com.apex.scaffold.workflow.infrastructure.persistence.po.ProcessInstancePO;
import com.baomidou.mybatisplus.core.mapper.BaseMapper;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Map;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;

/**
 * 流程实例 MyBatis Mapper 接口。
 *
 * <p>基于 MyBatis-Plus {@link BaseMapper}，提供流程实例持久化对象
 * {@link ProcessInstancePO} 的基础 CRUD 操作，并额外提供用于监控统计的聚合查询。</p>
 *
 * @author Apex Team
 * @version 1.0.0
 * @since 1.0.0
 */
@Mapper
public interface ProcessInstanceMapper extends BaseMapper<ProcessInstancePO> {

    /**
     * 统计指定时间区间内发起的流程实例数量。
     *
     * @param start 区间起点（含）
     * @param end 区间终点（不含）
     * @return 发起的流程实例数量
     */
    @Select(
            "SELECT COUNT(*) FROM wf_process_instance WHERE start_time >= #{start} AND start_time < #{end} AND deleted = 0")
    Integer countTodayStarted(@Param("start") LocalDateTime start, @Param("end") LocalDateTime end);

    /**
     * 按状态统计流程实例数量。
     *
     * @param status 流程实例状态
     * @return 指定状态的流程实例数量
     */
    @Select("SELECT COUNT(*) FROM wf_process_instance WHERE status = #{status} AND deleted = 0")
    Integer countByStatus(@Param("status") String status);

    /**
     * 统计处于挂起状态的流程实例数量。
     *
     * @return 挂起的流程实例数量
     */
    @Select("SELECT COUNT(*) FROM wf_process_instance WHERE suspended = 1 AND deleted = 0")
    Integer countSuspended();

    /**
     * 统计已结束流程实例的平均处理耗时（秒）。
     *
     * @return 平均耗时（秒）；无已结束实例时可能为 {@code null}
     */
    @Select(
            "SELECT AVG(TIMESTAMPDIFF(SECOND, start_time, end_time)) FROM wf_process_instance WHERE end_time IS NOT NULL AND deleted = 0")
    Long avgCompletionSeconds();

    /**
     * 按状态统计流程实例分布。
     *
     * @return 由状态与数量组成的记录列表，每项包含 {@code status} 与 {@code count}
     */
    @Select("SELECT status, COUNT(*) as count FROM wf_process_instance WHERE deleted = 0 GROUP BY status")
    List<Map<String, Object>> statusDistribution();

    /**
     * 按日期区间统计每日发起的流程实例数量。
     *
     * @param start 区间起点（含）
     * @param end 区间终点（不含）
     * @return 由日期与数量组成的记录列表，每项包含 {@code date} 与 {@code count}
     */
    @Select(
            "SELECT DATE(start_time) as date, COUNT(*) as count FROM wf_process_instance WHERE start_time >= #{start} AND start_time < #{end} AND deleted = 0 GROUP BY DATE(start_time)")
    List<Map<String, Object>> countStartedByDateRange(
            @Param("start") LocalDateTime start, @Param("end") LocalDateTime end);

    /**
     * 按日期区间统计每日完成的流程实例数量。
     *
     * @param start 区间起点（含）
     * @param end 区间终点（不含）
     * @return 由日期与数量组成的记录列表，每项包含 {@code date} 与 {@code count}
     */
    @Select(
            "SELECT DATE(end_time) as date, COUNT(*) as count FROM wf_process_instance WHERE end_time >= #{start} AND end_time < #{end} AND deleted = 0 GROUP BY DATE(end_time)")
    List<Map<String, Object>> countCompletedByDateRange(
            @Param("start") LocalDateTime start, @Param("end") LocalDateTime end);
}

package com.apex.scaffold.workflow.infrastructure.persistence.repository;

import com.apex.scaffold.common.context.TenantContext;
import com.apex.scaffold.common.persistence.util.ConditionUtil;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.workflow.domain.model.ProcessInstance;
import com.apex.scaffold.workflow.domain.repository.ProcessInstanceRepository;
import com.apex.scaffold.workflow.infrastructure.persistence.converter.ProcessInstancePoConverter;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.ProcessInstanceMapper;
import com.apex.scaffold.workflow.infrastructure.persistence.po.ProcessInstancePO;
import java.time.LocalDateTime;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Repository;
import reactor.core.publisher.Mono;

/**
 * 流程实例仓储实现。
 *
 * <p>基于 MyBatis-Plus 实现流程实例仓储接口 {@link ProcessInstanceRepository}，
 * 负责流程实例领域对象与数据库表 {@code wf_process_instance} 之间的映射与转换。</p>
 *
 * <h2>阻塞操作隔离</h2>
 * <p>所有数据库操作通过 {@link BlockingIoSchedulers#jdbc()} 调度器执行，
 * 避免阻塞响应式流的事件循环线程。</p>
 *
 * @author Apex Team
 * @version 1.0.0
 * @since 1.0.0
 */
@Repository
@RequiredArgsConstructor
public class ProcessInstanceRepositoryImpl implements ProcessInstanceRepository {

    /** 流程实例 MyBatis Mapper。 */
    private final ProcessInstanceMapper processInstanceMapper;

    /** 流程实例 PO 转换器。 */
    private final ProcessInstancePoConverter processInstancePoConverter;

    /** {@inheritDoc} */
    @Override
    public Mono<ProcessInstance> findById(Long id) {
        return Mono.fromCallable(() -> processInstanceMapper.selectById(id))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(processInstancePoConverter.toEntity(po)));
    }

    /** {@inheritDoc} */
    @Override
    public Mono<ProcessInstance> findByBusinessKey(String businessKey) {
        return Mono.fromCallable(() -> processInstanceMapper.selectOne(ConditionUtil.lambda(ProcessInstancePO.class)
                        .eq(ProcessInstancePO::getBusinessKey, businessKey)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(processInstancePoConverter.toEntity(po)));
    }

    /** {@inheritDoc} */
    @Override
    public Mono<List<ProcessInstance>> findByInitiator(Long initiatorId) {
        return Mono.fromCallable(() -> processInstanceMapper.selectList(ConditionUtil.lambda(ProcessInstancePO.class)
                        .eq(ProcessInstancePO::getInitiatorId, initiatorId)
                        .orderByDesc(ProcessInstancePO::getCreateTime)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .map(processInstancePoConverter::toEntityList);
    }

    /** {@inheritDoc} */
    @Override
    public Mono<Integer> insert(ProcessInstance entity) {
        return TenantContext.withTenant(Mono.fromCallable(() -> {
                    ProcessInstancePO po = processInstancePoConverter.toPo(entity);
                    po.setTenantId(TenantContext.currentTenantId().orElseThrow());
                    po.setCreateTime(LocalDateTime.now());
                    po.setUpdateTime(po.getCreateTime());
                    po.setVersion(0);
                    int inserted = processInstanceMapper.insert(po);
                    entity.setId(po.getId());
                    return inserted;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc()));
    }

    /** {@inheritDoc} */
    @Override
    public Mono<Integer> updateById(ProcessInstance entity) {
        return Mono.fromCallable(() -> processInstanceMapper.updateById(processInstancePoConverter.toPo(entity)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /** {@inheritDoc} */
    @Override
    public Mono<Integer> deleteById(Long id) {
        return Mono.fromCallable(() -> processInstanceMapper.deleteById(id)).subscribeOn(BlockingIoSchedulers.jdbc());
    }
}

package com.apex.scaffold.workflow.application.query;

import com.apex.scaffold.common.dto.PageResponse;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.workflow.application.dto.WorkflowDefinitionDTO;
import com.apex.scaffold.workflow.application.dto.WorkflowInstanceDTO;
import com.apex.scaffold.workflow.application.dto.WorkflowInstanceDetailDTO;
import com.apex.scaffold.workflow.application.dto.WorkflowTaskDTO;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.ProcessInstanceMapper;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.TaskMapper;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.WorkflowDefinitionMapper;
import com.apex.scaffold.workflow.infrastructure.persistence.po.ProcessInstancePO;
import com.apex.scaffold.workflow.infrastructure.persistence.po.TaskPO;
import com.apex.scaffold.workflow.infrastructure.persistence.po.WorkflowDefinitionPO;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.core.metadata.IPage;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;

/**
 * 工作流查询服务。
 *
 * <p>提供流程实例查询、任务查询、详情查询等功能。</p>
 *
 * <p>该服务基于响应式编程模型，所有查询方法均返回 {@link Mono}，
 * 内部对 MyBatis-Plus 的阻塞式 Mapper 调用统一通过
 * {@link BlockingIoSchedulers#jdbc()} 调度器承载，避免阻塞 Netty 事件循环线程。
 *
 * <h2>核心功能</h2>
 * <ul>
 *   <li>流程实例分页查询与状态过滤</li>
 *   <li>流程实例详情聚合查询（定义 + 任务 + 当前节点）</li>
 *   <li>用户待办任务分页查询</li>
 *   <li>流程定义详情查询（用于设计器加载）</li>
 *   <li>数据库持久化对象向应用 DTO 的转换</li>
 * </ul>
 *
 * @author Apex Team
 * @version 1.4.0
 * @since 1.4.0
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class WorkflowQueryService {

    /** 流程实例 Mapper，负责流程实例表的持久化查询 */
    private final ProcessInstanceMapper processInstanceMapper;

    /** 任务 Mapper，负责任务表的持久化查询 */
    private final TaskMapper taskMapper;

    /** 工作流定义 Mapper，负责流程定义表的持久化查询 */
    private final WorkflowDefinitionMapper workflowDefinitionMapper;

    /** Jackson JSON 解析器，用于解析流程定义的 DAG JSON 结构 */
    private final ObjectMapper objectMapper;

    /**
     * 分页查询流程实例列表。
     *
     * <p>按状态过滤流程实例，按创建时间倒序排列。该方法仅为便捷重载，
     * 内部委托给携带发起人过滤参数的完整版本。
     *
     * @param status 状态过滤（可选）
     * @param pageNum 页码
     * @param pageSize 每页大小
     * @return 分页结果
     */
    public Mono<PageResponse<WorkflowInstanceDTO>> listInstances(String status, int pageNum, int pageSize) {
        return listInstances(pageNum, pageSize, status, null);
    }

    /**
     * 分页查询流程实例列表（完整版本）。
     *
     * <p>支持按状态与发起人双重过滤，查询结果按创建时间倒序排列。
     * 每条实例记录会额外查询其所属工作流定义以补充流程编码信息。
     *
     * @param pageNum 页码
     * @param pageSize 每页大小
     * @param status 状态过滤（可选）
     * @param initiatorId 发起人过滤（可选）
     * @return 分页结果
     */
    public Mono<PageResponse<WorkflowInstanceDTO>> listInstances(
            int pageNum, int pageSize, String status, Long initiatorId) {
        return Mono.fromCallable(() -> {
                    log.info(
                            "开始查询工作流实例列表: pageNum={}, pageSize={}, status={}, initiatorId={}",
                            pageNum,
                            pageSize,
                            status,
                            initiatorId);

                    Page<ProcessInstancePO> page = new Page<>(pageNum, pageSize);
                    LambdaQueryWrapper<ProcessInstancePO> wrapper = new LambdaQueryWrapper<>();

                    if (status != null && !status.isEmpty()) {
                        wrapper.eq(ProcessInstancePO::getStatus, status);
                    }
                    if (initiatorId != null) {
                        wrapper.eq(ProcessInstancePO::getInitiatorId, initiatorId);
                    }
                    wrapper.orderByDesc(ProcessInstancePO::getCreateTime);

                    IPage<ProcessInstancePO> poPage = processInstanceMapper.selectPage(page, wrapper);
                    log.info("查询到 {} 条记录，总数: {}", poPage.getRecords().size(), poPage.getTotal());

                    // 转换为 DTO，需要查询工作流定义获取 processCode
                    List<WorkflowInstanceDTO> dtoList = poPage.getRecords().stream()
                            .map(po -> {
                                WorkflowDefinitionPO definition =
                                        workflowDefinitionMapper.selectById(po.getWorkflowDefinitionId());
                                return convertToInstanceDTO(po, definition);
                            })
                            .collect(Collectors.toList());

                    log.info("转换完成，返回 {} 条 DTO", dtoList.size());
                    return PageResponse.of(dtoList, poPage.getTotal(), pageNum, pageSize);
                })
                .doOnError(error -> log.error("查询工作流实例列表失败", error))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取流程实例详情（包含定义和任务）。
     *
     * <p>聚合流程实例基本信息、流程定义、任务列表与当前节点，
     * 用于详情页完整渲染。若实例不存在则返回 null。
     *
     * @param instanceId 流程实例 ID
     * @return 流程详情 DTO
     */
    public Mono<WorkflowInstanceDetailDTO> getInstanceDetail(Long instanceId) {
        return Mono.fromCallable(() -> {
                    WorkflowInstanceDetailDTO detail = new WorkflowInstanceDetailDTO();

                    // 查询流程实例
                    ProcessInstancePO processInstance = processInstanceMapper.selectById(instanceId);
                    if (processInstance == null) {
                        return null;
                    }

                    // 查询流程定义
                    WorkflowDefinitionPO workflowDefinition =
                            workflowDefinitionMapper.selectById(processInstance.getWorkflowDefinitionId());
                    detail.setInstance(convertToInstanceDTO(processInstance, workflowDefinition));
                    detail.setCurrentNodeId(processInstance.getCurrentNodeCode());

                    if (workflowDefinition != null) {
                        detail.setDefinition(convertToDefinitionDTO(workflowDefinition));
                    }

                    // 查询任务列表
                    List<TaskPO> taskList = taskMapper.selectList(new LambdaQueryWrapper<TaskPO>()
                            .eq(TaskPO::getProcessInstanceId, instanceId)
                            .orderByDesc(TaskPO::getCreateTime));
                    List<WorkflowTaskDTO> tasks =
                            taskList.stream().map(this::convertToTaskDTO).collect(Collectors.toList());
                    detail.setTasks(tasks);

                    return detail;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 查询用户待办任务。
     *
     * <p>按办理人 ID 查询状态为 PENDING 的待办任务，按创建时间倒序分页返回。
     *
     * @param assigneeId 办理人 ID
     * @param pageNum 页码
     * @param pageSize 每页大小
     * @return 分页结果
     */
    public Mono<PageResponse<WorkflowTaskDTO>> listMyTasks(Long assigneeId, int pageNum, int pageSize) {
        return com.apex.scaffold.common.context.TenantContext.withTenant(Mono.fromCallable(() -> {
                    Page<TaskPO> page = new Page<>(pageNum, pageSize);
                    LambdaQueryWrapper<TaskPO> wrapper = new LambdaQueryWrapper<>();
                    wrapper.eq(TaskPO::getAssigneeId, assigneeId)
                            .eq(TaskPO::getStatus, "PENDING")
                            .orderByDesc(TaskPO::getCreateTime);

                    com.apex.scaffold.common.context.TenantContext.currentTenantId()
                            .ifPresent(tenantId -> wrapper.eq(TaskPO::getTenantId, tenantId));
                    IPage<TaskPO> poPage = taskMapper.selectPage(page, wrapper);

                    List<WorkflowTaskDTO> dtoList = poPage.getRecords().stream()
                            .map(this::convertToTaskDTO)
                            .collect(Collectors.toList());

                    return PageResponse.of(dtoList, poPage.getTotal(), pageNum, pageSize);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc()));
    }

    /**
     * 按任务 ID 查询任务详情。
     *
     * <p>用于在工作流事件发布等场景补充任务信息（所属流程实例、节点编码等）。
     * 主键不存在时返回空 {@link Mono}。
     *
     * @param taskId 任务 ID
     * @return 任务 DTO；任务不存在时返回 {@link Mono#empty()}
     */
    public Mono<WorkflowTaskDTO> getTaskById(Long taskId) {
        return Mono.fromCallable(() -> {
                    TaskPO po = taskMapper.selectById(taskId);
                    return po == null ? null : convertToTaskDTO(po);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取流程定义详情（用于设计器加载）。
     *
     * <p>根据流程编码查询唯一的流程定义，并解析其 DAG JSON 结构。
     *
     * @param workflowCode 流程编码
     * @return 流程定义 DTO
     */
    public Mono<WorkflowDefinitionDTO> getDefinitionDetail(String workflowCode) {
        return Mono.fromCallable(() -> {
                    WorkflowDefinitionPO workflowDefinition =
                            workflowDefinitionMapper.selectOne(new LambdaQueryWrapper<WorkflowDefinitionPO>()
                                    .eq(WorkflowDefinitionPO::getWorkflowCode, workflowCode));
                    if (workflowDefinition == null) {
                        return null;
                    }
                    return convertToDefinitionDTO(workflowDefinition);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取流程定义详情（根据定义 ID）。
     *
     * <p>根据流程定义主键 ID 查询流程定义，并解析其 DAG JSON 结构。
     *
     * @param definitionId 流程定义 ID
     * @return 流程定义 DTO
     */
    public Mono<WorkflowDefinitionDTO> getDefinitionDetail(Long definitionId) {
        return Mono.fromCallable(() -> {
                    WorkflowDefinitionPO workflowDefinition = workflowDefinitionMapper.selectById(definitionId);
                    if (workflowDefinition == null) {
                        return null;
                    }
                    return convertToDefinitionDTO(workflowDefinition);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 将流程实例持久化对象转换为流程实例 DTO。
     *
     * <p>流程编码取自关联的工作流定义而非业务键；发起人姓名暂采用简化规则拼接。
     *
     * @param po 流程实例持久化对象
     * @param definition 关联的工作流定义持久化对象（可能为 null）
     * @return 流程实例 DTO
     */
    private WorkflowInstanceDTO convertToInstanceDTO(ProcessInstancePO po, WorkflowDefinitionPO definition) {
        WorkflowInstanceDTO dto = new WorkflowInstanceDTO();
        dto.setId(po.getId());
        dto.setDefinitionId(po.getWorkflowDefinitionId());
        // 从工作流定义获取 processCode，而不是使用 businessKey
        dto.setProcessCode(definition != null ? definition.getWorkflowCode() : null);
        dto.setTitle(po.getRemark() != null ? po.getRemark() : "流程实例-" + po.getId());
        dto.setStatus(po.getStatus());
        dto.setSuspended(Boolean.TRUE.equals(po.getSuspended()) || "SUSPENDED".equals(po.getStatus()));
        dto.setInitiatorId(po.getInitiatorId());
        // 简化映射，实际应关联用户表
        dto.setInitiatorName("用户-" + po.getInitiatorId());
        dto.setBusinessKey(po.getBusinessKey());
        dto.setCurrentNodeId(po.getCurrentNodeCode());
        dto.setStartTime(po.getStartTime());
        dto.setEndTime(po.getEndTime());
        dto.setCreateTime(po.getCreateTime());
        return dto;
    }

    /**
     * 将任务持久化对象转换为任务 DTO。
     *
     * <p>任务类型暂固定为 USER_TASK，办理人姓名采用简化规则拼接。
     *
     * @param po 任务持久化对象
     * @return 任务 DTO
     */
    private WorkflowTaskDTO convertToTaskDTO(TaskPO po) {
        WorkflowTaskDTO dto = new WorkflowTaskDTO();
        dto.setId(po.getId());
        dto.setInstanceId(po.getProcessInstanceId());
        dto.setTaskName(po.getTaskName());
        // 简化映射
        dto.setTaskType("USER_TASK");
        dto.setStatus(po.getStatus());
        dto.setAssigneeId(po.getAssigneeId());
        // 简化映射
        dto.setAssigneeName("用户-" + po.getAssigneeId());
        dto.setComment(po.getRemark());
        dto.setNodeId(po.getNodeCode());
        dto.setStartTime(po.getCreateTime());
        dto.setCompletedTime(po.getCompleteTime());
        dto.setCreateTime(po.getCreateTime());
        return dto;
    }

    /**
     * 将工作流定义持久化对象转换为定义 DTO。
     *
     * <p>会解析 {@code node_definition} 字段中的 DAG JSON 结构，
     * 提取其中节点列表与连线列表。解析失败时返回空的节点与连线列表。
     *
     * @param po 工作流定义持久化对象
     * @return 流程定义 DTO
     */
    private WorkflowDefinitionDTO convertToDefinitionDTO(WorkflowDefinitionPO po) {
        WorkflowDefinitionDTO dto = new WorkflowDefinitionDTO();
        dto.setId(po.getId());
        dto.setCode(po.getWorkflowCode());
        dto.setName(po.getWorkflowName());
        dto.setDescription(po.getDescription());
        dto.setVersion(po.getVersion());
        dto.setEnabled(po.getEnabled() == 1);

        // 解析 DAG JSON，增加 null 防护
        try {
            if (po.getNodeDefinition() != null && !po.getNodeDefinition().isEmpty()) {
                Map<String, Object> dag =
                        objectMapper.readValue(po.getNodeDefinition(), new TypeReference<Map<String, Object>>() {});

                // 解析节点，增加 null 检查
                if (dag != null) {
                    @SuppressWarnings("unchecked")
                    List<Map<String, Object>> nodesJson = (List<Map<String, Object>>) dag.get("nodes");
                    if (nodesJson != null) {
                        List<WorkflowDefinitionDTO.WorkflowNodeDTO> nodes =
                                nodesJson.stream().map(this::convertToNodeDTO).collect(Collectors.toList());
                        dto.setNodes(nodes);
                    } else {
                        dto.setNodes(new ArrayList<>(16));
                    }

                    // 解析连线
                    @SuppressWarnings("unchecked")
                    List<Map<String, Object>> edgesJson = (List<Map<String, Object>>) dag.get("edges");
                    if (edgesJson != null) {
                        List<WorkflowDefinitionDTO.WorkflowEdgeDTO> edges =
                                edgesJson.stream().map(this::convertToEdgeDTO).collect(Collectors.toList());
                        dto.setEdges(edges);
                    } else {
                        dto.setEdges(new ArrayList<>(16));
                    }
                } else {
                    dto.setNodes(new ArrayList<>(16));
                    dto.setEdges(new ArrayList<>(16));
                }
            } else {
                dto.setNodes(new ArrayList<>(16));
                dto.setEdges(new ArrayList<>(16));
            }
        } catch (Exception e) {
            log.error("解析 DAG JSON 失败", e);
            dto.setNodes(new ArrayList<>(16));
            dto.setEdges(new ArrayList<>(16));
        }

        return dto;
    }

    /**
     * 将节点 JSON 数据转换为节点 DTO。
     *
     * <p>从 JSON 中提取节点的标识、类型、名称、审批人配置、超时配置与坐标位置等字段。
     *
     * @param json 节点 JSON 数据
     * @return 节点 DTO
     */
    private WorkflowDefinitionDTO.WorkflowNodeDTO convertToNodeDTO(Map<String, Object> json) {
        WorkflowDefinitionDTO.WorkflowNodeDTO node = new WorkflowDefinitionDTO.WorkflowNodeDTO();
        node.setNodeId((String) json.get("nodeId"));
        node.setNodeType((String) json.get("nodeType"));
        node.setNodeName((String) json.get("nodeName"));
        node.setApproverType((String) json.get("approverType"));
        node.setApproverValue((String) json.get("approverValue"));
        node.setApprovalStrategy((String) json.get("approvalStrategy"));
        node.setTimeoutHours((Integer) json.get("timeoutHours"));
        node.setTimeoutAction((String) json.get("timeoutAction"));

        @SuppressWarnings("unchecked")
        Map<String, Object> position = (Map<String, Object>) json.get("position");
        node.setPosition(position != null ? position : new HashMap<>(16));

        return node;
    }

    /**
     * 将连线 JSON 数据转换为连线 DTO。
     *
     * <p>从 JSON 中提取连线的标识、源节点、目标节点与流转条件字段。
     *
     * @param json 连线 JSON 数据
     * @return 连线 DTO
     */
    private WorkflowDefinitionDTO.WorkflowEdgeDTO convertToEdgeDTO(Map<String, Object> json) {
        WorkflowDefinitionDTO.WorkflowEdgeDTO edge = new WorkflowDefinitionDTO.WorkflowEdgeDTO();
        edge.setEdgeId((String) json.get("edgeId"));
        edge.setSourceNodeId((String) json.get("sourceNodeId"));
        edge.setTargetNodeId((String) json.get("targetNodeId"));
        edge.setCondition((String) json.get("condition"));
        return edge;
    }
}

package com.apex.scaffold.workflow.application.query;

import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.workflow.application.dto.WorkflowStatisticsDTO;
import com.apex.scaffold.workflow.application.dto.WorkflowTrendDTO;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.ProcessInstanceMapper;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.TaskMapper;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;

/**
 * 工作流统计服务。
 *
 * <p>提供流程统计数据、趋势分析等功能。</p>
 *
 * <p>该服务基于响应式编程模型，所有统计查询方法均返回 {@link Mono}，
 * 内部对 MyBatis-Plus 的阻塞式 Mapper 统计调用统一通过
 * {@link BlockingIoSchedulers#jdbc()} 调度器承载，避免阻塞 Netty 事件循环线程。
 *
 * <h2>核心功能</h2>
 * <ul>
 *   <li>工作流统计概览：今日发起数、运行中总数、待办任务数、异常计数、平均完成时长等</li>
 *   <li>工作流趋势分析：按日统计最近 N 天的发起数量与完成数量</li>
 * </ul>
 *
 * @author Apex Team
 * @version 1.4.0
 * @since 1.4.0
 */
@Service
@RequiredArgsConstructor
public class WorkflowStatisticsService {

    /** 流程实例 Mapper，负责流程实例表的统计查询 */
    private final ProcessInstanceMapper processInstanceMapper;

    /** 任务 Mapper，负责任务表的统计查询 */
    private final TaskMapper taskMapper;

    /**
     * 获取工作流统计概览。
     *
     * <p>聚合今日发起流程数、运行中总数、待办任务总数、已挂起流程数、已超时任务数、
     * 已转办任务数、平均完成时长以及流程状态分布等指标，
     * 供监控页面展示整体运行状况。
     *
     * @return 统计概览 DTO
     */
    public Mono<WorkflowStatisticsDTO> getStatistics() {
        return Mono.fromCallable(() -> {
                    WorkflowStatisticsDTO stats = new WorkflowStatisticsDTO();

                    // 今日发起流程数
                    LocalDateTime todayStart = LocalDateTime.of(LocalDate.now(), LocalTime.MIN);
                    LocalDateTime todayEnd = LocalDateTime.of(LocalDate.now(), LocalTime.MAX);
                    Integer todayStarted = processInstanceMapper.countTodayStarted(todayStart, todayEnd);
                    stats.setTodayStarted(todayStarted != null ? todayStarted : 0);

                    Integer runningTotal = processInstanceMapper.countByStatus("RUNNING");
                    stats.setRunningTotal(runningTotal != null ? runningTotal : 0);

                    Integer suspendedCount = processInstanceMapper.countSuspended();
                    stats.setSuspendedCount(suspendedCount != null ? suspendedCount : 0);

                    Integer pendingTaskTotal = taskMapper.countPendingTasks();
                    stats.setPendingTaskTotal(pendingTaskTotal != null ? pendingTaskTotal : 0);

                    Integer timeoutCount = taskMapper.countTimeoutTasks(LocalDateTime.now());
                    stats.setTimeoutCount(timeoutCount != null ? timeoutCount : 0);

                    Integer transferredCount = taskMapper.countTransferredTasks();
                    stats.setTransferredCount(transferredCount != null ? transferredCount : 0);

                    Long avgSeconds = processInstanceMapper.avgCompletionSeconds();
                    stats.setAvgCompletionSeconds(avgSeconds != null ? avgSeconds : 0L);

                    // 转换状态分布 List<Map> 为 Map<String, Integer>
                    List<Map<String, Object>> statusList = processInstanceMapper.statusDistribution();
                    Map<String, Integer> statusMap = new HashMap<>(16);
                    if (statusList != null) {
                        for (Map<String, Object> row : statusList) {
                            String status = (String) row.get("status");
                            Object countObj = row.get("count");
                            Integer count =
                                    countObj instanceof Long ? ((Long) countObj).intValue() : (Integer) countObj;
                            statusMap.put(status, count);
                        }
                    }
                    stats.setStatusDistribution(statusMap);

                    return stats;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取工作流趋势数据（最近N天）。
     *
     * <p>按日统计给定天数范围内的每日流程发起数量与完成数量，
     * 三个列表（日期、发起数、完成数）索引一一对应，供趋势图表展示。
     *
     * @param days 天数，默认7天
     * @return 趋势 DTO
     */
    public Mono<WorkflowTrendDTO> getTrend(int days) {
        return Mono.fromCallable(() -> {
                    WorkflowTrendDTO trend = new WorkflowTrendDTO();
                    List<String> dates = new ArrayList<>(16);
                    List<Integer> startedCounts = new ArrayList<>(16);
                    List<Integer> completedCounts = new ArrayList<>(16);

                    LocalDate today = LocalDate.now();
                    for (int i = days - 1; i >= 0; i--) {
                        LocalDate date = today.minusDays(i);
                        dates.add(date.toString());

                        LocalDateTime dayStart = LocalDateTime.of(date, LocalTime.MIN);
                        LocalDateTime dayEnd = LocalDateTime.of(date, LocalTime.MAX);

                        // 转换 List<Map> 为 Map<LocalDate, Integer>
                        List<Map<String, Object>> startedList =
                                processInstanceMapper.countStartedByDateRange(dayStart, dayEnd);
                        List<Map<String, Object>> completedList =
                                processInstanceMapper.countCompletedByDateRange(dayStart, dayEnd);

                        Map<LocalDate, Integer> startedByDate = convertToDateMap(startedList);
                        Map<LocalDate, Integer> completedByDate = convertToDateMap(completedList);

                        startedCounts.add(startedByDate.getOrDefault(date, 0));
                        completedCounts.add(completedByDate.getOrDefault(date, 0));
                    }

                    trend.setDates(dates);
                    trend.setStartedCounts(startedCounts);
                    trend.setCompletedCounts(completedCounts);
                    return trend;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 转换 List&lt;Map&gt; 为 Map&lt;LocalDate, Integer&gt;。
     *
     * <p>将统计查询返回的行集合转换为以日期为键、数量为值的映射。
     * 兼容 MySQL DATE() 返回的 {@link java.sql.Date} 以及直接返回的 {@link LocalDate} 两种类型。
     *
     * @param list 统计查询结果行集合
     * @return 以日期为键、数量为值的映射
     */
    private Map<LocalDate, Integer> convertToDateMap(List<Map<String, Object>> list) {
        Map<LocalDate, Integer> result = new HashMap<>(16);
        if (list != null) {
            for (Map<String, Object> row : list) {
                Object dateObj = row.get("date");
                Object countObj = row.get("count");

                // MySQL DATE() 返回 java.sql.Date
                LocalDate date = null;
                if (dateObj instanceof java.sql.Date) {
                    date = ((java.sql.Date) dateObj).toLocalDate();
                } else if (dateObj instanceof LocalDate) {
                    date = (LocalDate) dateObj;
                }

                Integer count = countObj instanceof Long ? ((Long) countObj).intValue() : (Integer) countObj;

                if (date != null && count != null) {
                    result.put(date, count);
                }
            }
        }
        return result;
    }
}

package com.apex.scaffold.workflow.infrastructure.persistence.po;

import com.apex.scaffold.common.persistence.po.BasePO;
import com.baomidou.mybatisplus.annotation.TableName;
import java.time.LocalDateTime;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.NoArgsConstructor;
import lombok.experimental.SuperBuilder;

/**
 * 流程任务持久化对象（PO）。
 *
 * <p>映射数据库表 {@code wf_task}，存储工作流待办任务的完整信息。
 * 继承 {@link BasePO} 获得主键、创建/更新时间、乐观锁版本与逻辑删除等通用字段。</p>
 *
 * <h2>字段说明</h2>
 * <ul>
 *   <li>{@code timeoutAt}：超时时间，对应数据库字段 {@code timeout_at}。</li>
 *   <li>{@code timeoutStrategy}：超时策略，对应数据库字段 {@code timeout_strategy}。</li>
 *   <li>{@code transferredFrom}：转办来源，对应数据库字段 {@code transferred_from}。</li>
 * </ul>
 *
 * @author Apex Team
 * @version 1.3.0
 * @since 1.0.0
 * @see com.apex.scaffold.workflow.domain.model.Task
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
@SuperBuilder
@EqualsAndHashCode(callSuper = true)
@TableName("wf_task")
public class TaskPO extends BasePO {

    /** 租户 ID，用于多租户数据隔离。 */
    private Long tenantId;

    /** 所属流程实例 ID。 */
    private Long processInstanceId;

    /** 节点编码，该任务所处的流程节点。 */
    private String nodeCode;

    /** 任务名称，当前节点的展示名称。 */
    private String taskName;

    /** 待办人用户 ID。 */
    private Long assigneeId;

    /** 任务状态，取值参见领域模型 {@code Task} 状态说明。 */
    private String status;

    /** 处理截止时间，对应数据库字段 {@code due_time}。 */
    private LocalDateTime dueTime;

    /** 完成时间，对应数据库字段 {@code complete_time}。 */
    private LocalDateTime completeTime;

    /** 备注信息。 */
    private String remark;

    /** 超时时间点。 */
    private LocalDateTime timeoutAt;

    /** 超时策略，取值参见领域模型 {@code Task} 超时策略说明。 */
    private String timeoutStrategy;

    /** 转办来源用户 ID，未转办时为 {@code null}。 */
    private Long transferredFrom;

    /**
     * 获取节点 ID（兼容方法，实际返回 {@link #nodeCode} 字段值）。
     *
     * @return 节点 ID
     */
    public String getNodeId() {
        return nodeCode;
    }

    /**
     * 设置节点 ID（兼容方法，实际写入 {@link #nodeCode} 字段）。
     *
     * @param nodeId 节点 ID
     */
    public void setNodeId(String nodeId) {
        this.nodeCode = nodeId;
    }
}

package com.apex.scaffold.workflow.infrastructure.persistence.mapper;

import com.apex.scaffold.workflow.infrastructure.persistence.po.TaskPO;
import com.baomidou.mybatisplus.core.mapper.BaseMapper;
import java.time.LocalDateTime;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;

/**
 * 流程任务 MyBatis Mapper 接口。
 *
 * <p>基于 MyBatis-Plus {@link BaseMapper}，提供流程任务持久化对象
 * {@link TaskPO} 的基础 CRUD 操作，并额外提供用于超时处理与监控统计的计数查询。</p>
 *
 * @author Apex Team
 * @version 1.0.0
 * @since 1.0.0
 */
@Mapper
public interface TaskMapper extends BaseMapper<TaskPO> {

    /**
     * 统计处于待处理（PENDING）状态的任务数量。
     *
     * @return 待处理任务数量
     */
    @Select("SELECT COUNT(*) FROM wf_task WHERE status = 'PENDING' AND deleted = 0")
    Integer countPendingTasks();

    /**
     * 统计截至指定时刻已超时且尚未处理的任务数量。
     *
     * @param now 当前时刻
     * @return 超时未处理任务数量
     */
    @Select(
            "SELECT COUNT(*) FROM wf_task WHERE status = 'PENDING' AND timeout_at IS NOT NULL AND timeout_at <= #{now} AND timeout_handled = 0 AND deleted = 0")
    Integer countTimeoutTasks(@Param("now") LocalDateTime now);

    /**
     * 统计发生转办的任务数量。
     *
     * @return 转办任务数量
     */
    @Select("SELECT COUNT(*) FROM wf_task WHERE transferred_from IS NOT NULL AND deleted = 0")
    Integer countTransferredTasks();
}

package com.apex.scaffold.workflow.infrastructure.persistence.repository;

import com.apex.scaffold.common.persistence.util.ConditionUtil;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.workflow.domain.model.Task;
import com.apex.scaffold.workflow.domain.repository.TaskRepository;
import com.apex.scaffold.workflow.infrastructure.persistence.converter.TaskPoConverter;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.TaskMapper;
import com.apex.scaffold.workflow.infrastructure.persistence.po.TaskPO;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Repository;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

/**
 * 流程任务仓储实现。
 *
 * <p>基于 MyBatis-Plus 实现流程任务仓储接口 {@link TaskRepository}，
 * 负责任务领域对象与数据库表 {@code wf_task} 之间的映射与转换。</p>
 *
 * <h2>阻塞操作隔离</h2>
 * <p>所有数据库查询操作通过 {@link BlockingIoSchedulers#jdbc()} 调度器执行，
 * 避免阻塞响应式流的事件循环线程。</p>
 *
 * @author Apex Team
 * @version 1.3.0
 * @since 1.0.0
 */
@Repository
@RequiredArgsConstructor
public class TaskRepositoryImpl implements TaskRepository {

    /** 任务 MyBatis Mapper。 */
    private final TaskMapper taskMapper;

    /** 任务 PO 转换器。 */
    private final TaskPoConverter taskPoConverter;

    /** {@inheritDoc} */
    @Override
    public Mono<Task> findById(Long id) {
        return Mono.fromCallable(() -> taskMapper.selectById(id))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(taskPoConverter.toEntity(po)));
    }

    /** {@inheritDoc} */
    @Override
    public Mono<List<Task>> findByProcessInstanceId(Long processInstanceId) {
        return Mono.fromCallable(() -> taskMapper.selectList(ConditionUtil.lambda(TaskPO.class)
                        .eq(TaskPO::getProcessInstanceId, processInstanceId)
                        .orderByDesc(TaskPO::getCreateTime)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .map(taskPoConverter::toEntityList);
    }

    /** {@inheritDoc} */
    @Override
    public Mono<List<Task>> findByAssignee(Long assigneeId) {
        return Mono.fromCallable(() -> taskMapper.selectList(ConditionUtil.lambda(TaskPO.class)
                        .eq(TaskPO::getAssigneeId, assigneeId)
                        .eq(TaskPO::getStatus, "PENDING")
                        .orderByDesc(TaskPO::getCreateTime)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .map(taskPoConverter::toEntityList);
    }

    /** {@inheritDoc} */
    @Override
    public Flux<Task> findPendingTasks() {
        return Mono.fromCallable(() -> taskMapper.selectList(ConditionUtil.lambda(TaskPO.class)
                        .eq(TaskPO::getStatus, "PENDING")
                        .isNotNull(TaskPO::getTimeoutAt)
                        .orderByAsc(TaskPO::getTimeoutAt)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMapMany(poList -> Flux.fromIterable(taskPoConverter.toEntityList(poList)));
    }

    /** {@inheritDoc} */
    @Override
    public Mono<Integer> insert(Task entity) {
        return Mono.fromCallable(() -> taskMapper.insert(taskPoConverter.toPo(entity)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /** {@inheritDoc} */
    @Override
    public Mono<Integer> updateById(Task entity) {
        return Mono.fromCallable(() -> taskMapper.updateById(taskPoConverter.toPo(entity)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /** {@inheritDoc} */
    @Override
    public Mono<Integer> deleteById(Long id) {
        return Mono.fromCallable(() -> taskMapper.deleteById(id)).subscribeOn(BlockingIoSchedulers.jdbc());
    }
}

package com.apex.scaffold.workflow.application.query;

import com.apex.scaffold.common.dto.PageResponse;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.workflow.application.dto.WorkflowDefinitionDTO;
import com.apex.scaffold.workflow.application.dto.WorkflowInstanceDTO;
import com.apex.scaffold.workflow.application.dto.WorkflowInstanceDetailDTO;
import com.apex.scaffold.workflow.application.dto.WorkflowTaskDTO;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.ProcessInstanceMapper;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.TaskMapper;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.WorkflowDefinitionMapper;
import com.apex.scaffold.workflow.infrastructure.persistence.po.ProcessInstancePO;
import com.apex.scaffold.workflow.infrastructure.persistence.po.TaskPO;
import com.apex.scaffold.workflow.infrastructure.persistence.po.WorkflowDefinitionPO;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.core.metadata.IPage;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;

/**
 * 工作流查询服务。
 *
 * <p>提供流程实例查询、任务查询、详情查询等功能。</p>
 *
 * <p>该服务基于响应式编程模型，所有查询方法均返回 {@link Mono}，
 * 内部对 MyBatis-Plus 的阻塞式 Mapper 调用统一通过
 * {@link BlockingIoSchedulers#jdbc()} 调度器承载，避免阻塞 Netty 事件循环线程。
 *
 * <h2>核心功能</h2>
 * <ul>
 *   <li>流程实例分页查询与状态过滤</li>
 *   <li>流程实例详情聚合查询（定义 + 任务 + 当前节点）</li>
 *   <li>用户待办任务分页查询</li>
 *   <li>流程定义详情查询（用于设计器加载）</li>
 *   <li>数据库持久化对象向应用 DTO 的转换</li>
 * </ul>
 *
 * @author Apex Team
 * @version 1.4.0
 * @since 1.4.0
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class WorkflowQueryService {

    /** 流程实例 Mapper，负责流程实例表的持久化查询 */
    private final ProcessInstanceMapper processInstanceMapper;

    /** 任务 Mapper，负责任务表的持久化查询 */
    private final TaskMapper taskMapper;

    /** 工作流定义 Mapper，负责流程定义表的持久化查询 */
    private final WorkflowDefinitionMapper workflowDefinitionMapper;

    /** Jackson JSON 解析器，用于解析流程定义的 DAG JSON 结构 */
    private final ObjectMapper objectMapper;

    /**
     * 分页查询流程实例列表。
     *
     * <p>按状态过滤流程实例，按创建时间倒序排列。该方法仅为便捷重载，
     * 内部委托给携带发起人过滤参数的完整版本。
     *
     * @param status 状态过滤（可选）
     * @param pageNum 页码
     * @param pageSize 每页大小
     * @return 分页结果
     */
    public Mono<PageResponse<WorkflowInstanceDTO>> listInstances(String status, int pageNum, int pageSize) {
        return listInstances(pageNum, pageSize, status, null);
    }

    /**
     * 分页查询流程实例列表（完整版本）。
     *
     * <p>支持按状态与发起人双重过滤，查询结果按创建时间倒序排列。
     * 每条实例记录会额外查询其所属工作流定义以补充流程编码信息。
     *
     * @param pageNum 页码
     * @param pageSize 每页大小
     * @param status 状态过滤（可选）
     * @param initiatorId 发起人过滤（可选）
     * @return 分页结果
     */
    public Mono<PageResponse<WorkflowInstanceDTO>> listInstances(
            int pageNum, int pageSize, String status, Long initiatorId) {
        return Mono.fromCallable(() -> {
                    log.info(
                            "开始查询工作流实例列表: pageNum={}, pageSize={}, status={}, initiatorId={}",
                            pageNum,
                            pageSize,
                            status,
                            initiatorId);

                    Page<ProcessInstancePO> page = new Page<>(pageNum, pageSize);
                    LambdaQueryWrapper<ProcessInstancePO> wrapper = new LambdaQueryWrapper<>();

                    if (status != null && !status.isEmpty()) {
                        wrapper.eq(ProcessInstancePO::getStatus, status);
                    }
                    if (initiatorId != null) {
                        wrapper.eq(ProcessInstancePO::getInitiatorId, initiatorId);
                    }
                    wrapper.orderByDesc(ProcessInstancePO::getCreateTime);

                    IPage<ProcessInstancePO> poPage = processInstanceMapper.selectPage(page, wrapper);
                    log.info("查询到 {} 条记录，总数: {}", poPage.getRecords().size(), poPage.getTotal());

                    // 转换为 DTO，需要查询工作流定义获取 processCode
                    List<WorkflowInstanceDTO> dtoList = poPage.getRecords().stream()
                            .map(po -> {
                                WorkflowDefinitionPO definition =
                                        workflowDefinitionMapper.selectById(po.getWorkflowDefinitionId());
                                return convertToInstanceDTO(po, definition);
                            })
                            .collect(Collectors.toList());

                    log.info("转换完成，返回 {} 条 DTO", dtoList.size());
                    return PageResponse.of(dtoList, poPage.getTotal(), pageNum, pageSize);
                })
                .doOnError(error -> log.error("查询工作流实例列表失败", error))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取流程实例详情（包含定义和任务）。
     *
     * <p>聚合流程实例基本信息、流程定义、任务列表与当前节点，
     * 用于详情页完整渲染。若实例不存在则返回 null。
     *
     * @param instanceId 流程实例 ID
     * @return 流程详情 DTO
     */
    public Mono<WorkflowInstanceDetailDTO> getInstanceDetail(Long instanceId) {
        return Mono.fromCallable(() -> {
                    WorkflowInstanceDetailDTO detail = new WorkflowInstanceDetailDTO();

                    // 查询流程实例
                    ProcessInstancePO processInstance = processInstanceMapper.selectById(instanceId);
                    if (processInstance == null) {
                        return null;
                    }

                    // 查询流程定义
                    WorkflowDefinitionPO workflowDefinition =
                            workflowDefinitionMapper.selectById(processInstance.getWorkflowDefinitionId());
                    detail.setInstance(convertToInstanceDTO(processInstance, workflowDefinition));
                    detail.setCurrentNodeId(processInstance.getCurrentNodeCode());

                    if (workflowDefinition != null) {
                        detail.setDefinition(convertToDefinitionDTO(workflowDefinition));
                    }

                    // 查询任务列表
                    List<TaskPO> taskList = taskMapper.selectList(new LambdaQueryWrapper<TaskPO>()
                            .eq(TaskPO::getProcessInstanceId, instanceId)
                            .orderByDesc(TaskPO::getCreateTime));
                    List<WorkflowTaskDTO> tasks =
                            taskList.stream().map(this::convertToTaskDTO).collect(Collectors.toList());
                    detail.setTasks(tasks);

                    return detail;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 查询用户待办任务。
     *
     * <p>按办理人 ID 查询状态为 PENDING 的待办任务，按创建时间倒序分页返回。
     *
     * @param assigneeId 办理人 ID
     * @param pageNum 页码
     * @param pageSize 每页大小
     * @return 分页结果
     */
    public Mono<PageResponse<WorkflowTaskDTO>> listMyTasks(Long assigneeId, int pageNum, int pageSize) {
        return com.apex.scaffold.common.context.TenantContext.withTenant(Mono.fromCallable(() -> {
                    Page<TaskPO> page = new Page<>(pageNum, pageSize);
                    LambdaQueryWrapper<TaskPO> wrapper = new LambdaQueryWrapper<>();
                    wrapper.eq(TaskPO::getAssigneeId, assigneeId)
                            .eq(TaskPO::getStatus, "PENDING")
                            .orderByDesc(TaskPO::getCreateTime);

                    com.apex.scaffold.common.context.TenantContext.currentTenantId()
                            .ifPresent(tenantId -> wrapper.eq(TaskPO::getTenantId, tenantId));
                    IPage<TaskPO> poPage = taskMapper.selectPage(page, wrapper);

                    List<WorkflowTaskDTO> dtoList = poPage.getRecords().stream()
                            .map(this::convertToTaskDTO)
                            .collect(Collectors.toList());

                    return PageResponse.of(dtoList, poPage.getTotal(), pageNum, pageSize);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc()));
    }

    /**
     * 按任务 ID 查询任务详情。
     *
     * <p>用于在工作流事件发布等场景补充任务信息（所属流程实例、节点编码等）。
     * 主键不存在时返回空 {@link Mono}。
     *
     * @param taskId 任务 ID
     * @return 任务 DTO；任务不存在时返回 {@link Mono#empty()}
     */
    public Mono<WorkflowTaskDTO> getTaskById(Long taskId) {
        return Mono.fromCallable(() -> {
                    TaskPO po = taskMapper.selectById(taskId);
                    return po == null ? null : convertToTaskDTO(po);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取流程定义详情（用于设计器加载）。
     *
     * <p>根据流程编码查询唯一的流程定义，并解析其 DAG JSON 结构。
     *
     * @param workflowCode 流程编码
     * @return 流程定义 DTO
     */
    public Mono<WorkflowDefinitionDTO> getDefinitionDetail(String workflowCode) {
        return Mono.fromCallable(() -> {
                    WorkflowDefinitionPO workflowDefinition =
                            workflowDefinitionMapper.selectOne(new LambdaQueryWrapper<WorkflowDefinitionPO>()
                                    .eq(WorkflowDefinitionPO::getWorkflowCode, workflowCode));
                    if (workflowDefinition == null) {
                        return null;
                    }
                    return convertToDefinitionDTO(workflowDefinition);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取流程定义详情（根据定义 ID）。
     *
     * <p>根据流程定义主键 ID 查询流程定义，并解析其 DAG JSON 结构。
     *
     * @param definitionId 流程定义 ID
     * @return 流程定义 DTO
     */
    public Mono<WorkflowDefinitionDTO> getDefinitionDetail(Long definitionId) {
        return Mono.fromCallable(() -> {
                    WorkflowDefinitionPO workflowDefinition = workflowDefinitionMapper.selectById(definitionId);
                    if (workflowDefinition == null) {
                        return null;
                    }
                    return convertToDefinitionDTO(workflowDefinition);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 将流程实例持久化对象转换为流程实例 DTO。
     *
     * <p>流程编码取自关联的工作流定义而非业务键；发起人姓名暂采用简化规则拼接。
     *
     * @param po 流程实例持久化对象
     * @param definition 关联的工作流定义持久化对象（可能为 null）
     * @return 流程实例 DTO
     */
    private WorkflowInstanceDTO convertToInstanceDTO(ProcessInstancePO po, WorkflowDefinitionPO definition) {
        WorkflowInstanceDTO dto = new WorkflowInstanceDTO();
        dto.setId(po.getId());
        dto.setDefinitionId(po.getWorkflowDefinitionId());
        // 从工作流定义获取 processCode，而不是使用 businessKey
        dto.setProcessCode(definition != null ? definition.getWorkflowCode() : null);
        dto.setTitle(po.getRemark() != null ? po.getRemark() : "流程实例-" + po.getId());
        dto.setStatus(po.getStatus());
        dto.setSuspended(Boolean.TRUE.equals(po.getSuspended()) || "SUSPENDED".equals(po.getStatus()));
        dto.setInitiatorId(po.getInitiatorId());
        // 简化映射，实际应关联用户表
        dto.setInitiatorName("用户-" + po.getInitiatorId());
        dto.setBusinessKey(po.getBusinessKey());
        dto.setCurrentNodeId(po.getCurrentNodeCode());
        dto.setStartTime(po.getStartTime());
        dto.setEndTime(po.getEndTime());
        dto.setCreateTime(po.getCreateTime());
        return dto;
    }

    /**
     * 将任务持久化对象转换为任务 DTO。
     *
     * <p>任务类型暂固定为 USER_TASK，办理人姓名采用简化规则拼接。
     *
     * @param po 任务持久化对象
     * @return 任务 DTO
     */
    private WorkflowTaskDTO convertToTaskDTO(TaskPO po) {
        WorkflowTaskDTO dto = new WorkflowTaskDTO();
        dto.setId(po.getId());
        dto.setInstanceId(po.getProcessInstanceId());
        dto.setTaskName(po.getTaskName());
        // 简化映射
        dto.setTaskType("USER_TASK");
        dto.setStatus(po.getStatus());
        dto.setAssigneeId(po.getAssigneeId());
        // 简化映射
        dto.setAssigneeName("用户-" + po.getAssigneeId());
        dto.setComment(po.getRemark());
        dto.setNodeId(po.getNodeCode());
        dto.setStartTime(po.getCreateTime());
        dto.setCompletedTime(po.getCompleteTime());
        dto.setCreateTime(po.getCreateTime());
        return dto;
    }

    /**
     * 将工作流定义持久化对象转换为定义 DTO。
     *
     * <p>会解析 {@code node_definition} 字段中的 DAG JSON 结构，
     * 提取其中节点列表与连线列表。解析失败时返回空的节点与连线列表。
     *
     * @param po 工作流定义持久化对象
     * @return 流程定义 DTO
     */
    private WorkflowDefinitionDTO convertToDefinitionDTO(WorkflowDefinitionPO po) {
        WorkflowDefinitionDTO dto = new WorkflowDefinitionDTO();
        dto.setId(po.getId());
        dto.setCode(po.getWorkflowCode());
        dto.setName(po.getWorkflowName());
        dto.setDescription(po.getDescription());
        dto.setVersion(po.getVersion());
        dto.setEnabled(po.getEnabled() == 1);

        // 解析 DAG JSON，增加 null 防护
        try {
            if (po.getNodeDefinition() != null && !po.getNodeDefinition().isEmpty()) {
                Map<String, Object> dag =
                        objectMapper.readValue(po.getNodeDefinition(), new TypeReference<Map<String, Object>>() {});

                // 解析节点，增加 null 检查
                if (dag != null) {
                    @SuppressWarnings("unchecked")
                    List<Map<String, Object>> nodesJson = (List<Map<String, Object>>) dag.get("nodes");
                    if (nodesJson != null) {
                        List<WorkflowDefinitionDTO.WorkflowNodeDTO> nodes =
                                nodesJson.stream().map(this::convertToNodeDTO).collect(Collectors.toList());
                        dto.setNodes(nodes);
                    } else {
                        dto.setNodes(new ArrayList<>(16));
                    }

                    // 解析连线
                    @SuppressWarnings("unchecked")
                    List<Map<String, Object>> edgesJson = (List<Map<String, Object>>) dag.get("edges");
                    if (edgesJson != null) {
                        List<WorkflowDefinitionDTO.WorkflowEdgeDTO> edges =
                                edgesJson.stream().map(this::convertToEdgeDTO).collect(Collectors.toList());
                        dto.setEdges(edges);
                    } else {
                        dto.setEdges(new ArrayList<>(16));
                    }
                } else {
                    dto.setNodes(new ArrayList<>(16));
                    dto.setEdges(new ArrayList<>(16));
                }
            } else {
                dto.setNodes(new ArrayList<>(16));
                dto.setEdges(new ArrayList<>(16));
            }
        } catch (Exception e) {
            log.error("解析 DAG JSON 失败", e);
            dto.setNodes(new ArrayList<>(16));
            dto.setEdges(new ArrayList<>(16));
        }

        return dto;
    }

    /**
     * 将节点 JSON 数据转换为节点 DTO。
     *
     * <p>从 JSON 中提取节点的标识、类型、名称、审批人配置、超时配置与坐标位置等字段。
     *
     * @param json 节点 JSON 数据
     * @return 节点 DTO
     */
    private WorkflowDefinitionDTO.WorkflowNodeDTO convertToNodeDTO(Map<String, Object> json) {
        WorkflowDefinitionDTO.WorkflowNodeDTO node = new WorkflowDefinitionDTO.WorkflowNodeDTO();
        node.setNodeId((String) json.get("nodeId"));
        node.setNodeType((String) json.get("nodeType"));
        node.setNodeName((String) json.get("nodeName"));
        node.setApproverType((String) json.get("approverType"));
        node.setApproverValue((String) json.get("approverValue"));
        node.setApprovalStrategy((String) json.get("approvalStrategy"));
        node.setTimeoutHours((Integer) json.get("timeoutHours"));
        node.setTimeoutAction((String) json.get("timeoutAction"));

        @SuppressWarnings("unchecked")
        Map<String, Object> position = (Map<String, Object>) json.get("position");
        node.setPosition(position != null ? position : new HashMap<>(16));

        return node;
    }

    /**
     * 将连线 JSON 数据转换为连线 DTO。
     *
     * <p>从 JSON 中提取连线的标识、源节点、目标节点与流转条件字段。
     *
     * @param json 连线 JSON 数据
     * @return 连线 DTO
     */
    private WorkflowDefinitionDTO.WorkflowEdgeDTO convertToEdgeDTO(Map<String, Object> json) {
        WorkflowDefinitionDTO.WorkflowEdgeDTO edge = new WorkflowDefinitionDTO.WorkflowEdgeDTO();
        edge.setEdgeId((String) json.get("edgeId"));
        edge.setSourceNodeId((String) json.get("sourceNodeId"));
        edge.setTargetNodeId((String) json.get("targetNodeId"));
        edge.setCondition((String) json.get("condition"));
        return edge;
    }
}

package com.apex.scaffold.workflow.application.query;

import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.workflow.application.dto.WorkflowStatisticsDTO;
import com.apex.scaffold.workflow.application.dto.WorkflowTrendDTO;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.ProcessInstanceMapper;
import com.apex.scaffold.workflow.infrastructure.persistence.mapper.TaskMapper;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;

/**
 * 工作流统计服务。
 *
 * <p>提供流程统计数据、趋势分析等功能。</p>
 *
 * <p>该服务基于响应式编程模型，所有统计查询方法均返回 {@link Mono}，
 * 内部对 MyBatis-Plus 的阻塞式 Mapper 统计调用统一通过
 * {@link BlockingIoSchedulers#jdbc()} 调度器承载，避免阻塞 Netty 事件循环线程。
 *
 * <h2>核心功能</h2>
 * <ul>
 *   <li>工作流统计概览：今日发起数、运行中总数、待办任务数、异常计数、平均完成时长等</li>
 *   <li>工作流趋势分析：按日统计最近 N 天的发起数量与完成数量</li>
 * </ul>
 *
 * @author Apex Team
 * @version 1.4.0
 * @since 1.4.0
 */
@Service
@RequiredArgsConstructor
public class WorkflowStatisticsService {

    /** 流程实例 Mapper，负责流程实例表的统计查询 */
    private final ProcessInstanceMapper processInstanceMapper;

    /** 任务 Mapper，负责任务表的统计查询 */
    private final TaskMapper taskMapper;

    /**
     * 获取工作流统计概览。
     *
     * <p>聚合今日发起流程数、运行中总数、待办任务总数、已挂起流程数、已超时任务数、
     * 已转办任务数、平均完成时长以及流程状态分布等指标，
     * 供监控页面展示整体运行状况。
     *
     * @return 统计概览 DTO
     */
    public Mono<WorkflowStatisticsDTO> getStatistics() {
        return Mono.fromCallable(() -> {
                    WorkflowStatisticsDTO stats = new WorkflowStatisticsDTO();

                    // 今日发起流程数
                    LocalDateTime todayStart = LocalDateTime.of(LocalDate.now(), LocalTime.MIN);
                    LocalDateTime todayEnd = LocalDateTime.of(LocalDate.now(), LocalTime.MAX);
                    Integer todayStarted = processInstanceMapper.countTodayStarted(todayStart, todayEnd);
                    stats.setTodayStarted(todayStarted != null ? todayStarted : 0);

                    Integer runningTotal = processInstanceMapper.countByStatus("RUNNING");
                    stats.setRunningTotal(runningTotal != null ? runningTotal : 0);

                    Integer suspendedCount = processInstanceMapper.countSuspended();
                    stats.setSuspendedCount(suspendedCount != null ? suspendedCount : 0);

                    Integer pendingTaskTotal = taskMapper.countPendingTasks();
                    stats.setPendingTaskTotal(pendingTaskTotal != null ? pendingTaskTotal : 0);

                    Integer timeoutCount = taskMapper.countTimeoutTasks(LocalDateTime.now());
                    stats.setTimeoutCount(timeoutCount != null ? timeoutCount : 0);

                    Integer transferredCount = taskMapper.countTransferredTasks();
                    stats.setTransferredCount(transferredCount != null ? transferredCount : 0);

                    Long avgSeconds = processInstanceMapper.avgCompletionSeconds();
                    stats.setAvgCompletionSeconds(avgSeconds != null ? avgSeconds : 0L);

                    // 转换状态分布 List<Map> 为 Map<String, Integer>
                    List<Map<String, Object>> statusList = processInstanceMapper.statusDistribution();
                    Map<String, Integer> statusMap = new HashMap<>(16);
                    if (statusList != null) {
                        for (Map<String, Object> row : statusList) {
                            String status = (String) row.get("status");
                            Object countObj = row.get("count");
                            Integer count =
                                    countObj instanceof Long ? ((Long) countObj).intValue() : (Integer) countObj;
                            statusMap.put(status, count);
                        }
                    }
                    stats.setStatusDistribution(statusMap);

                    return stats;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 获取工作流趋势数据（最近N天）。
     *
     * <p>按日统计给定天数范围内的每日流程发起数量与完成数量，
     * 三个列表（日期、发起数、完成数）索引一一对应，供趋势图表展示。
     *
     * @param days 天数，默认7天
     * @return 趋势 DTO
     */
    public Mono<WorkflowTrendDTO> getTrend(int days) {
        return Mono.fromCallable(() -> {
                    WorkflowTrendDTO trend = new WorkflowTrendDTO();
                    List<String> dates = new ArrayList<>(16);
                    List<Integer> startedCounts = new ArrayList<>(16);
                    List<Integer> completedCounts = new ArrayList<>(16);

                    LocalDate today = LocalDate.now();
                    for (int i = days - 1; i >= 0; i--) {
                        LocalDate date = today.minusDays(i);
                        dates.add(date.toString());

                        LocalDateTime dayStart = LocalDateTime.of(date, LocalTime.MIN);
                        LocalDateTime dayEnd = LocalDateTime.of(date, LocalTime.MAX);

                        // 转换 List<Map> 为 Map<LocalDate, Integer>
                        List<Map<String, Object>> startedList =
                                processInstanceMapper.countStartedByDateRange(dayStart, dayEnd);
                        List<Map<String, Object>> completedList =
                                processInstanceMapper.countCompletedByDateRange(dayStart, dayEnd);

                        Map<LocalDate, Integer> startedByDate = convertToDateMap(startedList);
                        Map<LocalDate, Integer> completedByDate = convertToDateMap(completedList);

                        startedCounts.add(startedByDate.getOrDefault(date, 0));
                        completedCounts.add(completedByDate.getOrDefault(date, 0));
                    }

                    trend.setDates(dates);
                    trend.setStartedCounts(startedCounts);
                    trend.setCompletedCounts(completedCounts);
                    return trend;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 转换 List&lt;Map&gt; 为 Map&lt;LocalDate, Integer&gt;。
     *
     * <p>将统计查询返回的行集合转换为以日期为键、数量为值的映射。
     * 兼容 MySQL DATE() 返回的 {@link java.sql.Date} 以及直接返回的 {@link LocalDate} 两种类型。
     *
     * @param list 统计查询结果行集合
     * @return 以日期为键、数量为值的映射
     */
    private Map<LocalDate, Integer> convertToDateMap(List<Map<String, Object>> list) {
        Map<LocalDate, Integer> result = new HashMap<>(16);
        if (list != null) {
            for (Map<String, Object> row : list) {
                Object dateObj = row.get("date");
                Object countObj = row.get("count");

                // MySQL DATE() 返回 java.sql.Date
                LocalDate date = null;
                if (dateObj instanceof java.sql.Date) {
                    date = ((java.sql.Date) dateObj).toLocalDate();
                } else if (dateObj instanceof LocalDate) {
                    date = (LocalDate) dateObj;
                }

                Integer count = countObj instanceof Long ? ((Long) countObj).intValue() : (Integer) countObj;

                if (date != null && count != null) {
                    result.put(date, count);
                }
            }
        }
        return result;
    }
}

