package com.apex.scaffold.auth.domain.service;

import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.PrivateKey;
import java.security.PublicKey;
import java.security.SecureRandom;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Base64;
import java.util.List;
import java.util.UUID;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.redis.core.ReactiveRedisTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

/**
 * JWT密钥轮换服务
 *
 * <p>实现JWT签名密钥的自动轮换机制，提高系统安全性：</p>
 * <ul>
 *   <li>支持RSA-2048密钥对生成和轮换</li>
 *   <li>密钥轮换周期：30天（可配置）</li>
 *   <li>密钥宽限期：7天（旧密钥在宽限期内仍可验证JWT）</li>
 *   <li>使用Redis存储密钥对，支持分布式环境</li>
 *   <li>支持立即轮换（紧急响应密钥泄露）</li>
 * </ul>
 *
 * <p>密钥存储结构：</p>
 * <pre>
 * jwt:keys:current -> keyId (当前活跃密钥ID)
 * jwt:key:{keyId}:private -> Base64编码的私钥
 * jwt:key:{keyId}:public -> Base64编码的公钥
 * jwt:key:{keyId}:created -> 创建时间戳
 * jwt:keys:all -> Set(所有可用密钥ID，包括宽限期内的旧密钥)
 * </pre>
 *
 * @author Apex Security Team
 * @since 1.0.0
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class JwtKeyRotationService {

    private static final String REDIS_KEY_CURRENT = "jwt:keys:current";
    private static final String REDIS_KEY_ALL = "jwt:keys:all";
    private static final String REDIS_KEY_PREFIX = "jwt:key:";

    /**
     * 密钥轮换周期：30天
     */
    private static final long ROTATION_PERIOD_DAYS = 30;

    /**
     * 密钥宽限期：7天（旧密钥在宽限期内仍可用于验证）
     */
    private static final long GRACE_PERIOD_DAYS = 7;

    /**
     * RSA密钥长度
     */
    private static final int KEY_SIZE = 2048;

    private final ReactiveRedisTemplate<String, String> redisTemplate;

    /**
     * 初始化密钥对（系统启动时调用）
     * 如果Redis中没有密钥，则生成初始密钥对
     *
     * @return 初始化结果
     */
    public Mono<String> initializeKeys() {
        return getCurrentKeyId()
                .switchIfEmpty(Mono.defer(() -> {
                    log.info("检测到系统中没有JWT密钥，开始生成初始密钥对");
                    return rotateKeys().thenReturn("初始密钥对生成成功");
                }))
                .map(keyId -> "JWT密钥已就绪: keyId=" + keyId);
    }

    /**
     * 获取当前活跃的密钥ID
     *
     * @return 当前密钥ID，如果不存在则返回empty
     */
    public Mono<String> getCurrentKeyId() {
        return redisTemplate.opsForValue().get(REDIS_KEY_CURRENT);
    }

    /**
     * 获取当前活跃的私钥（用于签名JWT）
     *
     * @return 私钥对象
     */
    public Mono<PrivateKey> getCurrentPrivateKey() {
        return getCurrentKeyId()
                .flatMap(this::getPrivateKey)
                .switchIfEmpty(Mono.error(new IllegalStateException("JWT密钥未初始化")));
    }

    /**
     * 获取当前活跃的公钥（用于验证JWT）
     *
     * @return 公钥对象
     */
    public Mono<PublicKey> getCurrentPublicKey() {
        return getCurrentKeyId()
                .flatMap(this::getPublicKey)
                .switchIfEmpty(Mono.error(new IllegalStateException("JWT密钥未初始化")));
    }

    /**
     * 根据密钥ID获取公钥（用于验证旧JWT）
     *
     * @param keyId 密钥ID
     * @return 公钥对象
     */
    public Mono<PublicKey> getPublicKey(String keyId) {
        String redisKey = REDIS_KEY_PREFIX + keyId + ":public";
        return redisTemplate.opsForValue().get(redisKey).flatMap(encodedKey -> {
            try {
                byte[] keyBytes = Base64.getDecoder().decode(encodedKey);
                java.security.spec.X509EncodedKeySpec spec = new java.security.spec.X509EncodedKeySpec(keyBytes);
                java.security.KeyFactory keyFactory = java.security.KeyFactory.getInstance("RSA");
                return Mono.just(keyFactory.generatePublic(spec));
            } catch (Exception e) {
                return Mono.error(new RuntimeException("解析公钥失败: keyId=" + keyId, e));
            }
        });
    }

    /**
     * 根据密钥ID获取私钥
     *
     * @param keyId 密钥ID
     * @return 私钥对象
     */
    private Mono<PrivateKey> getPrivateKey(String keyId) {
        String redisKey = REDIS_KEY_PREFIX + keyId + ":private";
        return redisTemplate.opsForValue().get(redisKey).flatMap(encodedKey -> {
            try {
                byte[] keyBytes = Base64.getDecoder().decode(encodedKey);
                java.security.spec.PKCS8EncodedKeySpec spec = new java.security.spec.PKCS8EncodedKeySpec(keyBytes);
                java.security.KeyFactory keyFactory = java.security.KeyFactory.getInstance("RSA");
                return Mono.just(keyFactory.generatePrivate(spec));
            } catch (Exception e) {
                return Mono.error(new RuntimeException("解析私钥失败: keyId=" + keyId, e));
            }
        });
    }

    /**
     * 执行密钥轮换
     *
     * <p>轮换步骤：</p>
     * <ol>
     *   <li>生成新的RSA-2048密钥对</li>
     *   <li>将新密钥存储到Redis</li>
     *   <li>更新当前密钥ID</li>
     *   <li>将新密钥ID添加到可用密钥集合</li>
     *   <li>清理过期的旧密钥（超过宽限期）</li>
     * </ol>
     *
     * @return 新密钥ID
     */
    public Mono<String> rotateKeys() {
        return Mono.fromCallable(() -> {
                    log.info("开始JWT密钥轮换");

                    // 1. 生成新密钥对
                    KeyPairGenerator keyGen = KeyPairGenerator.getInstance("RSA");
                    keyGen.initialize(KEY_SIZE, new SecureRandom());
                    KeyPair keyPair = keyGen.generateKeyPair();

                    String newKeyId = "key-" + UUID.randomUUID().toString();
                    Instant now = Instant.now();

                    log.info("生成新密钥对成功: keyId={}, algorithm=RSA, keySize={}", newKeyId, KEY_SIZE);

                    return new Object[] {newKeyId, keyPair, now};
                })
                .flatMap(data -> {
                    String newKeyId = (String) data[0];
                    KeyPair keyPair = (KeyPair) data[1];
                    Instant now = (Instant) data[2];

                    // 2. 存储新密钥对到Redis
                    String privateKeyEncoded = Base64.getEncoder()
                            .encodeToString(keyPair.getPrivate().getEncoded());
                    String publicKeyEncoded = Base64.getEncoder()
                            .encodeToString(keyPair.getPublic().getEncoded());

                    return Mono.when(
                                    redisTemplate
                                            .opsForValue()
                                            .set(REDIS_KEY_PREFIX + newKeyId + ":private", privateKeyEncoded),
                                    redisTemplate
                                            .opsForValue()
                                            .set(REDIS_KEY_PREFIX + newKeyId + ":public", publicKeyEncoded),
                                    redisTemplate
                                            .opsForValue()
                                            .set(
                                                    REDIS_KEY_PREFIX + newKeyId + ":created",
                                                    String.valueOf(now.toEpochMilli())))
                            .then(Mono.just(newKeyId));
                })
                .flatMap(newKeyId -> {
                    // 3. 更新当前密钥ID
                    return redisTemplate
                            .opsForValue()
                            .set(REDIS_KEY_CURRENT, newKeyId)
                            .then(redisTemplate.opsForSet().add(REDIS_KEY_ALL, newKeyId))
                            .thenReturn(newKeyId);
                })
                .flatMap(newKeyId -> {
                    // 4. 清理过期的旧密钥
                    return cleanupExpiredKeys().thenReturn(newKeyId);
                })
                .doOnSuccess(newKeyId -> log.info("JWT密钥轮换成功: newKeyId={}", newKeyId))
                .doOnError(e -> log.error("JWT密钥轮换失败", e));
    }

    /**
     * 清理过期的旧密钥（超过宽限期）
     *
     * @return 清理结果
     */
    private Mono<Void> cleanupExpiredKeys() {
        Instant expirationTime = Instant.now().minus(ROTATION_PERIOD_DAYS + GRACE_PERIOD_DAYS, ChronoUnit.DAYS);

        return redisTemplate
                .opsForSet()
                .members(REDIS_KEY_ALL)
                .collectList()
                .flatMapMany(Flux::fromIterable)
                .flatMap(keyId -> {
                    String createdKey = REDIS_KEY_PREFIX + keyId + ":created";
                    return redisTemplate.opsForValue().get(createdKey).map(createdStr -> {
                        long createdMillis = Long.parseLong(createdStr);
                        Instant created = Instant.ofEpochMilli(createdMillis);
                        return new Object[] {keyId, created};
                    });
                })
                .filter(data -> {
                    Instant created = (Instant) data[1];
                    return created.isBefore(expirationTime);
                })
                .flatMap(data -> {
                    String keyId = (String) data[0];
                    log.info("删除过期JWT密钥: keyId={}", keyId);

                    return Mono.when(
                            redisTemplate.delete(REDIS_KEY_PREFIX + keyId + ":private"),
                            redisTemplate.delete(REDIS_KEY_PREFIX + keyId + ":public"),
                            redisTemplate.delete(REDIS_KEY_PREFIX + keyId + ":created"),
                            redisTemplate.opsForSet().remove(REDIS_KEY_ALL, keyId));
                })
                .then();
    }

    /**
     * 定时任务：每天凌晨2点检查是否需要轮换密钥
     *
     * <p>轮换条件：当前密钥的创建时间超过30天
     */
    @Scheduled(cron = "0 0 2 * * ?")
    public void scheduledKeyRotation() {
        log.info("执行定时JWT密钥轮换检查");

        getCurrentKeyId()
                .flatMap(keyId -> {
                    String createdKey = REDIS_KEY_PREFIX + keyId + ":created";
                    return redisTemplate.opsForValue().get(createdKey).map(createdStr -> {
                        long createdMillis = Long.parseLong(createdStr);
                        Instant created = Instant.ofEpochMilli(createdMillis);
                        long daysSinceCreation = ChronoUnit.DAYS.between(created, Instant.now());
                        return daysSinceCreation >= ROTATION_PERIOD_DAYS;
                    });
                })
                .defaultIfEmpty(false)
                .flatMap(needsRotation -> {
                    if (needsRotation) {
                        log.info("检测到密钥已超过轮换周期，开始自动轮换");
                        return rotateKeys().then();
                    } else {
                        log.debug("当前密钥仍在有效期内，无需轮换");
                        return Mono.empty();
                    }
                })
                .subscribe(null, e -> log.error("定时密钥轮换失败", e));
    }

    /**
     * 获取所有可用的密钥ID（包括宽限期内的旧密钥）
     *
     * @return 密钥ID列表
     */
    public Mono<List<String>> getAllAvailableKeyIds() {
        return redisTemplate.opsForSet().members(REDIS_KEY_ALL).collectList();
    }

    /**
     * 立即强制轮换密钥（用于紧急响应密钥泄露）
     *
     * <p>与定时轮换的区别：</p>
     * <ul>
     *   <li>忽略轮换周期检查，立即执行</li>
     *   <li>立即清理所有旧密钥（不等待宽限期）</li>
     *   <li>记录安全事件日志</li>
     * </ul>
     *
     * @param reason 轮换原因（用于审计）
     * @return 新密钥ID
     */
    public Mono<String> forceRotateKeys(String reason) {
        log.warn("执行紧急密钥轮换: reason={}", reason);

        return rotateKeys()
                .flatMap(newKeyId -> {
                    // 立即清理所有旧密钥（不等待宽限期）
                    return redisTemplate
                            .opsForSet()
                            .members(REDIS_KEY_ALL)
                            .filter(keyId -> !keyId.equals(newKeyId))
                            .flatMap(oldKeyId -> {
                                log.warn("紧急删除旧密钥: keyId={}, reason={}", oldKeyId, reason);
                                return Mono.when(
                                        redisTemplate.delete(REDIS_KEY_PREFIX + oldKeyId + ":private"),
                                        redisTemplate.delete(REDIS_KEY_PREFIX + oldKeyId + ":public"),
                                        redisTemplate.delete(REDIS_KEY_PREFIX + oldKeyId + ":created"),
                                        redisTemplate.opsForSet().remove(REDIS_KEY_ALL, oldKeyId));
                            })
                            .then(Mono.just(newKeyId));
                })
                .doOnSuccess(newKeyId -> log.warn("紧急密钥轮换完成: newKeyId={}, reason={}", newKeyId, reason));
    }
}

package com.apex.scaffold.auth.domain.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jws;
import io.jsonwebtoken.JwtBuilder;
import io.jsonwebtoken.JwtException;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import java.io.IOException;
import java.security.PrivateKey;
import java.security.PublicKey;
import java.time.Instant;
import java.util.Base64;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.Map;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

/**
 * JWT 非对称（RSA/RS256）密钥材料服务。
 *
 * <p>微服务迁移 Phase 2.1 的核心组件：将认证中心 Token 签名算法由对称的
 * HS256（共享密钥）升级为非对称的 RS256（私钥签名、公钥验证），实现：
 *
 * <h2>升级动机</h2>
 * <ul>
 *   <li><b>职责分离</b>：私钥仅存于认证中心用于签发；其它服务仅持公钥验签，
 *       无需再分发共享密钥，任一验证方泄露都不影响签发安全。</li>
 *   <li><b>标准互操作</b>：通过 {@code /.well-known/jwks.json} 暴露 JWKS，
 *       网关及各业务服务可按 {@code kid} 拉取公钥完成本地验签。</li>
 *   <li><b>平滑轮换</b>：JWT 头部携带 {@code kid}，新旧密钥可并存验证，
 *       密钥轮换对调用方透明。</li>
 * </ul>
 *
 * <h2>与密钥轮换的关系</h2>
 * <p>本服务不自行管理密钥生命周期，而是复用 {@link JwtKeyRotationService}
 * （Redis-RSA 实现）完成密钥的生成、轮换与宽限期管理，仅负责：
 * <ul>
 *   <li>用“当前活跃私钥”签发 Token，并写入与公钥一致的 {@code kid}；</li>
 *   <li>按 {@code kid} 选择对应公钥，对 Token 进行验签与解析；</li>
 *   <li>为 JWKS 端点提供密钥集合投影。</li>
 * </ul>
 *
 * @author Apex Team
 * @since 1.3.1
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class JwtKeyMaterialService {

    /**
     * JWT 头部中的密钥标识字段名（RFC 7515 §4.1.4）。
     */
    private static final String HEADER_KEY_ID = "kid";

    /**
     * RSA 密钥轮换与签名服务（Redis-RSA 实现，唯一保留的密钥轮换实现）。
     */
    private final JwtKeyRotationService jwtKeyRotationService;

    /**
     * 用于解码 JWT 头部 JSON 的 Jackson 映射器（线程安全，可直接复用）。
     */
    private final ObjectMapper objectMapper = new ObjectMapper();

    /**
     * 使用当前活跃私钥签发 RS256 Token。
     *
     * <p>方法签名与 {@code JwtUtil.generateToken(subject, claims, expireTime)} 保持一致，
     * 便于调用方从对称签名平滑切换到非对称签名。
     *
     * @param subject      Token 主题（通常为用户ID）
     * @param claims       自定义声明（可含 jti 等注册声明）
     * @param expireMillis 有效期（毫秒）
     * @return 已签名的紧凑型 JWT 字符串
     */
    public Mono<String> sign(String subject, Map<String, Object> claims, long expireMillis) {
        return jwtKeyRotationService
                .getCurrentKeyId()
                .zipWith(jwtKeyRotationService.getCurrentPrivateKey())
                .map(tuple -> buildSignedToken(tuple.getT1(), tuple.getT2(), subject, claims, expireMillis));
    }

    /**
     * 按 {@code kid} 验签并解析 Token。
     *
     * <p>先从 Token 头部读取 {@code kid}，再加载对应公钥验签；
     * 若未携带 {@code kid}（历史 Token）则回退到当前活跃公钥尝试验签，
     * 兼容密钥轮换宽限期内的旧 Token。
     *
     * @param token 紧凑型 JWT 字符串
     * @return 解析后的声明集合
     */
    public Mono<Claims> parse(String token) {
        return Mono.defer(() -> {
            String keyId = extractKeyId(token);
            if (keyId != null && !keyId.isBlank()) {
                return jwtKeyRotationService
                        .getPublicKey(keyId)
                        .switchIfEmpty(Mono.error(new JwtException("未找到 kid 对应的公钥: " + keyId)))
                        .map(publicKey -> parseWithKey(token, publicKey));
            }
            return jwtKeyRotationService
                    .getCurrentPublicKey()
                    .switchIfEmpty(Mono.error(new JwtException("JWT 密钥未初始化")))
                    .map(publicKey -> parseWithKey(token, publicKey));
        });
    }

    /**
     * 获取所有可用于验签的公钥（当前活跃 + 宽限期内旧密钥），用于 JWKS 投影。
     *
     * @return 密钥ID与公钥的映射（有序，当前活跃密钥优先）
     */
    public Mono<Map<String, PublicKey>> availablePublicKeys() {
        return jwtKeyRotationService
                .getAllAvailableKeyIds()
                .flatMapMany(Flux::fromIterable)
                .concatMap(keyId ->
                        jwtKeyRotationService.getPublicKey(keyId).map(publicKey -> Map.entry(keyId, publicKey)))
                .collectList()
                .map(entries -> {
                    Map<String, PublicKey> result = new LinkedHashMap<>();
                    entries.forEach(entry -> result.put(entry.getKey(), entry.getValue()));
                    return result;
                });
    }

    /**
     * 从 Token 头部安全提取 {@code kid}（不验签，仅读取）。
     *
     * <p>紧凑型 JWT 的第一段即为 Base64URL 编码的头部 JSON，直接解码读取
     * {@code kid}。此方式不涉及任何验签，天然规避“先有公钥才能读 kid”的
     * 循环依赖，且对非法 Token 保持健壮（解析失败返回 {@code null} 交由
     * 上层回退到当前活跃公钥）。
     *
     * @param token 紧凑型 JWT 字符串
     * @return kid 值；无法解析时返回 {@code null}
     */
    private String extractKeyId(String token) {
        if (token == null || token.isBlank()) {
            return null;
        }
        int firstDot = token.indexOf('.');
        if (firstDot <= 0) {
            return null;
        }
        try {
            byte[] headerBytes = Base64.getUrlDecoder().decode(token.substring(0, firstDot));
            JsonNode header = objectMapper.readTree(headerBytes);
            JsonNode kid = header.get(HEADER_KEY_ID);
            return kid == null || kid.isNull() ? null : kid.asText();
        } catch (IllegalArgumentException | IOException exception) {
            log.debug("读取 JWT kid 失败，将回退当前活跃公钥验证: {}", exception.getClass().getSimpleName());
            return null;
        }
    }

    /**
     * 使用指定公钥验签并解析。
     *
     * @param token     紧凑型 JWT 字符串
     * @param publicKey RSA 公钥
     * @return 解析后的声明集合
     * @throws JwtException 验签失败或 Token 非法
     */
    private Claims parseWithKey(String token, PublicKey publicKey) {
        Jws<Claims> jws = Jwts.parser().verifyWith(publicKey).build().parseSignedClaims(token);
        return jws.getPayload();
    }

    /**
     * 构建并签名 Token，写入 {@code kid} 与标准时间声明。
     *
     * @param keyId       密钥ID
     * @param privateKey  RSA 私钥
     * @param subject     Token 主题
     * @param claims      自定义声明
     * @param expireMillis 有效期（毫秒）
     * @return 紧凑型 JWT 字符串
     */
    private String buildSignedToken(
            String keyId, PrivateKey privateKey, String subject, Map<String, Object> claims, long expireMillis) {
        Instant now = Instant.now();
        JwtBuilder builder = Jwts.builder()
                .setHeaderParam(HEADER_KEY_ID, keyId)
                .subject(subject)
                // 注意：必须使用 claims(claims) 的“追加”语义（与旧版 JwtUtil.generateToken 一致）；
                // 若改用 setClaims(claims) 会整体替换声明集合，从而覆盖上面设置的 subject。
                .claims(claims)
                .issuedAt(Date.from(now))
                .expiration(Date.from(now.plusMillis(expireMillis)));
        return builder.signWith(privateKey, SignatureAlgorithm.RS256).compact();
    }
}

package com.apex.scaffold.auth.application.service;

import com.apex.scaffold.auth.domain.model.entity.TokenEntity;
import com.apex.scaffold.auth.domain.model.vo.TokenPair;
import com.apex.scaffold.auth.domain.repository.TokenRepository;
import com.apex.scaffold.auth.domain.repository.UserRepository;
import com.apex.scaffold.auth.domain.service.JwtKeyMaterialService;
import com.apex.scaffold.auth.domain.service.TokenEncryptionService;
import com.apex.scaffold.auth.domain.service.TokenService;
import com.apex.scaffold.common.audit.SecurityAuditService;
import com.apex.scaffold.common.context.TenantContext;
import com.apex.scaffold.common.exception.BusinessException;
import com.apex.scaffold.common.result.ResultCode;
import io.jsonwebtoken.ExpiredJwtException;
import io.jsonwebtoken.JwtException;
import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;

/**
 * Token服务实现类
 *
 * <p>基于JWT实现Token的签发、验证、刷新和撤销功能。
 *
 * <h2>核心功能</h2>
 * <ul>
 *   <li>签发Token对：访问令牌（2小时）+ 刷新令牌（7天）</li>
 *   <li>验证Token：签名验证、过期检测、撤销检查</li>
 *   <li>刷新Token：使用刷新令牌换取新的访问令牌</li>
 *   <li>撤销Token：单个撤销或批量撤销用户所有Token</li>
 * </ul>
 *
 * <h2>Token声明结构</h2>
 * <pre>{@code
 * {
 *   "jti": "唯一Token ID",
 *   "userId": "用户ID",
 *   "tenantId": "租户ID",
 *   "tokenType": "ACCESS/REFRESH",
 *   "deviceId": "设备ID",
 *   "iat": "签发时间",
 *   "exp": "过期时间"
 * }
 * }</pre>
 *
 * <h2>安全保障</h2>
 * <ul>
 *   <li>所有Token持久化到数据库，支持撤销和追踪</li>
 *   <li>验证时检查数据库撤销状态，已撤销Token拒绝访问</li>
 *   <li>刷新令牌不轮换，使用时不生成新的刷新令牌</li>
 *   <li>租户隔离：Token只能在签发租户内使用</li>
 * </ul>
 *
 * @author Apex Team
 * @since 1.3.1
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class TokenServiceImpl implements TokenService {

    private static final int CLAIMS_INITIAL_CAPACITY = 8;
    private static final String REFRESH_TOKEN_TYPE = "REFRESH";

    private final TokenRepository tokenRepository;
    private final UserRepository userRepository;
    private final TokenEncryptionService encryptionService;
    private final SecurityAuditService auditService;
    private final JwtKeyMaterialService jwtKeyMaterialService;

    private static final long ACCESS_TOKEN_EXPIRE_MS = 2 * 60 * 60 * 1000L;
    private static final long REFRESH_TOKEN_EXPIRE_MS = 7 * 24 * 60 * 60 * 1000L;

    @Override
    @SuppressWarnings("PMD.MethodTooLongRule")
    public Mono<TokenPair> issueToken(Long userId, String tenantId, String deviceId, String clientIp) {
        return issueToken(userId, tenantId, deviceId, clientIp, null);
    }

    @Override
    @SuppressWarnings("PMD.MethodTooLongRule")
    public Mono<TokenPair> issueToken(
            Long userId, String tenantId, String deviceId, String clientIp, String clientType) {
        log.debug("开始签发Token: userId={}, clientType={}", userId, clientType);

        return userRepository
                .findById(userId)
                .switchIfEmpty(Mono.error(new BusinessException(ResultCode.NOT_FOUND, "用户不存在")))
                .flatMap(user -> {
                    if (!tenantId.equals(user.getTenantId())) {
                        return Mono.error(new BusinessException(ResultCode.FORBIDDEN, "租户不匹配"));
                    }
                    if (!user.isActive()) {
                        return Mono.error(new BusinessException(ResultCode.FORBIDDEN, "账户已禁用"));
                    }
                    if (user.isLocked()) {
                        return Mono.error(new BusinessException(ResultCode.FORBIDDEN, "账户已锁定"));
                    }

                    String accessJti = UUID.randomUUID().toString();
                    String refreshJti = UUID.randomUUID().toString();

                    Map<String, Object> accessClaims =
                            buildClaims(accessJti, userId, tenantId, "ACCESS", deviceId, user, clientType);
                    Map<String, Object> refreshClaims =
                            buildClaims(refreshJti, userId, tenantId, REFRESH_TOKEN_TYPE, deviceId, user, clientType);

                    // 使用 RSA/RS256 非对称密钥签发访问令牌与刷新令牌（Phase 2.1 迁移）
                    return jwtKeyMaterialService
                            .sign(String.valueOf(userId), accessClaims, ACCESS_TOKEN_EXPIRE_MS)
                            .zipWith(jwtKeyMaterialService.sign(
                                    String.valueOf(userId), refreshClaims, REFRESH_TOKEN_EXPIRE_MS))
                            .flatMap(signedTokens -> {
                                String accessToken = signedTokens.getT1();
                                String refreshToken = signedTokens.getT2();

                                // 加密Token并计算哈希
                                TokenEncryptionService.EncryptedToken encryptedAccess =
                                        encryptionService.encrypt(accessToken);
                                TokenEncryptionService.EncryptedToken encryptedRefresh =
                                        encryptionService.encrypt(refreshToken);
                                String accessTokenHash = encryptionService.hashToken(accessToken);
                                String refreshTokenHash = encryptionService.hashToken(refreshToken);

                                // 生成Token Family ID用于轮换检测
                                String tokenFamily = UUID.randomUUID().toString();

                                LocalDateTime now = LocalDateTime.now();
                                TokenEntity accessTokenEntity = TokenEntity.builder()
                                        .tenantId(tenantId)
                                        .userId(userId)
                                        .tokenType("ACCESS")
                                        .tokenValue(encryptedAccess.encryptedData())
                                        .tokenHash(accessTokenHash)
                                        .tokenIv(encryptedAccess.iv())
                                        .jti(accessJti)
                                        .expiresAt(now.plusSeconds(ACCESS_TOKEN_EXPIRE_MS / 1000))
                                        .deviceId(deviceId)
                                        .clientIp(clientIp)
                                        .tokenFamily(tokenFamily)
                                        .build();

                                TokenEntity refreshTokenEntity = TokenEntity.builder()
                                        .tenantId(tenantId)
                                        .userId(userId)
                                        .tokenType(REFRESH_TOKEN_TYPE)
                                        .tokenValue(encryptedRefresh.encryptedData())
                                        .tokenHash(refreshTokenHash)
                                        .tokenIv(encryptedRefresh.iv())
                                        .jti(refreshJti)
                                        .expiresAt(now.plusSeconds(REFRESH_TOKEN_EXPIRE_MS / 1000))
                                        .deviceId(deviceId)
                                        .clientIp(clientIp)
                                        .tokenFamily(tokenFamily)
                                        .build();

                                return tokenRepository
                                        .save(accessTokenEntity)
                                        .then(tokenRepository.save(refreshTokenEntity))
                                        .flatMap(savedRefreshToken -> auditService
                                                .logTokenIssued(userId, tenantId, clientIp, deviceId, "ACCESS+REFRESH")
                                                .thenReturn(TokenPair.builder()
                                                        .accessToken(accessToken)
                                                        .refreshToken(refreshToken)
                                                        .expiresIn(ACCESS_TOKEN_EXPIRE_MS / 1000)
                                                        .tokenType("Bearer")
                                                        .build()));
                            });
                })
                .doOnSuccess(pair -> log.debug("Token签发成功: userId={}", userId));
    }

    /**
     * 构建 Token claims（统一账户模型）。
     *
     * <p>除既有 jti/userId/tenantId/tokenType/deviceId 外，追加统一账户字段：
     * {@code accountId}（主应用 sys_user.id，未映射时不写入）、{@code username}、
     * {@code clientType}（客户端类型编码，调用方未上报时不写入），供主应用
     * 装配统一身份与按终端审计。
     *
     * @param jti        Token 唯一ID
     * @param userId     认证中心用户ID
     * @param tenantId   租户ID
     * @param tokenType  令牌类型（ACCESS/REFRESH）
     * @param deviceId   设备ID
     * @param user       用户实体（携带统一账户映射）
     * @param clientType 客户端类型编码，可为空
     * @return claims Map
     */
    private Map<String, Object> buildClaims(
            String jti,
            Long userId,
            String tenantId,
            String tokenType,
            String deviceId,
            com.apex.scaffold.auth.domain.model.entity.UserEntity user,
            String clientType) {
        Map<String, Object> claims = new HashMap<>(CLAIMS_INITIAL_CAPACITY);
        claims.put("jti", jti);
        claims.put("userId", userId);
        claims.put("tenantId", tenantId);
        claims.put("tokenType", tokenType);
        claims.put("deviceId", deviceId);
        if (user.getAccountId() != null) {
            claims.put("accountId", user.getAccountId());
        }
        if (user.getUsername() != null && !user.getUsername().isBlank()) {
            claims.put("username", user.getUsername());
        }
        if (clientType != null && !clientType.isBlank()) {
            claims.put("clientType", clientType);
        }
        return claims;
    }

    @Override
    public Mono<TokenEntity> validateToken(String token) {
        return jwtKeyMaterialService
                .parse(token)
                .onErrorMap(ExpiredJwtException.class, exception -> {
                    log.debug("Token已过期");
                    return new BusinessException(ResultCode.UNAUTHORIZED, "Token已过期");
                })
                .onErrorMap(
                        exception -> exception instanceof JwtException || exception instanceof IllegalArgumentException,
                        exception -> {
                            log.debug("Token验证失败");
                            return new BusinessException(ResultCode.UNAUTHORIZED, "Token无效");
                        })
                .flatMap(claims -> {
                    String jti = claims.get("jti", String.class);
                    Long userId = claims.get("userId", Long.class);
                    String tenantId = claims.get("tenantId", String.class);

                    if (jti == null || jti.isBlank() || userId == null || tenantId == null || tenantId.isBlank()) {
                        return Mono.error(new BusinessException(ResultCode.UNAUTHORIZED, "Token声明不完整"));
                    }

                    return Mono.deferContextual(context -> {
                        String existingTenant = context.getOrDefault(TenantContext.REACTOR_CONTEXT_KEY, null);
                        if (existingTenant != null && !existingTenant.equals(tenantId)) {
                            return Mono.error(new BusinessException(ResultCode.FORBIDDEN));
                        }
                        return tokenRepository
                                .findByJti(jti)
                                .switchIfEmpty(Mono.error(new BusinessException(ResultCode.UNAUTHORIZED, "Token不存在")))
                                .flatMap(tokenEntity -> {
                                    if (!Objects.equals(tokenEntity.getTenantId(), tenantId)
                                            || !Objects.equals(tokenEntity.getUserId(), userId)
                                            || !Objects.equals(tokenEntity.getJti(), jti)
                                            || !Objects.equals(
                                                    tokenEntity.getTokenType(),
                                                    claims.get("tokenType", String.class))) {
                                        return Mono.error(new BusinessException(ResultCode.UNAUTHORIZED));
                                    }
                                    if (tokenEntity.isRevoked()) {
                                        return Mono.error(new BusinessException(ResultCode.UNAUTHORIZED, "Token已撤销"));
                                    }
                                    if (tokenEntity.isExpired()) {
                                        return Mono.error(new BusinessException(ResultCode.UNAUTHORIZED, "Token已过期"));
                                    }
                                    if (!tokenEntity.isValid()) {
                                        return Mono.error(new BusinessException(ResultCode.UNAUTHORIZED, "Token无效"));
                                    }
                                    return Mono.just(tokenEntity);
                                })
                                .transformDeferred(mono -> TenantContext.withTenant(mono))
                                .contextWrite(TenantContext.withTenant(tenantId));
                    });
                });
    }

    @Override
    public Mono<TokenPair> refreshToken(String refreshToken) {
        return validateToken(refreshToken)
                .flatMap(tokenEntity -> {
                    if (!REFRESH_TOKEN_TYPE.equals(tokenEntity.getTokenType())) {
                        return Mono.error(new BusinessException(ResultCode.PARAM_ERROR, "必须使用刷新令牌"));
                    }

                    // 检测Token重放攻击：如果Token已被撤销，说明可能是重放攻击
                    if (tokenEntity.isRevoked()) {
                        log.warn("检测到可疑的Token刷新尝试: userId={}", tokenEntity.getUserId());

                        // 记录Token重放攻击审计日志
                        return auditService
                                .logTokenReplayAttack(
                                        tokenEntity.getUserId(),
                                        tokenEntity.getTenantId(),
                                        tokenEntity.getClientIp(),
                                        tokenEntity.getJti())
                                .then(tokenRepository.revokeByUserId(
                                        tokenEntity.getUserId(), tokenEntity.getTenantId()))
                                .then(Mono.error(
                                        new BusinessException(ResultCode.UNAUTHORIZED, "检测到安全威胁，已撤销所有会话，请重新登录")));
                    }

                    // 实施Token轮换：撤销旧的refresh token
                    return tokenRepository
                            .revokeByJti(tokenEntity.getJti(), "system", "token_refresh")
                            .flatMap(revoked -> {
                                if (!revoked) {
                                    log.warn("Token轮换失败: 无法撤销旧token");
                                    return Mono.error(new BusinessException(ResultCode.ERROR, "Token刷新失败"));
                                }

                                // 签发新的Token对（包含新的refresh token）
                                return issueToken(
                                                tokenEntity.getUserId(),
                                                tokenEntity.getTenantId(),
                                                tokenEntity.getDeviceId(),
                                                tokenEntity.getClientIp())
                                        .flatMap(newTokenPair -> auditService
                                                .logTokenRefreshed(
                                                        tokenEntity.getUserId(),
                                                        tokenEntity.getTenantId(),
                                                        tokenEntity.getClientIp(),
                                                        tokenEntity.getJti())
                                                .thenReturn(newTokenPair));
                            })
                            .transformDeferred(mono -> TenantContext.withTenant(mono))
                            .contextWrite(TenantContext.withTenant(tokenEntity.getTenantId()));
                })
                .doOnSuccess(pair -> log.debug("Token刷新成功，已轮换refresh token"));
    }

    @Override
    public Mono<Void> revokeToken(String token) {
        return jwtKeyMaterialService
                .parse(token)
                .onErrorMap(
                        exception -> exception instanceof JwtException || exception instanceof IllegalArgumentException,
                        exception -> {
                            log.debug("Token无效");
                            return new BusinessException(ResultCode.UNAUTHORIZED, "Token无效");
                        })
                .flatMap(claims -> {
                    String jti = claims.get("jti", String.class);

                    if (jti == null || jti.isBlank()) {
                        return Mono.error(new BusinessException(ResultCode.UNAUTHORIZED, "Token格式错误"));
                    }

                    return tokenRepository
                            .findByJti(jti)
                            .switchIfEmpty(Mono.error(new BusinessException(ResultCode.NOT_FOUND, "Token不存在")))
                            .flatMap(tokenEntity -> {
                                // 记录撤销原因和操作人
                                tokenEntity.revoke("user:" + tokenEntity.getUserId(), "manual");
                                return tokenRepository
                                        .update(tokenEntity)
                                        .then(auditService.logTokenRevoked(
                                                tokenEntity.getUserId(),
                                                null, // username需要从UserService获取
                                                tokenEntity.getTenantId(),
                                                jti,
                                                "manual",
                                                tokenEntity.getClientIp()));
                            })
                            .doOnSuccess(v -> log.debug("Token撤销成功"));
                });
    }

    @Override
    public Mono<Void> revokeAllUserTokens(Long userId, String tenantId) {
        return tokenRepository
                .revokeByUserId(userId, tenantId)
                .doOnSuccess(count -> log.debug("已撤销用户所有Token: userId={}, count={}", userId, count))
                .then();
    }

    @Override
    public Mono<Long> extractUserId(String token) {
        return validateToken(token).map(TokenEntity::getUserId);
    }
}

