package com.apex.scaffold.auth.domain.model;

import java.time.LocalDateTime;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.springframework.data.annotation.Id;
import org.springframework.data.relational.core.mapping.Table;

/**
 * 多因素认证(MFA)配置领域模型
 * @author Apex Team
 * @since 1.2.0
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
@Table("mfa_config")
public class MfaConfig {

    /**
     * 主键ID
     */
    @Id
    private Long id;

    /**
     * 用户ID
     */
    private String userId;

    /**
     * 租户ID
     */
    private String tenantId;

    /**
     * MFA类型
     */
    private MfaType type;

    /**
     * MFA状态
     */
    private MfaStatus status;

    /**
     * 密钥（加密存储）
     */
    private String secret;

    /**
     * 备用验证码（加密存储，逗号分隔）
     */
    private String backupCodes;

    /**
     * 设备信息（用于设备绑定）
     */
    private String deviceInfo;

    /**
     * 最后验证时间
     */
    private LocalDateTime lastVerifiedAt;

    /**
     * 验证失败次数
     */
    private Integer failedAttempts;

    /**
     * 创建时间
     */
    private LocalDateTime createdAt;

    /**
     * 更新时间
     */
    private LocalDateTime updatedAt;

    /**
     * MFA类型枚举
     */
    public enum MfaType {
        /**
         * TOTP - 基于时间的一次性密码（Google Authenticator）
         */
        TOTP,

        /**
         * SMS - 短信验证码
         */
        SMS,

        /**
         * EMAIL - 邮箱验证码
         */
        EMAIL,

        /**
         * BACKUP_CODE - 备用验证码
         */
        BACKUP_CODE
    }

    /**
     * MFA状态枚举
     */
    public enum MfaStatus {
        /**
         * 待激活 - 已配置但未完成验证
         */
        PENDING,

        /**
         * 已激活 - 正常使用中
         */
        ACTIVE,

        /**
         * 已禁用 - 用户主动禁用
         */
        DISABLED,

        /**
         * 已锁定 - 验证失败次数过多
         */
        LOCKED
    }

    /**
     * 判断是否已激活
     *
     * @return MFA状态为激活时返回true，否则返回false
     */
    public boolean isActive() {
        return MfaStatus.ACTIVE.equals(status);
    }

    /**
     * 判断是否已锁定
     *
     * @return MFA状态为锁定时返回true，否则返回false
     */
    public boolean isLocked() {
        return MfaStatus.LOCKED.equals(status);
    }

    /**
     * 增加失败次数
     */
    private static final int MAX_FAILED_ATTEMPTS = 5;

    /**
     * 增加失败次数，达到上限时锁定MFA。
     */
    public void incrementFailedAttempts() {
        this.failedAttempts = (this.failedAttempts == null ? 0 : this.failedAttempts) + 1;

        if (this.failedAttempts >= MAX_FAILED_ATTEMPTS) {
            this.status = MfaStatus.LOCKED;
        }
    }

    /**
     * 重置失败次数
     */
    public void resetFailedAttempts() {
        this.failedAttempts = 0;
        if (MfaStatus.LOCKED.equals(this.status)) {
            this.status = MfaStatus.ACTIVE;
        }
    }

    /**
     * 更新最后验证时间
     */
    public void updateLastVerified() {
        this.lastVerifiedAt = LocalDateTime.now();
        resetFailedAttempts();
    }
}

package com.apex.scaffold.auth.infrastructure.repository;

import com.apex.scaffold.auth.domain.model.MfaConfig;
import org.springframework.data.repository.reactive.ReactiveCrudRepository;
import org.springframework.stereotype.Repository;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

/**
 * MFA配置存储库
 * @author Apex Team
 * @since 1.2.0
 */
@Repository
public interface MfaConfigRepository extends ReactiveCrudRepository<MfaConfig, Long> {

    /**
     * 根据用户 ID 查询所有 MFA 配置。
     *
     * @param userId 用户 ID
     * @return MFA 配置列表
     */
    Flux<MfaConfig> findByUserId(String userId);

    /**
     * 根据用户 ID 和租户 ID 查询所有 MFA 配置。
     *
     * @param userId 用户 ID
     * @param tenantId 租户 ID
     * @return MFA 配置列表
     */
    Flux<MfaConfig> findByUserIdAndTenantId(String userId, String tenantId);

    /**
     * 根据用户 ID 和类型查询 MFA 配置。
     *
     * @param userId 用户 ID
     * @param type MFA 类型
     * @return MFA 配置
     */
    Mono<MfaConfig> findByUserIdAndType(String userId, MfaConfig.MfaType type);

    /**
     * 根据用户 ID、类型和租户 ID 查询 MFA 配置。
     *
     * @param userId 用户 ID
     * @param type MFA 类型
     * @param tenantId 租户 ID
     * @return MFA 配置
     */
    Mono<MfaConfig> findByUserIdAndTypeAndTenantId(String userId, MfaConfig.MfaType type, String tenantId);

    /**
     * 根据租户 ID 查询所有 MFA 配置。
     *
     * @param tenantId 租户 ID
     * @return MFA 配置列表
     */
    Flux<MfaConfig> findByTenantId(String tenantId);

    /**
     * 删除用户的指定类型 MFA 配置。
     *
     * @param userId 用户 ID
     * @param type MFA 类型
     * @return 删除的记录数
     */
    Mono<Long> deleteByUserIdAndType(String userId, MfaConfig.MfaType type);
}

package com.apex.scaffold.auth.infrastructure.service;

import com.apex.scaffold.auth.domain.model.MfaConfig;
import com.apex.scaffold.auth.domain.service.MfaService;
import com.apex.scaffold.auth.infrastructure.repository.MfaConfigRepository;
import com.apex.scaffold.common.audit.AuditLogService;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.common.security.EncryptionService;
import com.apex.scaffold.domain.service.SmsCodeService;
import com.apex.scaffold.infrastructure.mail.MailService;
import dev.samstevens.totp.code.*;
import dev.samstevens.totp.qr.QrData;
import dev.samstevens.totp.secret.DefaultSecretGenerator;
import dev.samstevens.totp.time.SystemTimeProvider;
import java.security.SecureRandom;
import java.time.Duration;
import java.time.LocalDateTime;
import java.util.*;
import java.util.stream.IntStream;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.data.redis.core.ReactiveStringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.data.redis.core.script.RedisScript;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

/**
 * 多因素认证服务实现
 * @author Apex Team
 * @since 1.2.0
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class MfaServiceImpl implements MfaService {

    private final MfaConfigRepository mfaConfigRepository;
    private final EncryptionService encryptionService;
    private final AuditLogService auditLogService;
    private final ReactiveStringRedisTemplate redisTemplate;
    private final SmsCodeService smsCodeService;
    private final MailService mailService;

    private static final String ISSUER = "Apex Scaffold";
    private static final String OTP_KEY_PREFIX = "mfa:otp:";
    private static final Duration OTP_TTL = Duration.ofMinutes(5);
    private static final RedisScript<Long> VERIFY_OTP_SCRIPT = new DefaultRedisScript<>(
            "local value = redis.call('GET', KEYS[1]); "
                    + "if not value then return 0; end; "
                    + "if value == ARGV[1] then redis.call('DEL', KEYS[1]); return 1; end; "
                    + "return -1;",
            Long.class);
    private static final int BACKUP_CODES_COUNT = 10;
    private static final int BACKUP_CODE_LENGTH = 8;

    @Override
    public Mono<TotpSetupInfo> enableTotp(String userId, String tenantId) {
        // 生成TOTP密钥
        DefaultSecretGenerator secretGenerator = new DefaultSecretGenerator();
        String secret = secretGenerator.generate();

        // 加密存储密钥
        return encryptionService
                .encrypt(secret)
                .flatMap(encryptedSecret -> {
                    // 创建MFA配置
                    MfaConfig config = MfaConfig.builder()
                            .userId(userId)
                            .tenantId(tenantId)
                            .type(MfaConfig.MfaType.TOTP)
                            .status(MfaConfig.MfaStatus.PENDING)
                            .secret(encryptedSecret)
                            .failedAttempts(0)
                            .createdAt(LocalDateTime.now())
                            .build();

                    return mfaConfigRepository.save(config);
                })
                .map(config -> {
                    // 生成二维码URL
                    QrData qrData = new QrData.Builder()
                            .label(userId)
                            .secret(secret)
                            .issuer(ISSUER)
                            .algorithm(HashingAlgorithm.SHA1)
                            .digits(6)
                            .period(30)
                            .build();

                    String qrCodeUrl = qrData.getUri();

                    log.info("用户启用TOTP MFA: userId={}, tenantId={}", userId, tenantId);

                    return new TotpSetupInfo(secret, qrCodeUrl, secret);
                });
    }

    @Override
    public Mono<MfaActivationResult> verifyAndActivateTotp(String userId, String code, String tenantId) {
        return mfaConfigRepository
                .findByUserIdAndTypeAndTenantId(userId, MfaConfig.MfaType.TOTP, tenantId)
                .flatMap(config -> {
                    if (config.isActive()) {
                        return Mono.error(new IllegalStateException("TOTP已经激活"));
                    }

                    // 解密密钥
                    return encryptionService.decrypt(config.getSecret()).flatMap(secret -> {
                        // 验证TOTP代码
                        CodeVerifier verifier =
                                new DefaultCodeVerifier(new DefaultCodeGenerator(), new SystemTimeProvider());

                        boolean isValid = verifier.isValidCode(secret, code);

                        if (!isValid) {
                            config.incrementFailedAttempts();
                            return mfaConfigRepository
                                    .save(config)
                                    .then(Mono.error(new IllegalArgumentException("验证码错误")));
                        }

                        // 激活TOTP
                        config.setStatus(MfaConfig.MfaStatus.ACTIVE);
                        config.updateLastVerified();

                        // 生成备用验证码
                        String[] backupCodes = generateBackupCodes();
                        String backupCodesStr = String.join(",", backupCodes);

                        return encryptionService
                                .encrypt(backupCodesStr)
                                .flatMap(encryptedBackupCodes -> {
                                    config.setBackupCodes(encryptedBackupCodes);
                                    config.setUpdatedAt(LocalDateTime.now());
                                    return mfaConfigRepository.save(config);
                                })
                                .map(saved -> {
                                    auditLogService.log(
                                            userId,
                                            config.getTenantId(),
                                            "激活TOTP多因素认证",
                                            "MFA_TOTP_ACTIVATED",
                                            "SUCCESS",
                                            null);
                                    log.info("用户激活TOTP MFA: userId={}", userId);
                                    return new MfaActivationResult(true, backupCodes);
                                });
                    });
                });
    }

    /**
     * 启用短信MFA，创建短信类型的MFA配置并记录审计日志
     *
     * @param userId 用户ID
     * @param tenantId 租户ID
     * @param phoneNumber 接收验证码的手机号
     * @return 新创建的短信MFA配置
     */
    @Override
    public Mono<MfaConfig> enableSms(String userId, String tenantId, String phoneNumber) {
        MfaConfig config = MfaConfig.builder()
                .userId(userId)
                .tenantId(tenantId)
                .type(MfaConfig.MfaType.SMS)
                .status(MfaConfig.MfaStatus.ACTIVE)
                // 存储手机号
                .deviceInfo(phoneNumber)
                .failedAttempts(0)
                .createdAt(LocalDateTime.now())
                .build();

        return mfaConfigRepository.save(config).doOnSuccess(saved -> {
            auditLogService.log(userId, tenantId, "启用短信多因素认证", "MFA_SMS_ENABLED", "SUCCESS", null);
            log.info("用户启用SMS MFA: userId={}, phone={}", userId, phoneNumber);
        });
    }

    /**
     * 启用邮箱MFA，创建邮箱类型的MFA配置并记录审计日志
     *
     * @param userId 用户ID
     * @param tenantId 租户ID
     * @param email 接收验证码的邮箱地址
     * @return 新创建的邮箱MFA配置
     */
    @Override
    public Mono<MfaConfig> enableEmail(String userId, String tenantId, String email) {
        MfaConfig config = MfaConfig.builder()
                .userId(userId)
                .tenantId(tenantId)
                .type(MfaConfig.MfaType.EMAIL)
                .status(MfaConfig.MfaStatus.ACTIVE)
                // 存储邮箱
                .deviceInfo(email)
                .failedAttempts(0)
                .createdAt(LocalDateTime.now())
                .build();

        return mfaConfigRepository.save(config).doOnSuccess(saved -> {
            auditLogService.log(userId, tenantId, "启用邮箱多因素认证", "MFA_EMAIL_ENABLED", "SUCCESS", null);
            log.info("用户启用EMAIL MFA: userId={}, email={}", userId, email);
        });
    }

    /**
     * 禁用指定类型的MFA，将配置状态置为禁用并记录审计日志
     *
     * @param userId 用户ID
     * @param type 要禁用的MFA类型
     * @param tenantId 租户ID
     * @return 完成信号
     */
    @Override
    @CacheEvict(value = "mfa-config", key = "#tenantId + ':' + #userId")
    public Mono<Void> disableMfa(String userId, MfaConfig.MfaType type, String tenantId) {
        return mfaConfigRepository
                .findByUserIdAndTypeAndTenantId(userId, type, tenantId)
                .flatMap(config -> {
                    config.setStatus(MfaConfig.MfaStatus.DISABLED);
                    config.setUpdatedAt(LocalDateTime.now());
                    return mfaConfigRepository.save(config);
                })
                .doOnNext(config -> {
                    auditLogService.log(
                            userId, config.getTenantId(), "禁用多因素认证: " + type, "MFA_DISABLED", "SUCCESS", null);
                    log.info("用户禁用MFA: userId={}, type={}", userId, type);
                })
                .then();
    }

    @Override
    public Mono<Boolean> verifyMfaCode(String userId, String code, MfaConfig.MfaType type, String tenantId) {
        return mfaConfigRepository
                .findByUserIdAndTypeAndTenantId(userId, type, tenantId)
                .flatMap(config -> {
                    if (!config.isActive()) {
                        return Mono.just(false);
                    }

                    if (config.isLocked()) {
                        return Mono.error(new IllegalStateException("MFA已锁定，请联系管理员"));
                    }

                    return switch (type) {
                        case TOTP -> verifyTotpCode(config, code);
                        case SMS, EMAIL -> verifyOtpCode(config, code);
                        case BACKUP_CODE -> verifyBackupCodeInternal(config, code);
                    };
                })
                .defaultIfEmpty(false);
    }

    /**
     * 验证TOTP代码
     */
    private Mono<Boolean> verifyTotpCode(MfaConfig config, String code) {
        return encryptionService.decrypt(config.getSecret()).flatMap(secret -> {
            CodeVerifier verifier = new DefaultCodeVerifier(new DefaultCodeGenerator(), new SystemTimeProvider());
            boolean isValid = verifier.isValidCode(secret, code);
            updateVerificationState(config, isValid);
            return mfaConfigRepository.save(config).thenReturn(isValid);
        });
    }

    /**
     * 验证OTP代码（SMS/Email）
     */
    private Mono<Boolean> verifyOtpCode(MfaConfig config, String code) {
        if (config.getDeviceInfo() == null || config.getDeviceInfo().isBlank()) {
            return Mono.just(false);
        }
        Mono<Boolean> validation = config.getType() == MfaConfig.MfaType.SMS
                ? smsCodeService.validate(config.getDeviceInfo(), code)
                : redisTemplate
                        .execute(VERIFY_OTP_SCRIPT, List.of(otpKey(config)), code)
                        .next()
                        .defaultIfEmpty(0L)
                        .map(result -> result == 1L);
        return validation.flatMap(valid -> {
            updateVerificationState(config, valid);
            return mfaConfigRepository.save(config).thenReturn(valid);
        });
    }

    private void updateVerificationState(MfaConfig config, boolean valid) {
        if (valid) {
            config.updateLastVerified();
        } else {
            config.incrementFailedAttempts();
        }
        config.setUpdatedAt(LocalDateTime.now());
    }

    private String otpKey(MfaConfig config) {
        return OTP_KEY_PREFIX + config.getTenantId() + ":" + config.getUserId() + ":" + config.getType();
    }

    /**
     * 验证备用验证码
     */
    private Mono<Boolean> verifyBackupCodeInternal(MfaConfig config, String code) {
        return encryptionService.decrypt(config.getBackupCodes()).flatMap(backupCodesStr -> {
            List<String> codes = new ArrayList<>(Arrays.asList(backupCodesStr.split(",")));
            if (codes.contains(code)) {
                codes.remove(code);
                String updatedCodes = String.join(",", codes);
                return encryptionService.encrypt(updatedCodes).flatMap(encrypted -> {
                    config.setBackupCodes(encrypted);
                    config.updateLastVerified();
                    config.setUpdatedAt(LocalDateTime.now());
                    return mfaConfigRepository.save(config).thenReturn(true);
                });
            }

            config.incrementFailedAttempts();
            config.setUpdatedAt(LocalDateTime.now());
            return mfaConfigRepository.save(config).thenReturn(false);
        });
    }

    /**
     * 发送MFA验证码（SMS/Email），生成6位数字验证码并按类型下发
     *
     * @param userId 用户ID
     * @param type MFA类型
     * @param tenantId 租户ID
     * @return 完成信号
     */
    @Override
    public Mono<Void> sendMfaCode(String userId, MfaConfig.MfaType type, String tenantId) {
        return mfaConfigRepository
                .findByUserIdAndTypeAndTenantId(userId, type, tenantId)
                .switchIfEmpty(Mono.error(new IllegalArgumentException("MFA配置不存在")))
                .flatMap(config -> {
                    if (!config.isActive()
                            || config.getDeviceInfo() == null
                            || config.getDeviceInfo().isBlank()) {
                        return Mono.error(new IllegalStateException("MFA配置不可用"));
                    }
                    if (type == MfaConfig.MfaType.SMS) {
                        return smsCodeService.sendAndStore(config.getDeviceInfo());
                    }
                    String code = String.format("%06d", new SecureRandom().nextInt(1_000_000));
                    return redisTemplate
                            .opsForValue()
                            .set(otpKey(config), code, OTP_TTL)
                            .flatMap(stored -> Boolean.TRUE.equals(stored)
                                    ? Mono.fromRunnable(() -> mailService.sendSimple(
                                                    config.getDeviceInfo(), "MFA验证码", "您的验证码是：" + code))
                                            .subscribeOn(BlockingIoSchedulers.remote())
                                            .then()
                                    : Mono.error(new IllegalStateException("验证码安全存储失败")));
                })
                .doOnSuccess(ignored -> log.info("MFA验证码发送完成: userId={}, type={}", userId, type));
    }

    /**
     * 查询用户的全部MFA配置
     *
     * @param userId 用户ID
     * @param tenantId 租户ID
     * @return 该用户的MFA配置流
     */
    @Override
    @Cacheable(value = "mfa-config", key = "#tenantId + ':' + #userId")
    public Flux<MfaConfig> getUserMfaConfigs(String userId, String tenantId) {
        return mfaConfigRepository.findByUserIdAndTenantId(userId, tenantId);
    }

    /**
     * 检查用户是否启用了任一处于激活状态的MFA
     *
     * @param userId 用户ID
     * @param tenantId 租户ID
     * @return 存在激活状态的MFA配置时为true，否则为false
     */
    @Override
    public Mono<Boolean> isMfaEnabled(String userId, String tenantId) {
        return mfaConfigRepository
                .findByUserIdAndTenantId(userId, tenantId)
                .filter(MfaConfig::isActive)
                .hasElements();
    }

    /**
     * 重新生成TOTP备用验证码，覆盖原有备用码并记录审计日志
     *
     * @param userId 用户ID
     * @param tenantId 租户ID
     * @return 新的备用验证码结果
     */
    @Override
    public Mono<BackupCodesResult> regenerateBackupCodes(String userId, String tenantId) {
        return mfaConfigRepository
                .findByUserIdAndTypeAndTenantId(userId, MfaConfig.MfaType.TOTP, tenantId)
                .flatMap(config -> {
                    String[] backupCodes = generateBackupCodes();
                    String backupCodesStr = String.join(",", backupCodes);

                    return encryptionService
                            .encrypt(backupCodesStr)
                            .flatMap(encrypted -> {
                                config.setBackupCodes(encrypted);
                                config.setUpdatedAt(LocalDateTime.now());
                                return mfaConfigRepository.save(config);
                            })
                            .map(saved -> {
                                auditLogService.log(
                                        userId,
                                        config.getTenantId(),
                                        "重新生成备用验证码",
                                        "MFA_BACKUP_CODES_REGENERATED",
                                        "SUCCESS",
                                        null);
                                return new BackupCodesResult(backupCodes);
                            });
                });
    }

    /**
     * 验证备用验证码，验证通过后该备用码将被作废
     *
     * @param userId 用户ID
     * @param code 备用验证码
     * @param tenantId 租户ID
     * @return 验证通过返回true，验证失败或配置不存在返回false
     */
    @Override
    public Mono<Boolean> verifyBackupCode(String userId, String code, String tenantId) {
        return verifyMfaCode(userId, code, MfaConfig.MfaType.BACKUP_CODE, tenantId);
    }

    /**
     * 解锁被锁定的MFA，重置失败尝试次数并记录审计日志
     *
     * @param userId 被解锁的用户ID
     * @param type 要解锁的MFA类型
     * @param operator 执行解锁操作的运维人员标识
     * @param tenantId 租户ID
     * @return 完成信号
     */
    @Override
    @CacheEvict(value = "mfa-config", key = "#tenantId + ':' + #userId")
    public Mono<Void> unlockMfa(String userId, MfaConfig.MfaType type, String operator, String tenantId) {
        return mfaConfigRepository
                .findByUserIdAndTypeAndTenantId(userId, type, tenantId)
                .flatMap(config -> {
                    config.resetFailedAttempts();
                    config.setUpdatedAt(LocalDateTime.now());
                    return mfaConfigRepository.save(config);
                })
                .doOnNext(config -> {
                    auditLogService.log(
                            operator, config.getTenantId(), "解锁MFA账户: " + userId, "MFA_UNLOCKED", "SUCCESS", null);
                    log.info("管理员解锁MFA账户: userId={}, operator={}", userId, operator);
                })
                .then();
    }

    /**
     * 生成备用验证码
     */
    private String[] generateBackupCodes() {
        SecureRandom random = new SecureRandom();
        return IntStream.range(0, BACKUP_CODES_COUNT)
                .mapToObj(i -> {
                    StringBuilder code = new StringBuilder();
                    for (int j = 0; j < BACKUP_CODE_LENGTH; j++) {
                        code.append(random.nextInt(10));
                    }
                    return code.toString();
                })
                .toArray(String[]::new);
    }
}

package com.apex.scaffold.auth.application.service;

import com.apex.scaffold.auth.domain.model.entity.MfaConfigEntity;
import com.apex.scaffold.auth.domain.model.entity.TotpEntity;
import com.apex.scaffold.auth.domain.repository.MfaConfigRepository;
import com.apex.scaffold.auth.domain.repository.TotpRepository;
import java.nio.ByteBuffer;
import java.security.SecureRandom;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;

/**
 * TOTP（Time-based One-Time Password）服务
 *
 * <p>提供 TOTP 多因素认证的核心功能，包括：
 * <ul>
 *   <li>生成 TOTP 密钥（Base32 编码）</li>
 *   <li>验证 TOTP 验证码（6 位数字）</li>
 *   <li>生成 OTP Auth URL（用于二维码）</li>
 *   <li>生成备份码</li>
 *   <li>验证备份码</li>
 * </ul>
 *
 * <p>遵循 RFC 6238 标准，支持 30 秒时间窗口和 ±1 窗口容差。
 *
 * @author Apex Scaffold Team
 * @since 1.3.1
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class TotpService {

    private static final int BASE32_BITS_PER_CHAR = 5;
    private static final int BASE32_PADDING_BLOCK_SIZE = 8;

    private final TotpRepository totpRepository;
    private final MfaConfigRepository mfaConfigRepository;

    /** TOTP 时间步长（秒） */
    private static final int TIME_STEP = 30;

    /** TOTP 密钥长度（字节） */
    private static final int SECRET_SIZE = 20;

    /** TOTP 验证码位数 */
    private static final int CODE_DIGITS = 6;

    /** 备份码数量 */
    private static final int BACKUP_CODE_COUNT = 10;

    /** 备份码长度 */
    private static final int BACKUP_CODE_LENGTH = 8;

    /** 时间窗口容差（前后各 1 个窗口） */
    private static final int WINDOW = 1;

    /** Base32 字符表 */
    private static final String BASE32_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

    private final SecureRandom secureRandom = new SecureRandom();

    /**
     * 为用户生成新的 TOTP 密钥
     *
     * @param userId   用户 ID
     * @param tenantId 租户 ID
     * @return 包含密钥和 OTP Auth URL 的结果
     */
    public Mono<TotpSetupResult> generateSecret(Long userId, String tenantId, String issuer, String accountName) {
        // 生成随机密钥
        byte[] secretBytes = new byte[SECRET_SIZE];
        secureRandom.nextBytes(secretBytes);
        String secret = encodeBase32(secretBytes);

        // 生成 OTP Auth URL
        String otpAuthUrl = buildOtpAuthUrl(issuer, accountName, secret);

        // 生成备份码
        List<String> backupCodes = generateBackupCodes();

        // 创建 TOTP 实体
        TotpEntity totpEntity = TotpEntity.builder()
                .tenantId(tenantId)
                .userId(userId)
                .secret(secret)
                .verified(false)
                .backupCodes(String.join(",", backupCodes))
                .usedBackupCodes(null)
                .enabled(false)
                .createdAt(LocalDateTime.now())
                .updatedAt(LocalDateTime.now())
                .version(1)
                .deleted(false)
                .build();

        return totpRepository.save(totpEntity).map(saved -> new TotpSetupResult(secret, otpAuthUrl, backupCodes));
    }

    /**
     * 验证 TOTP 验证码
     *
     * @param userId   用户 ID
     * @param code     用户输入的 6 位验证码
     * @param tenantId 租户 ID
     * @return 验证是否成功
     */
    public Mono<Boolean> verifyCode(Long userId, String code, String tenantId) {
        return totpRepository
                .findByUserId(userId, tenantId)
                .map(totp -> {
                    if (!totp.isEnabled()) {
                        log.warn("TOTP 未启用: userId={}", userId);
                        return false;
                    }
                    return verifyTotpCode(totp.getSecret(), code);
                })
                .defaultIfEmpty(false);
    }

    /**
     * 验证 TOTP 验证码并标记为已验证（首次设置时使用）
     *
     * @param userId   用户 ID
     * @param code     用户输入的 6 位验证码
     * @param tenantId 租户 ID
     * @return 验证是否成功
     */
    public Mono<Boolean> verifyAndEnable(Long userId, String code, String tenantId) {
        return totpRepository
                .findByUserId(userId, tenantId)
                .flatMap(totp -> {
                    boolean valid = verifyTotpCode(totp.getSecret(), code);
                    if (!valid) {
                        log.warn("TOTP 验证码错误: userId={}", userId);
                        return Mono.just(false);
                    }
                    totp.markAsVerified();
                    totp.enable();
                    return totpRepository
                            .update(totp)
                            .then(Mono.fromCallable(() -> {
                                // 同步创建 MFA 配置
                                MfaConfigEntity mfaConfig = MfaConfigEntity.builder()
                                        .tenantId(tenantId)
                                        .userId(userId)
                                        .mfaType(MfaConfigEntity.MfaType.TOTP.name())
                                        .enabled(true)
                                        .required(false)
                                        .priority(1)
                                        .createdAt(LocalDateTime.now())
                                        .updatedAt(LocalDateTime.now())
                                        .version(1)
                                        .deleted(false)
                                        .build();
                                return mfaConfig;
                            }))
                            .flatMap(mfaConfigRepository::save)
                            .thenReturn(true);
                })
                .defaultIfEmpty(false);
    }

    /**
     * 禁用用户的 TOTP
     *
     * @param userId   用户 ID
     * @param tenantId 租户 ID
     * @return 是否禁用成功
     */
    public Mono<Boolean> disable(Long userId, String tenantId) {
        return totpRepository
                .findByUserId(userId, tenantId)
                .flatMap(totp -> {
                    totp.disable();
                    return totpRepository
                            .update(totp)
                            .then(mfaConfigRepository.findByUserIdAndType(
                                    userId, MfaConfigEntity.MfaType.TOTP.name(), tenantId))
                            .flatMap(config -> {
                                config.disable();
                                return mfaConfigRepository.update(config);
                            })
                            .thenReturn(true);
                })
                .defaultIfEmpty(false);
    }

    /**
     * 验证备份码
     *
     * @param userId     用户 ID
     * @param backupCode 备份码
     * @param tenantId   租户 ID
     * @return 验证是否成功
     */
    public Mono<Boolean> verifyBackupCode(Long userId, String backupCode, String tenantId) {
        return totpRepository
                .findByUserId(userId, tenantId)
                .flatMap(totp -> {
                    if (!totp.isEnabled() || !totp.useBackupCode(backupCode)) {
                        return Mono.just(false);
                    }
                    return totpRepository.update(totp).thenReturn(true);
                })
                .defaultIfEmpty(false);
    }

    /**
     * 获取用户的 TOTP 配置
     *
     * @param userId   用户 ID
     * @param tenantId 租户 ID
     * @return TOTP 实体
     */
    public Mono<TotpEntity> getTotpConfig(Long userId, String tenantId) {
        return totpRepository.findByUserId(userId, tenantId);
    }

    /**
     * 检查用户是否已启用 TOTP
     *
     * @param userId   用户 ID
     * @param tenantId 租户 ID
     * @return 是否已启用
     */
    public Mono<Boolean> isEnabled(Long userId, String tenantId) {
        return totpRepository
                .findByUserId(userId, tenantId)
                .map(TotpEntity::isEnabled)
                .defaultIfEmpty(false);
    }

    // ==================== TOTP 算法实现 ====================

    /**
     * 验证 TOTP 验证码
     *
     * @param secret Base32 编码的密钥
     * @param code   用户输入的验证码
     * @return 验证是否成功
     */
    private boolean verifyTotpCode(String secret, String code) {
        if (secret == null || code == null || code.length() != CODE_DIGITS) {
            return false;
        }

        long currentTime = System.currentTimeMillis() / 1000;
        long currentStep = currentTime / TIME_STEP;

        // 检查当前窗口和前后各 1 个窗口
        for (int i = -WINDOW; i <= WINDOW; i++) {
            long step = currentStep + i;
            String expectedCode = generateTotpCode(secret, step);
            if (expectedCode.isEmpty()) {
                return false;
            }
            if (code.equals(expectedCode)) {
                return true;
            }
        }
        return false;
    }

    /**
     * 生成 TOTP 验证码
     *
     * @param secret Base32 编码的密钥
     * @param step   时间步长
     * @return 6 位验证码
     */
    private String generateTotpCode(String secret, long step) {
        byte[] key = decodeBase32(secret);
        byte[] timeBytes = ByteBuffer.allocate(8).putLong(step).array();

        try {
            Mac mac = Mac.getInstance("HmacSHA1");
            mac.init(new SecretKeySpec(key, "HmacSHA1"));
            byte[] hash = mac.doFinal(timeBytes);

            int offset = hash[hash.length - 1] & 0x0F;
            int truncated = ((hash[offset] & 0x7F) << 24)
                    | ((hash[offset + 1] & 0xFF) << 16)
                    | ((hash[offset + 2] & 0xFF) << 8)
                    | (hash[offset + 3] & 0xFF);

            int code = truncated % (int) Math.pow(10, CODE_DIGITS);
            return String.format("%0" + CODE_DIGITS + "d", code);
        } catch (Exception e) {
            log.warn("生成 TOTP 验证码失败: error={}", e.getClass().getSimpleName());
            return "";
        }
    }

    /**
     * 生成当前时间的 TOTP 验证码（用于测试）
     *
     * @param secret Base32 编码的密钥
     * @return 6 位验证码
     */
    public String generateCurrentCode(String secret) {
        long currentTime = System.currentTimeMillis() / 1000;
        long currentStep = currentTime / TIME_STEP;
        return generateTotpCode(secret, currentStep);
    }

    // ==================== 工具方法 ====================

    /**
     * 构建 OTP Auth URL
     *
     * <p>格式: otpauth://totp/Issuer:accountName?secret=SECRET&issuer=Issuer&algorithm=SHA1&digits=6&period=30
     *
     * @param issuer      发行方
     * @param accountName 账户名
     * @param secret      Base32 密钥
     * @return OTP Auth URL
     */
    private String buildOtpAuthUrl(String issuer, String accountName, String secret) {
        return String.format(
                "otpauth://totp/%s:%s?secret=%s&issuer=%s&algorithm=SHA1&digits=%d&period=%d",
                issuer, accountName, secret, issuer, CODE_DIGITS, TIME_STEP);
    }

    /**
     * Base32 编码
     *
     * @param bytes 字节数组
     * @return Base32 编码字符串
     */
    private String encodeBase32(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        int buffer = 0;
        int bitsLeft = 0;

        for (byte b : bytes) {
            buffer = (buffer << Byte.SIZE) | (b & 0xFF);
            bitsLeft += Byte.SIZE;
            while (bitsLeft >= BASE32_BITS_PER_CHAR) {
                int index = (buffer >> (bitsLeft - BASE32_BITS_PER_CHAR)) & 0x1F;
                result.append(BASE32_CHARS.charAt(index));
                bitsLeft -= BASE32_BITS_PER_CHAR;
            }
        }
        if (bitsLeft > 0) {
            int index = (buffer << (BASE32_BITS_PER_CHAR - bitsLeft)) & 0x1F;
            result.append(BASE32_CHARS.charAt(index));
        }

        // 补齐到 Byte.SIZE 的倍数
        while (result.length() % BASE32_PADDING_BLOCK_SIZE != 0) {
            result.append('=');
        }

        return result.toString();
    }

    /**
     * Base32 解码
     *
     * @param encoded Base32 编码字符串
     * @return 字节数组
     */
    private byte[] decodeBase32(String encoded) {
        encoded = encoded.replaceAll("=", "");
        List<Byte> bytes = new ArrayList<>();
        int buffer = 0;
        int bitsLeft = 0;

        for (char c : encoded.toCharArray()) {
            int index = BASE32_CHARS.indexOf(Character.toUpperCase(c));
            if (index < 0) {
                continue;
            }
            buffer = (buffer << BASE32_BITS_PER_CHAR) | index;
            bitsLeft += BASE32_BITS_PER_CHAR;
            if (bitsLeft >= Byte.SIZE) {
                bytes.add((byte) ((buffer >> (bitsLeft - Byte.SIZE)) & 0xFF));
                bitsLeft -= Byte.SIZE;
            }
        }

        byte[] result = new byte[bytes.size()];
        for (int i = 0; i < bytes.size(); i++) {
            result[i] = bytes.get(i);
        }
        return result;
    }

    /**
     * 生成备份码列表
     *
     * @return 备份码列表
     */
    private List<String> generateBackupCodes() {
        List<String> codes = new ArrayList<>();
        for (int i = 0; i < BACKUP_CODE_COUNT; i++) {
            StringBuilder code = new StringBuilder();
            for (int j = 0; j < BACKUP_CODE_LENGTH; j++) {
                code.append(secureRandom.nextInt(10));
            }
            codes.add(code.toString());
        }
        return codes;
    }

    /**
     * TOTP 设置结果
     */
    public record TotpSetupResult(String secret, String otpAuthUrl, List<String> backupCodes) {
        /**
         * 获取 Base64 编码的二维码图片数据
         *
         * @return data:image/png;base64,... 格式的图片数据
         */
        public String getQrCodeDataUrl() {
            // 实际项目中可以使用 ZXing 库生成二维码图片
            // 这里返回 OTP Auth URL 供前端生成二维码
            return otpAuthUrl;
        }
    }
}

