package com.apex.scaffold.authservice.config;

import static org.springframework.web.reactive.function.server.RequestPredicates.*;
import static org.springframework.web.reactive.function.server.RouterFunctions.route;

import com.apex.scaffold.authservice.interfaces.handler.IpAccessControlHandler;
import com.apex.scaffold.authservice.interfaces.handler.MfaManagementHandler;
import lombok.RequiredArgsConstructor;
import org.springdoc.core.annotations.RouterOperation;
import org.springdoc.core.annotations.RouterOperations;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.reactive.function.server.RouterFunction;
import org.springframework.web.reactive.function.server.ServerResponse;

/**
 * 认证中心路由配置
 *
 * 使用WebFlux函数式路由注册认证中心的端点路由
 *
 * 端点列表：
 * - /api/mfa/** - 多因素认证管理
 * - /api/ip-access-control/** - IP访问控制管理
 *
 * @author Apex Team
 * @since 1.3.1
 */
@Configuration
@RequiredArgsConstructor
public class AuthCenterRouterConfig {

    private final MfaManagementHandler mfaHandler;
    private final IpAccessControlHandler ipAccessControlHandler;

    /**
     * MFA多因素认证管理路由（/api/mfa/**，与 {@link com.apex.scaffold.authservice.interfaces.router.MfaRouter}
     * 的 /api/v1/mfa/** 路由集相互独立，bean 命名区分避免冲突）
     *
     * @return MFA 管理路由
     */
    @Bean
    @RouterOperations({
        @RouterOperation(
                path = "/api/mfa/totp/enable",
                method = RequestMethod.POST,
                beanClass = MfaManagementHandler.class,
                beanMethod = "enableTotp"),
        @RouterOperation(
                path = "/api/mfa/totp/activate",
                method = RequestMethod.POST,
                beanClass = MfaManagementHandler.class,
                beanMethod = "activateTotp"),
        @RouterOperation(
                path = "/api/mfa/sms/enable",
                method = RequestMethod.POST,
                beanClass = MfaManagementHandler.class,
                beanMethod = "enableSms"),
        @RouterOperation(
                path = "/api/mfa/email/enable",
                method = RequestMethod.POST,
                beanClass = MfaManagementHandler.class,
                beanMethod = "enableEmail"),
        @RouterOperation(
                path = "/api/mfa/{type}",
                method = RequestMethod.DELETE,
                beanClass = MfaManagementHandler.class,
                beanMethod = "disableMfa"),
        @RouterOperation(
                path = "/api/mfa/verify",
                method = RequestMethod.POST,
                beanClass = MfaManagementHandler.class,
                beanMethod = "verifyMfaCode"),
        @RouterOperation(
                path = "/api/mfa/send-code",
                method = RequestMethod.POST,
                beanClass = MfaManagementHandler.class,
                beanMethod = "sendMfaCode"),
        @RouterOperation(
                path = "/api/mfa/configs",
                method = RequestMethod.GET,
                beanClass = MfaManagementHandler.class,
                beanMethod = "getUserMfaConfigs"),
        @RouterOperation(
                path = "/api/mfa/status",
                method = RequestMethod.GET,
                beanClass = MfaManagementHandler.class,
                beanMethod = "checkMfaStatus"),
        @RouterOperation(
                path = "/api/mfa/backup-codes/regenerate",
                method = RequestMethod.POST,
                beanClass = MfaManagementHandler.class,
                beanMethod = "regenerateBackupCodes"),
        @RouterOperation(
                path = "/api/mfa/backup-codes/verify",
                method = RequestMethod.POST,
                beanClass = MfaManagementHandler.class,
                beanMethod = "verifyBackupCode"),
        @RouterOperation(
                path = "/api/mfa/unlock",
                method = RequestMethod.POST,
                beanClass = MfaManagementHandler.class,
                beanMethod = "unlockMfa")
    })
    public RouterFunction<ServerResponse> authCenterMfaRoutes() {
        return route().POST("/api/mfa/totp/enable", mfaHandler::enableTotp)
                .POST("/api/mfa/totp/activate", mfaHandler::activateTotp)
                .POST("/api/mfa/sms/enable", mfaHandler::enableSms)
                .POST("/api/mfa/email/enable", mfaHandler::enableEmail)
                .DELETE("/api/mfa/{type}", mfaHandler::disableMfa)
                .POST("/api/mfa/verify", mfaHandler::verifyMfaCode)
                .POST("/api/mfa/send-code", mfaHandler::sendMfaCode)
                .GET("/api/mfa/configs", mfaHandler::getUserMfaConfigs)
                .GET("/api/mfa/status", mfaHandler::checkMfaStatus)
                .POST("/api/mfa/backup-codes/regenerate", mfaHandler::regenerateBackupCodes)
                .POST("/api/mfa/backup-codes/verify", mfaHandler::verifyBackupCode)
                .POST("/api/mfa/unlock", mfaHandler::unlockMfa)
                .build();
    }

    /**
     * IP访问控制路由。
     *
     * @return IP 规则管理路由
     */
    @Bean
    @RouterOperations({
        @RouterOperation(
                path = "/api/ip-access-control/whitelist",
                method = RequestMethod.POST,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "addToWhitelist"),
        @RouterOperation(
                path = "/api/ip-access-control/blacklist",
                method = RequestMethod.POST,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "addToBlacklist"),
        @RouterOperation(
                path = "/api/ip-access-control/whitelist",
                method = RequestMethod.DELETE,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "removeFromWhitelist"),
        @RouterOperation(
                path = "/api/ip-access-control/blacklist",
                method = RequestMethod.DELETE,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "removeFromBlacklist"),
        @RouterOperation(
                path = "/api/ip-access-control/whitelist",
                method = RequestMethod.GET,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "getWhitelist"),
        @RouterOperation(
                path = "/api/ip-access-control/blacklist",
                method = RequestMethod.GET,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "getBlacklist"),
        @RouterOperation(
                path = "/api/ip-access-control/{ruleId}/enable",
                method = RequestMethod.PUT,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "enableRule"),
        @RouterOperation(
                path = "/api/ip-access-control/{ruleId}/disable",
                method = RequestMethod.PUT,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "disableRule"),
        @RouterOperation(
                path = "/api/ip-access-control/{ruleId}",
                method = RequestMethod.DELETE,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "deleteRule"),
        @RouterOperation(
                path = "/api/ip-access-control/cleanup",
                method = RequestMethod.POST,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "cleanupExpiredRules"),
        @RouterOperation(
                path = "/api/ip-access-control/check",
                method = RequestMethod.POST,
                beanClass = IpAccessControlHandler.class,
                beanMethod = "checkAccess")
    })
    public RouterFunction<ServerResponse> ipAccessControlRoutes() {
        return route().POST("/api/ip-access-control/whitelist", ipAccessControlHandler::addToWhitelist)
                .POST("/api/ip-access-control/blacklist", ipAccessControlHandler::addToBlacklist)
                .DELETE("/api/ip-access-control/whitelist", ipAccessControlHandler::removeFromWhitelist)
                .DELETE("/api/ip-access-control/blacklist", ipAccessControlHandler::removeFromBlacklist)
                .GET("/api/ip-access-control/whitelist", ipAccessControlHandler::getWhitelist)
                .GET("/api/ip-access-control/blacklist", ipAccessControlHandler::getBlacklist)
                .PUT("/api/ip-access-control/{ruleId}/enable", ipAccessControlHandler::enableRule)
                .PUT("/api/ip-access-control/{ruleId}/disable", ipAccessControlHandler::disableRule)
                .DELETE("/api/ip-access-control/{ruleId}", ipAccessControlHandler::deleteRule)
                .POST("/api/ip-access-control/cleanup", ipAccessControlHandler::cleanupExpiredRules)
                .POST("/api/ip-access-control/check", ipAccessControlHandler::checkAccess)
                .build();
    }
}

package com.apex.scaffold.authservice.interfaces.handler;

import com.apex.scaffold.auth.application.dto.AuthCenterApiResponses;
import com.apex.scaffold.auth.domain.model.MfaConfig;
import com.apex.scaffold.auth.domain.service.MfaService;
import com.apex.scaffold.common.annotation.OperationLog;
import com.apex.scaffold.common.annotation.OperationLog.OperationType;
import com.apex.scaffold.common.annotation.RequireAdminRole;
import com.apex.scaffold.common.annotation.RequireResourcePermission;
import com.apex.scaffold.common.context.TenantContext;
import com.apex.scaffold.common.result.Result;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.enums.ParameterIn;
import io.swagger.v3.oas.annotations.media.ArraySchema;
import io.swagger.v3.oas.annotations.media.Content;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.responses.ApiResponse;
import io.swagger.v3.oas.annotations.tags.Tag;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.reactive.function.server.ServerRequest;
import org.springframework.web.reactive.function.server.ServerResponse;
import reactor.core.publisher.Mono;

/**
 * 多因素认证管理处理器。
 *
 * <p>当前用户与租户来自可信请求上下文。TOTP 初始化后需激活，短信与邮箱配置由服务直接启用。
 * 配置列表返回裸数组，其他成功响应使用 Result；服务异步失败返回 HTTP 500。
 *
 * @author Apex Team
 * @since 1.3.1
 */
@Slf4j
@Component
@RequiredArgsConstructor
@Tag(name = "多因素认证", description = "MFA/2FA管理 - 支持TOTP、SMS、Email三种认证方式")
public class MfaManagementHandler {
    private final MfaService mfaService;

    /**
     * 为当前用户初始化 TOTP，生成密钥与二维码信息，尚需激活。
     * @param request 提供可信 userId、tenantId 的请求
     * @return Result 包装的 secret、qrCodeUrl、manualEntryKey
     */
    @OperationLog(
            module = "MFA管理",
            type = OperationType.INSERT,
            description = "启用TOTP多因素认证",
            saveRequest = false,
            saveResponse = false)
    @Operation(operationId = "enableTotp", summary = "初始化TOTP", description = "生成TOTP密钥和二维码，添加到认证器后需验证激活")
    @ApiResponse(
            responseCode = "200",
            description = "初始化信息",
            content =
                    @Content(mediaType = "application/json", schema = @Schema(implementation = TotpSetupResult.class)))
    @ApiResponse(
            responseCode = "500",
            description = "服务处理失败",
            content = @Content(mediaType = "application/json", schema = @Schema(implementation = Result.class)))
    public Mono<ServerResponse> enableTotp(ServerRequest request) {
        String userId = request.attribute("userId")
                .map(Object::toString)
                .orElseThrow(() -> new IllegalArgumentException("userId is required"));
        String tenantId = tenantId(request);
        return mfaService
                .enableTotp(userId, tenantId)
                .flatMap(result -> ServerResponse.ok()
                        .contentType(MediaType.APPLICATION_JSON)
                        .bodyValue(Result.success(result)))
                .onErrorResume(this::handleError);
    }

    /**
     * 校验当前用户的 TOTP 并激活配置。
     * @param request 包含 code 查询参数和可信用户、租户属性的请求
     * @return Result 包装的激活结论及备用码；服务异步失败返回 HTTP 500
     */
    @OperationLog(
            module = "MFA管理",
            type = OperationType.UPDATE,
            description = "验证并激活TOTP",
            saveRequest = false,
            saveResponse = false)
    @Operation(operationId = "activateTotp", summary = "验证并激活TOTP", description = "校验认证器验证码并返回激活结果及备用码")
    @Parameter(
            name = "code",
            in = ParameterIn.QUERY,
            description = "认证器验证码",
            required = true,
            schema = @Schema(implementation = String.class))
    @ApiResponse(
            responseCode = "200",
            description = "激活结果",
            content =
                    @Content(
                            mediaType = "application/json",
                            schema = @Schema(implementation = TotpActivationResult.class)))
    @ApiResponse(
            responseCode = "500",
            description = "服务处理失败",
            content = @Content(mediaType = "application/json", schema = @Schema(implementation = Result.class)))
    public Mono<ServerResponse> activateTotp(ServerRequest request) {
        String userId = request.attribute("userId")
                .map(Object::toString)
                .orElseThrow(() -> new IllegalArgumentException("userId is required"));
        String code = request.queryParam("code").orElseThrow(() -> new IllegalArgumentException("code is required"));
        String tenantId = tenantId(request);
        return mfaService
                .verifyAndActivateTotp(userId, code, tenantId)
                .flatMap(result -> ServerResponse.ok()
                        .contentType(MediaType.APPLICATION_JSON)
                        .bodyValue(Result.success(result)))
                .onErrorResume(this::handleError);
    }

    /**
     * 绑定手机号并调用服务直接启用短信 MFA。
     * @param request 含 phoneNumber 查询参数的请求
     * @return Result 包装的 MFA 配置；服务异步失败返回 HTTP 500
     */
    @OperationLog(
            module = "MFA管理",
            type = OperationType.INSERT,
            description = "启用短信MFA",
            saveRequest = false,
            saveResponse = false)
    @Operation(operationId = "enableSms", summary = "启用短信MFA", description = "为当前可信用户绑定手机号并直接启用短信MFA")
    @Parameter(
            name = "phoneNumber",
            in = ParameterIn.QUERY,
            description = "手机号码",
            required = true,
            schema = @Schema(implementation = String.class))
    @ApiResponse(
            responseCode = "200",
            description = "MFA配置",
            content =
                    @Content(
                            mediaType = "application/json",
                            schema = @Schema(implementation = ManagedMfaConfigResult.class)))
    @ApiResponse(
            responseCode = "500",
            description = "服务处理失败",
            content = @Content(mediaType = "application/json", schema = @Schema(implementation = Result.class)))
    public Mono<ServerResponse> enableSms(ServerRequest request) {
        String userId = request.attribute("userId")
                .map(Object::toString)
                .orElseThrow(() -> new IllegalArgumentException("userId is required"));
        String tenantId = tenantId(request);
        String phoneNumber = request.queryParam("phoneNumber")
                .orElseThrow(() -> new IllegalArgumentException("phoneNumber is required"));
        return mfaService
                .enableSms(userId, tenantId, phoneNumber)
                .flatMap(config -> ServerResponse.ok()
                        .contentType(MediaType.APPLICATION_JSON)
                        .bodyValue(Result.success(config)))
                .onErrorResume(this::handleError);
    }

    /**
     * 绑定邮箱并调用服务直接启用邮箱 MFA。
     * @param request 含 email 查询参数的请求
     * @return Result 包装的 MFA 配置；服务异步失败返回 HTTP 500
     */
    @OperationLog(
            module = "MFA管理",
            type = OperationType.INSERT,
            description = "启用邮箱MFA",
            saveRequest = false,
            saveResponse = false)
    @Operation(operationId = "enableEmail", summary = "启用邮箱MFA", description = "为当前可信用户绑定邮箱并直接启用邮箱MFA")
    @Parameter(
            name = "email",
            in = ParameterIn.QUERY,
            description = "邮箱地址",
            required = true,
            schema = @Schema(implementation = String.class))
    @ApiResponse(
            responseCode = "200",
            description = "MFA配置",
            content =
                    @Content(
                            mediaType = "application/json",
                            schema = @Schema(implementation = ManagedMfaConfigResult.class)))
