 * <h2>核心字段</h2>
 * <ul>
 *   <li>{@link #messageCode} - 消息编码（唯一标识）</li>
 *   <li>{@link #templateId} - 消息模板 ID（关联 {@code off_message_template}，可选）</li>
 *   <li>{@link #subject} - 消息主题</li>
 *   <li>{@link #content} - 消息内容（支持富文本）</li>
 *   <li>{@link #messageType} - 消息类型（SYSTEM_NOTIFY=系统通知、USER_MESSAGE=用户消息、APPROVAL_NOTIFY=审批通知）</li>
 *   <li>{@link #priority} - 优先级（LOW=低、NORMAL=普通、HIGH=高、URGENT=紧急）</li>
 *   <li>{@link #senderId} - 发送人 ID（系统消息为 null）</li>
 *   <li>{@link #senderName} - 发送人姓名（冗余字段，便于查询）</li>
 *   <li>{@link #sendTime} - 发送时间</li>
 *   <li>{@link #expireTime} - 过期时间（过期后消息自动失效）</li>
 *   <li>{@link #status} - 消息状态（DRAFT=草稿、SENDING=发送中、SENT=已发送、FAILED=发送失败）</li>
 *   <li>{@link #tenantId} - 租户标识（多租户隔离）</li>
 * </ul>
 *
 * <h2>消息类型</h2>
 * <ul>
 *   <li>SYSTEM_NOTIFY：系统通知（如密码重置、账号变更）</li>
 *   <li>USER_MESSAGE：用户消息（如好友申请、消息提醒）</li>
 *   <li>APPROVAL_NOTIFY：审批通知（如审批提交、审批结果）</li>
 *   <li>TASK_NOTIFY：任务通知（如任务分配、任务到期）</li>
 * </ul>
 *
 * <h2>消息状态</h2>
 * <ul>
 *   <li>DRAFT：草稿状态，未发送</li>
 *   <li>SENDING：发送中，正在分发给接收人</li>
 *   <li>SENT：已发送，消息已成功分发</li>
 *   <li>FAILED：发送失败，需要重试或人工处理</li>
 * </ul>
 *
 * <h2>关联关系</h2>
 * <ul>
 *   <li>一对多：一条消息可以有多个接收人（通过 {@code off_message_recipient} 关联）</li>
 *   <li>多对一：消息可以关联一个模板（{@code templateId}）</li>
 * </ul>
 *
 * <h2>业务场景</h2>
 * <ul>
 *   <li>站内通知：系统向用户发送通知消息</li>
 *   <li>用户消息：用户之间的私信交流</li>
 *   <li>批量消息：基于模板批量发送格式统一的消息</li>
 *   <li>定时消息：设置发送时间的延迟消息</li>
 * </ul>
 *
 * <h2>注意事项</h2>
 * <ul>
 *   <li>消息编码 {@code messageCode} 应保持全局唯一</li>
 *   <li>过期时间 {@code expireTime} 用于自动清理历史消息</li>
 *   <li>消息内容 {@code content} 支持 HTML 格式，需防止 XSS 攻击</li>
 *   <li>租户隔离通过 {@code tenantId} 字段实现</li>
 * </ul>
 *
 * @author Apex Team
 * @version 1.2.0
 * @since 1.2.0
 * @see BasePO
 * @see OffMessageTemplatePO
 * @see OffMessageRecipientPO
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
@SuperBuilder
@EqualsAndHashCode(callSuper = true)
@TableName("off_message")
public class OffMessagePO extends BasePO {

    @TableField("message_code")
    private String messageCode;

    @TableField("template_id")
    private Long templateId;

    @TableField("subject")
    private String subject;

    @TableField("content")
    private String content;

    @TableField("message_type")
    private String messageType;

    @TableField("priority")
    private String priority;

    @TableField("sender_id")
    private Long senderId;

    @TableField("sender_name")
    private String senderName;

    @TableField("send_time")
    private LocalDateTime sendTime;

    @TableField("expire_time")
    private LocalDateTime expireTime;

    @TableField("status")
    private String status;

    @TableField("tenant_id")
    private String tenantId;
}

package com.apex.scaffold.office.off.infrastructure.persistence.repository;

import com.apex.scaffold.common.dto.PageResponse;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.office.off.domain.entity.OffMessageEntity;
import com.apex.scaffold.office.off.domain.repository.OffMessageRepository;
import com.apex.scaffold.office.off.infrastructure.persistence.converter.OffMessagePoConverter;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageRecipientMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffMessagePO;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffMessageRecipientPO;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import java.util.Comparator;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Repository;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

/**
 * 办公消息的 MyBatis 持久化适配器。
 *
 * <p>所有数据库访问均延迟到订阅后在 JDBC 调度器执行，数据库异常以错误信号传播。
 * 租户条件由服务装配的消息租户拦截器根据可信上下文注入，调用链须传播该上下文；
 * 仓储不校验收发件人的访问权限，调用方仍须完成业务授权。
 * 本类不创建事务，也不因返回响应式类型而继承调用线程的 JDBC 事务。
 *
 * @author Apex Team
 * @since 1.2.0
 */
@Repository
@RequiredArgsConstructor
public class OffMessageRepositoryImpl implements OffMessageRepository {

    private final OffMessageMapper mapper;
    private final OffMessageRecipientMapper recipientMapper;
    private final OffMessagePoConverter converter;

    /**
     * 在 JDBC 调度器按主键查询消息主体，不加载接收人记录。
     *
     * @param id 消息主键
     * @return 转换后的消息；当前租户内不存在可见记录时为空
     */
    @Override
    public Mono<OffMessageEntity> findById(Long id) {
        return Mono.fromCallable(() -> mapper.selectById(id))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(converter.toEntity(po)));
    }

    /**
     * 在 JDBC 调度器按业务编码查询单条消息，不验证当前用户是否为收件人。
     *
     * @param messageCode 消息业务编码
     * @return 当前租户内可见的消息，不存在时为空；多条匹配等查询异常通过错误信号传播
     */
    @Override
    public Mono<OffMessageEntity> findByMessageCode(String messageCode) {
        return Mono.fromCallable(() -> mapper.selectOne(
                        new LambdaQueryWrapper<OffMessagePO>().eq(OffMessagePO::getMessageCode, messageCode)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(converter.toEntity(po)));
    }

    /**
     * 在 JDBC 调度器按接收记录主键倒序选取一页，再批量加载消息主体并按发送时间倒序排列。
     *
     * <p>发送时间为空的消息排在页内末尾；关联查询未建立事务快照，不保证并发变更时两次读取一致。
     *
     * @param recipientId 已通过业务授权的接收用户标识
     * @param pageNum 从 1 开始的页码，调用方负责校验
     * @param pageSize 每页记录数，调用方负责校验
     * @return 当前页可见消息，无记录时为空流
     */
    @Override
    public Flux<OffMessageEntity> findByRecipientId(Long recipientId, Integer pageNum, Integer pageSize) {
        return Mono.fromCallable(() -> {
                    // 接收人维度数据在关联表 off_message_recipient，先按接收人分页取消息 ID，再批量加载消息本体
                    Page<OffMessageRecipientPO> page = new Page<>(pageNum, pageSize);
                    recipientMapper.selectPage(
                            page,
                            new LambdaQueryWrapper<OffMessageRecipientPO>()
                                    .eq(OffMessageRecipientPO::getRecipientId, recipientId)
                                    .orderByDesc(OffMessageRecipientPO::getId));
                    List<Long> messageIds = page.getRecords().stream()
                            .map(OffMessageRecipientPO::getMessageId)
                            .toList();
                    if (messageIds.isEmpty()) {
                        return List.<OffMessageEntity>of();
                    }
                    return mapper.selectBatchIds(messageIds).stream()
                            .sorted(Comparator.comparing(
                                    OffMessagePO::getSendTime, Comparator.nullsLast(Comparator.reverseOrder())))
                            .map(converter::toEntity)
                            .toList();
                })
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMapMany(Flux::fromIterable);
    }

    /**
     * 在 JDBC 调度器查询指定发送人的一页消息，按发送时间倒序返回。
     *
     * @param senderId 已通过业务授权的发送用户标识
     * @param pageNum 从 1 开始的页码，调用方负责校验
     * @param pageSize 每页记录数，调用方负责校验
     * @return 当前租户内可见的发件消息，无记录时为空流
     */
    @Override
    public Flux<OffMessageEntity> findBySenderId(Long senderId, Integer pageNum, Integer pageSize) {
        return Mono.fromCallable(() -> {
                    Page<OffMessagePO> page = new Page<>(pageNum, pageSize);
                    mapper.selectPage(
                            page,
                            new LambdaQueryWrapper<OffMessagePO>()
                                    .eq(OffMessagePO::getSenderId, senderId)
                                    .orderByDesc(OffMessagePO::getSendTime));
                    return page.getRecords();
                })
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMapMany(Flux::fromIterable)
                .map(converter::toEntity);
    }

    /**
     * 在 JDBC 调度器插入消息主体，并将数据库生成的主键回填到传入实体。
     *
     * <p>不同时保存接收人记录；需要主体与接收人原子提交时，应使用业务层的同步事务写入路径。
     *
     * @param entity 待保存的消息实体，订阅执行时会修改其主键
     * @return Mapper 调用正常结束时固定返回 {@code 1}，不直接返回 Mapper 的影响行数
     */
    @Override
    public Mono<Integer> insert(OffMessageEntity entity) {
        return Mono.fromCallable(() -> {
                    OffMessagePO po = converter.toPo(entity);
                    mapper.insert(po);
                    entity.setId(po.getId());
                    return 1;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 在 JDBC 调度器按主键更新消息主体，字段写入策略遵循 MyBatis 实体映射配置。
     *
     * @param entity 包含消息主键及待更新字段的实体
     * @return 数据库影响行数，未匹配可见记录时为零
     */
    @Override
    public Mono<Integer> update(OffMessageEntity entity) {
        return Mono.fromCallable(() -> {
                    OffMessagePO po = converter.toPo(entity);
                    return mapper.updateById(po);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 在 JDBC 调度器调用消息主体的主键删除，不同步删除接收人记录。
     *
     * @param id 已通过业务授权的消息主键
     * @return 删除调用完成信号，未匹配记录仍正常完成；逻辑删除行为遵循实体映射配置
     */
    @Override
    public Mono<Void> deleteById(Long id) {
        return Mono.fromCallable(() -> mapper.deleteById(id))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .then();
    }

    /**
     * 在 JDBC 调度器统计当前租户内指定用户的接收记录，不关联检查消息主体状态。
     *
     * @param recipientId 已通过业务授权的接收用户标识
     * @return 接收记录数，无记录时为零
     */
    @Override
    public Mono<Long> countByRecipientId(Long recipientId) {
        return Mono.fromCallable(() -> recipientMapper.selectCount(new LambdaQueryWrapper<OffMessageRecipientPO>()
                        .eq(OffMessageRecipientPO::getRecipientId, recipientId)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 在 JDBC 调度器统计当前租户内阅读状态为 {@code false} 的接收记录。
     *
     * @param recipientId 已通过业务授权的接收用户标识
     * @return 未读接收记录数，不关联检查消息主体状态
     */
    @Override
    public Mono<Long> countUnreadByRecipientId(Long recipientId) {
        return Mono.fromCallable(() -> recipientMapper.selectCount(new LambdaQueryWrapper<OffMessageRecipientPO>()
                        .eq(OffMessageRecipientPO::getRecipientId, recipientId)
                        .eq(OffMessageRecipientPO::getReadStatus, false)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 在 JDBC 调度器按可选状态和类型查询消息主体，按发送时间倒序分页。
     *
     * <p>该查询不添加收发件人条件，调用方须事先验证管理或相应查询权限。
     * 返回对象仅显式设置总数与记录列表，其他分页字段沿用响应对象默认值。
     *
     * @param pageNum 从 1 开始的页码，调用方负责校验
     * @param pageSize 每页记录数，调用方负责校验
     * @param status 精确匹配的消息状态，{@code null} 时不限制
     * @param messageType 精确匹配的消息类型，{@code null} 时不限制
     * @return 当前租户内可见消息的总数与当前页记录
     */
    @Override
    public Mono<PageResponse<OffMessageEntity>> findPage(
            Integer pageNum, Integer pageSize, String status, String messageType) {
        return Mono.fromCallable(() -> {
                    Page<OffMessagePO> page = new Page<>(pageNum, pageSize);
                    LambdaQueryWrapper<OffMessagePO> wrapper = new LambdaQueryWrapper<>();
                    if (status != null) {
                        wrapper.eq(OffMessagePO::getStatus, status);
                    }
                    if (messageType != null) {
                        wrapper.eq(OffMessagePO::getMessageType, messageType);
                    }
                    wrapper.orderByDesc(OffMessagePO::getSendTime);
                    mapper.selectPage(page, wrapper);

                    PageResponse<OffMessageEntity> response = new PageResponse<>();
                    response.setTotal(page.getTotal());
                    response.setRecords(converter.toEntityList(page.getRecords()));
                    return response;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }
}

package com.apex.scaffold.office.off.infrastructure.persistence.repository;

import com.apex.scaffold.common.context.TenantContext;
import com.apex.scaffold.common.exception.BusinessException;
import com.apex.scaffold.common.result.ResultCode;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.office.off.domain.entity.OffMessageEntity;
import com.apex.scaffold.office.off.domain.repository.MessageDeliveryRepository;
import com.apex.scaffold.office.off.infrastructure.persistence.converter.OffMessagePoConverter;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffEmployeeMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageRecipientMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffEmployeePO;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffMessageRecipientPO;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import java.util.List;
import java.util.stream.Collectors;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import reactor.core.publisher.Mono;

/**
 * 在专用 JDBC 调度器上执行消息及接收人原子写入。
 * @author Apex Team
 * @version 1.3.1
 * @since 1.3.1
 */
@Repository
@RequiredArgsConstructor
public class MessageDeliveryRepositoryImpl implements MessageDeliveryRepository {
    /** 单次发送允许的最大接收人数量，与 SendMessageRequest 的校验上限保持一致。 */
    private static final int MAX_RECIPIENTS = 100;

    private final OffMessageMapper messageMapper;
    private final OffMessageRecipientMapper recipientMapper;
    private final OffMessagePoConverter converter;
    private final PlatformTransactionManager transactionManager;
    private final OffEmployeeMapper employeeMapper;

    /**
     * 单线程本地事务校验接收用户归属并写入，任一接收人失败使全部写入回滚。
     * JDBC 线程显式安装可信租户，结束后恢复原线程上下文。
     * @param message 待发送消息
     * @param recipients 去重后的接收用户，须在本租户绑定有效办公员工
     * @return 已完成事务提交的消息
     */
    @Override
    public Mono<OffMessageEntity> save(OffMessageEntity message, List<Long> recipients) {
        return Mono.deferContextual(context -> Mono.fromCallable(() -> {
                    String tenant = context.get(TenantContext.REACTOR_CONTEXT_KEY);
                    if (!tenant.equals(message.getTenantId())) {
                        throw new IllegalStateException("站内信写入租户不匹配");
                    }
                    String previous = TenantContext.setTenantId(tenant);
                    try {
                        return new TransactionTemplate(transactionManager).execute(status -> {
                            validateRecipients(tenant, recipients);
                            var po = converter.toPo(message);
                            var now = java.time.LocalDateTime.now();
                            po.setCreateTime(now);
                            po.setUpdateTime(now);
                            po.setVersion(0);
                            po.setDeleted(0);
                            if (messageMapper.insert(po) != 1) {
                                throw new IllegalStateException("消息写入失败");
                            }
                            message.setId(po.getId());
                            for (Long userId : recipients) {
                                var recipient = new OffMessageRecipientPO();
                                recipient.setMessageId(po.getId());
                                recipient.setRecipientId(userId);
                                recipient.setRecipientType("USER");
                                recipient.setTenantId(tenant);
                                recipient.setReadStatus(false);
                                recipient.setCreateTime(now);
                                recipient.setUpdateTime(now);
                                recipient.setVersion(0);
                                recipient.setDeleted(0);
                                if (recipientMapper.insert(recipient) != 1) {
                                    throw new IllegalStateException("消息接收人写入失败");
                                }
                            }
                            return message;
                        });
                    } finally {
                        TenantContext.restoreTenantId(previous);
                    }
                })
                .subscribeOn(BlockingIoSchedulers.jdbc()));
    }

    /**
     * 根据本地办公员工的用户绑定验证收件人归属，拒绝跨租户、未绑定或停用用户。
     * @param tenant 可信租户
     * @param recipients 接收用户标识，不能使用员工主键替代
     */
    private void validateRecipients(String tenant, List<Long> recipients) {
        boolean invalidSize = recipients.isEmpty() || recipients.size() > MAX_RECIPIENTS;
        boolean invalidId = recipients.stream().anyMatch(MessageDeliveryRepositoryImpl::isInvalidUserId);
        if (invalidSize || invalidId) {
            throw new BusinessException(ResultCode.PARAM_ERROR, "接收人参数无效");
        }
        var users = employeeMapper
                .selectList(new LambdaQueryWrapper<OffEmployeePO>()
                        .select(OffEmployeePO::getUserId)
                        .eq(OffEmployeePO::getTenantId, tenant)
                        .eq(OffEmployeePO::getStatus, "ACTIVE")
                        .in(OffEmployeePO::getUserId, recipients))
                .stream()
                .map(OffEmployeePO::getUserId)
                .collect(Collectors.toSet());
        if (!users.containsAll(recipients)) {
            throw new BusinessException(ResultCode.PARAM_ERROR, "接收人不存在或不属于当前租户");
        }
    }

    /**
     * 判断单个接收用户标识是否非法，空值与非正值均视为非法输入。
     * @param userId 待检查的接收用户标识
     * @return 非法返回 true
     */
    private static boolean isInvalidUserId(Long userId) {
        return userId == null || userId <= 0;
    }
}

package com.apex.scaffold.office.off.infrastructure.persistence.po;

import com.apex.scaffold.common.persistence.po.BasePO;
import com.baomidou.mybatisplus.annotation.TableField;
import com.baomidou.mybatisplus.annotation.TableName;
import java.time.LocalDateTime;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.NoArgsConstructor;
import lombok.experimental.SuperBuilder;

/**
 * 办公消息接收人持久化对象。
 *
 * <p>对应 {@code off_message_recipient} 表，按消息维度记录每位接收人的标识、姓名、
 * 接收类型与已读状态（含已读时间），通过 messageId 关联 {@code off_message} 消息主表，
 * 并携带租户标识实现多租户隔离，支撑办公消息的送达与已读跟踪。
 *
 * @author Apex Team
 * @version 1.2.0
 * @since 1.2.0
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
@SuperBuilder
@EqualsAndHashCode(callSuper = true)
@TableName("off_message_recipient")
public class OffMessageRecipientPO extends BasePO {

    @TableField("message_id")
    private Long messageId;

    @TableField("recipient_id")
    private Long recipientId;

    @TableField("recipient_name")
    private String recipientName;

    @TableField("recipient_type")
    private String recipientType;

    @TableField("read_status")
    private Boolean readStatus;

    @TableField("read_time")
    private LocalDateTime readTime;

    @TableField("tenant_id")
    private String tenantId;
}

package com.apex.scaffold.office.off.infrastructure.persistence.repository;

import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.office.off.domain.entity.OffMessageRecipientEntity;
import com.apex.scaffold.office.off.domain.repository.OffMessageRecipientRepository;
import com.apex.scaffold.office.off.infrastructure.persistence.converter.OffMessageRecipientPoConverter;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageRecipientMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffMessageRecipientPO;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;
import java.time.LocalDateTime;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Repository;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

/**
 * 消息接收人Repository实现
 *
 * @author Apex Team
 * @since 1.2.0
 */
@Repository
@RequiredArgsConstructor
public class OffMessageRecipientRepositoryImpl implements OffMessageRecipientRepository {

    private final OffMessageRecipientMapper mapper;
    private final OffMessageRecipientPoConverter converter;

    @Override
    public Mono<OffMessageRecipientEntity> findById(Long id) {
        return Mono.fromCallable(() -> mapper.selectById(id))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(converter.toEntity(po)));
    }

    @Override
    public Flux<OffMessageRecipientEntity> findByMessageId(Long messageId) {
        return Mono.fromCallable(() -> mapper.selectList(new LambdaQueryWrapper<OffMessageRecipientPO>()
                        .eq(OffMessageRecipientPO::getMessageId, messageId)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMapMany(Flux::fromIterable)
                .map(converter::toEntity);
    }

    @Override
    public Flux<OffMessageRecipientEntity> findByRecipientId(Long recipientId) {
        return Mono.fromCallable(() -> mapper.selectList(new LambdaQueryWrapper<OffMessageRecipientPO>()
                        .eq(OffMessageRecipientPO::getRecipientId, recipientId)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMapMany(Flux::fromIterable)
                .map(converter::toEntity);
    }

    @Override
    public Mono<OffMessageRecipientEntity> findByMessageIdAndRecipientId(Long messageId, Long recipientId) {
        return Mono.fromCallable(() -> mapper.selectOne(new LambdaQueryWrapper<OffMessageRecipientPO>()
                        .eq(OffMessageRecipientPO::getMessageId, messageId)
                        .eq(OffMessageRecipientPO::getRecipientId, recipientId)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(converter.toEntity(po)));
    }

    @Override
    public Mono<Integer> insert(OffMessageRecipientEntity entity) {
        return Mono.fromCallable(() -> {
                    OffMessageRecipientPO po = converter.toPo(entity);
                    mapper.insert(po);
                    entity.setId(po.getId());
                    return 1;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    @Override
    public Mono<Integer> batchInsert(List<OffMessageRecipientEntity> entities) {
        return Mono.fromCallable(() -> {
                    int count = 0;
                    for (OffMessageRecipientEntity entity : entities) {
                        OffMessageRecipientPO po = converter.toPo(entity);
                        mapper.insert(po);
                        entity.setId(po.getId());
                        count++;
                    }
                    return count;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    @Override
    public Mono<Integer> update(OffMessageRecipientEntity entity) {
        return Mono.fromCallable(() -> {
                    OffMessageRecipientPO po = converter.toPo(entity);
                    return mapper.updateById(po);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    @Override
    public Mono<Void> deleteById(Long id) {
        return Mono.fromCallable(() -> mapper.deleteById(id))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .then();
    }

    @Override
    public Mono<Long> countUnreadByRecipientId(Long recipientId) {
        return Mono.fromCallable(() -> mapper.selectCount(new LambdaQueryWrapper<OffMessageRecipientPO>()
                        .eq(OffMessageRecipientPO::getRecipientId, recipientId)
                        .eq(OffMessageRecipientPO::getReadStatus, false)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    @Override
    public Mono<Integer> markAsRead(Long messageId, Long recipientId) {
        return Mono.fromCallable(() -> mapper.update(
                        null,
                        new LambdaUpdateWrapper<OffMessageRecipientPO>()
                                .set(OffMessageRecipientPO::getReadStatus, true)
                                .set(OffMessageRecipientPO::getReadTime, LocalDateTime.now())
                                .eq(OffMessageRecipientPO::getMessageId, messageId)
                                .eq(OffMessageRecipientPO::getRecipientId, recipientId)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    @Override
    public Mono<Integer> markAllAsRead(Long recipientId) {
        return Mono.fromCallable(() -> mapper.update(
                        null,
                        new LambdaUpdateWrapper<OffMessageRecipientPO>()
                                .set(OffMessageRecipientPO::getReadStatus, true)
                                .set(OffMessageRecipientPO::getReadTime, LocalDateTime.now())
                                .eq(OffMessageRecipientPO::getRecipientId, recipientId)
                                .eq(OffMessageRecipientPO::getReadStatus, false)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }
}

package com.apex.scaffold.office.off.infrastructure.persistence.repository;

import com.apex.scaffold.common.dto.PageResponse;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.office.off.domain.entity.OffMessageEntity;
import com.apex.scaffold.office.off.domain.repository.OffMessageRepository;
import com.apex.scaffold.office.off.infrastructure.persistence.converter.OffMessagePoConverter;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageRecipientMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffMessagePO;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffMessageRecipientPO;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import java.util.Comparator;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Repository;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

/**
 * 办公消息的 MyBatis 持久化适配器。
 *
 * <p>所有数据库访问均延迟到订阅后在 JDBC 调度器执行，数据库异常以错误信号传播。
 * 租户条件由服务装配的消息租户拦截器根据可信上下文注入，调用链须传播该上下文；
 * 仓储不校验收发件人的访问权限，调用方仍须完成业务授权。
 * 本类不创建事务，也不因返回响应式类型而继承调用线程的 JDBC 事务。
 *
 * @author Apex Team
 * @since 1.2.0
 */
@Repository
@RequiredArgsConstructor
public class OffMessageRepositoryImpl implements OffMessageRepository {

    private final OffMessageMapper mapper;
    private final OffMessageRecipientMapper recipientMapper;
    private final OffMessagePoConverter converter;

    /**
     * 在 JDBC 调度器按主键查询消息主体，不加载接收人记录。
     *
     * @param id 消息主键
     * @return 转换后的消息；当前租户内不存在可见记录时为空
     */
    @Override
    public Mono<OffMessageEntity> findById(Long id) {
        return Mono.fromCallable(() -> mapper.selectById(id))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(converter.toEntity(po)));
    }

    /**
     * 在 JDBC 调度器按业务编码查询单条消息，不验证当前用户是否为收件人。
     *
     * @param messageCode 消息业务编码
     * @return 当前租户内可见的消息，不存在时为空；多条匹配等查询异常通过错误信号传播
     */
    @Override
    public Mono<OffMessageEntity> findByMessageCode(String messageCode) {
        return Mono.fromCallable(() -> mapper.selectOne(
                        new LambdaQueryWrapper<OffMessagePO>().eq(OffMessagePO::getMessageCode, messageCode)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(converter.toEntity(po)));
    }

    /**
     * 在 JDBC 调度器按接收记录主键倒序选取一页，再批量加载消息主体并按发送时间倒序排列。
     *
     * <p>发送时间为空的消息排在页内末尾；关联查询未建立事务快照，不保证并发变更时两次读取一致。
     *
     * @param recipientId 已通过业务授权的接收用户标识
     * @param pageNum 从 1 开始的页码，调用方负责校验
     * @param pageSize 每页记录数，调用方负责校验
     * @return 当前页可见消息，无记录时为空流
     */
    @Override
    public Flux<OffMessageEntity> findByRecipientId(Long recipientId, Integer pageNum, Integer pageSize) {
        return Mono.fromCallable(() -> {
                    // 接收人维度数据在关联表 off_message_recipient，先按接收人分页取消息 ID，再批量加载消息本体
                    Page<OffMessageRecipientPO> page = new Page<>(pageNum, pageSize);
                    recipientMapper.selectPage(
                            page,
                            new LambdaQueryWrapper<OffMessageRecipientPO>()
                                    .eq(OffMessageRecipientPO::getRecipientId, recipientId)
                                    .orderByDesc(OffMessageRecipientPO::getId));
                    List<Long> messageIds = page.getRecords().stream()
                            .map(OffMessageRecipientPO::getMessageId)
                            .toList();
                    if (messageIds.isEmpty()) {
                        return List.<OffMessageEntity>of();
                    }
                    return mapper.selectBatchIds(messageIds).stream()
                            .sorted(Comparator.comparing(
                                    OffMessagePO::getSendTime, Comparator.nullsLast(Comparator.reverseOrder())))
                            .map(converter::toEntity)
                            .toList();
                })
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMapMany(Flux::fromIterable);
    }

    /**
     * 在 JDBC 调度器查询指定发送人的一页消息，按发送时间倒序返回。
     *
     * @param senderId 已通过业务授权的发送用户标识
     * @param pageNum 从 1 开始的页码，调用方负责校验
     * @param pageSize 每页记录数，调用方负责校验
     * @return 当前租户内可见的发件消息，无记录时为空流
     */
    @Override
    public Flux<OffMessageEntity> findBySenderId(Long senderId, Integer pageNum, Integer pageSize) {
        return Mono.fromCallable(() -> {
                    Page<OffMessagePO> page = new Page<>(pageNum, pageSize);
                    mapper.selectPage(
                            page,
                            new LambdaQueryWrapper<OffMessagePO>()
                                    .eq(OffMessagePO::getSenderId, senderId)
                                    .orderByDesc(OffMessagePO::getSendTime));
                    return page.getRecords();
                })
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMapMany(Flux::fromIterable)
                .map(converter::toEntity);
    }

    /**
     * 在 JDBC 调度器插入消息主体，并将数据库生成的主键回填到传入实体。
     *
     * <p>不同时保存接收人记录；需要主体与接收人原子提交时，应使用业务层的同步事务写入路径。
     *
     * @param entity 待保存的消息实体，订阅执行时会修改其主键
     * @return Mapper 调用正常结束时固定返回 {@code 1}，不直接返回 Mapper 的影响行数
     */
    @Override
    public Mono<Integer> insert(OffMessageEntity entity) {
        return Mono.fromCallable(() -> {
                    OffMessagePO po = converter.toPo(entity);
                    mapper.insert(po);
                    entity.setId(po.getId());
                    return 1;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 在 JDBC 调度器按主键更新消息主体，字段写入策略遵循 MyBatis 实体映射配置。
     *
     * @param entity 包含消息主键及待更新字段的实体
     * @return 数据库影响行数，未匹配可见记录时为零
     */
    @Override
    public Mono<Integer> update(OffMessageEntity entity) {
        return Mono.fromCallable(() -> {
                    OffMessagePO po = converter.toPo(entity);
                    return mapper.updateById(po);
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 在 JDBC 调度器调用消息主体的主键删除，不同步删除接收人记录。
     *
     * @param id 已通过业务授权的消息主键
     * @return 删除调用完成信号，未匹配记录仍正常完成；逻辑删除行为遵循实体映射配置
     */
    @Override
    public Mono<Void> deleteById(Long id) {
        return Mono.fromCallable(() -> mapper.deleteById(id))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .then();
    }

    /**
     * 在 JDBC 调度器统计当前租户内指定用户的接收记录，不关联检查消息主体状态。
     *
     * @param recipientId 已通过业务授权的接收用户标识
     * @return 接收记录数，无记录时为零
     */
    @Override
    public Mono<Long> countByRecipientId(Long recipientId) {
        return Mono.fromCallable(() -> recipientMapper.selectCount(new LambdaQueryWrapper<OffMessageRecipientPO>()
                        .eq(OffMessageRecipientPO::getRecipientId, recipientId)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 在 JDBC 调度器统计当前租户内阅读状态为 {@code false} 的接收记录。
     *
     * @param recipientId 已通过业务授权的接收用户标识
     * @return 未读接收记录数，不关联检查消息主体状态
     */
    @Override
    public Mono<Long> countUnreadByRecipientId(Long recipientId) {
        return Mono.fromCallable(() -> recipientMapper.selectCount(new LambdaQueryWrapper<OffMessageRecipientPO>()
                        .eq(OffMessageRecipientPO::getRecipientId, recipientId)
                        .eq(OffMessageRecipientPO::getReadStatus, false)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    /**
     * 在 JDBC 调度器按可选状态和类型查询消息主体，按发送时间倒序分页。
     *
     * <p>该查询不添加收发件人条件，调用方须事先验证管理或相应查询权限。
     * 返回对象仅显式设置总数与记录列表，其他分页字段沿用响应对象默认值。
     *
     * @param pageNum 从 1 开始的页码，调用方负责校验
     * @param pageSize 每页记录数，调用方负责校验
     * @param status 精确匹配的消息状态，{@code null} 时不限制
     * @param messageType 精确匹配的消息类型，{@code null} 时不限制
     * @return 当前租户内可见消息的总数与当前页记录
     */
    @Override
    public Mono<PageResponse<OffMessageEntity>> findPage(
            Integer pageNum, Integer pageSize, String status, String messageType) {
        return Mono.fromCallable(() -> {
                    Page<OffMessagePO> page = new Page<>(pageNum, pageSize);
                    LambdaQueryWrapper<OffMessagePO> wrapper = new LambdaQueryWrapper<>();
                    if (status != null) {
                        wrapper.eq(OffMessagePO::getStatus, status);
                    }
                    if (messageType != null) {
                        wrapper.eq(OffMessagePO::getMessageType, messageType);
                    }
                    wrapper.orderByDesc(OffMessagePO::getSendTime);
                    mapper.selectPage(page, wrapper);

                    PageResponse<OffMessageEntity> response = new PageResponse<>();
                    response.setTotal(page.getTotal());
                    response.setRecords(converter.toEntityList(page.getRecords()));
                    return response;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }
}

package com.apex.scaffold.office.off.infrastructure.persistence.repository;

import com.apex.scaffold.common.context.TenantContext;
import com.apex.scaffold.common.exception.BusinessException;
import com.apex.scaffold.common.result.ResultCode;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.office.off.domain.entity.OffMessageEntity;
import com.apex.scaffold.office.off.domain.repository.MessageDeliveryRepository;
import com.apex.scaffold.office.off.infrastructure.persistence.converter.OffMessagePoConverter;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffEmployeeMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageRecipientMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffEmployeePO;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffMessageRecipientPO;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import java.util.List;
import java.util.stream.Collectors;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import reactor.core.publisher.Mono;

/**
 * 在专用 JDBC 调度器上执行消息及接收人原子写入。
 * @author Apex Team
 * @version 1.3.1
 * @since 1.3.1
 */
@Repository
@RequiredArgsConstructor
public class MessageDeliveryRepositoryImpl implements MessageDeliveryRepository {
    /** 单次发送允许的最大接收人数量，与 SendMessageRequest 的校验上限保持一致。 */
    private static final int MAX_RECIPIENTS = 100;

    private final OffMessageMapper messageMapper;
    private final OffMessageRecipientMapper recipientMapper;
    private final OffMessagePoConverter converter;
    private final PlatformTransactionManager transactionManager;
    private final OffEmployeeMapper employeeMapper;

    /**
     * 单线程本地事务校验接收用户归属并写入，任一接收人失败使全部写入回滚。
     * JDBC 线程显式安装可信租户，结束后恢复原线程上下文。
     * @param message 待发送消息
     * @param recipients 去重后的接收用户，须在本租户绑定有效办公员工
     * @return 已完成事务提交的消息
     */
    @Override
    public Mono<OffMessageEntity> save(OffMessageEntity message, List<Long> recipients) {
        return Mono.deferContextual(context -> Mono.fromCallable(() -> {
                    String tenant = context.get(TenantContext.REACTOR_CONTEXT_KEY);
                    if (!tenant.equals(message.getTenantId())) {
                        throw new IllegalStateException("站内信写入租户不匹配");
                    }
                    String previous = TenantContext.setTenantId(tenant);
                    try {
                        return new TransactionTemplate(transactionManager).execute(status -> {
                            validateRecipients(tenant, recipients);
                            var po = converter.toPo(message);
                            var now = java.time.LocalDateTime.now();
                            po.setCreateTime(now);
                            po.setUpdateTime(now);
                            po.setVersion(0);
                            po.setDeleted(0);
                            if (messageMapper.insert(po) != 1) {
                                throw new IllegalStateException("消息写入失败");
                            }
                            message.setId(po.getId());
                            for (Long userId : recipients) {
                                var recipient = new OffMessageRecipientPO();
                                recipient.setMessageId(po.getId());
                                recipient.setRecipientId(userId);
                                recipient.setRecipientType("USER");
                                recipient.setTenantId(tenant);
                                recipient.setReadStatus(false);
                                recipient.setCreateTime(now);
                                recipient.setUpdateTime(now);
                                recipient.setVersion(0);
                                recipient.setDeleted(0);
                                if (recipientMapper.insert(recipient) != 1) {
                                    throw new IllegalStateException("消息接收人写入失败");
                                }
                            }
                            return message;
                        });
                    } finally {
                        TenantContext.restoreTenantId(previous);
                    }
                })
                .subscribeOn(BlockingIoSchedulers.jdbc()));
    }

    /**
     * 根据本地办公员工的用户绑定验证收件人归属，拒绝跨租户、未绑定或停用用户。
     * @param tenant 可信租户
     * @param recipients 接收用户标识，不能使用员工主键替代
     */
    private void validateRecipients(String tenant, List<Long> recipients) {
        boolean invalidSize = recipients.isEmpty() || recipients.size() > MAX_RECIPIENTS;
        boolean invalidId = recipients.stream().anyMatch(MessageDeliveryRepositoryImpl::isInvalidUserId);
        if (invalidSize || invalidId) {
            throw new BusinessException(ResultCode.PARAM_ERROR, "接收人参数无效");
        }
        var users = employeeMapper
                .selectList(new LambdaQueryWrapper<OffEmployeePO>()
                        .select(OffEmployeePO::getUserId)
                        .eq(OffEmployeePO::getTenantId, tenant)
                        .eq(OffEmployeePO::getStatus, "ACTIVE")
                        .in(OffEmployeePO::getUserId, recipients))
                .stream()
                .map(OffEmployeePO::getUserId)
                .collect(Collectors.toSet());
        if (!users.containsAll(recipients)) {
            throw new BusinessException(ResultCode.PARAM_ERROR, "接收人不存在或不属于当前租户");
        }
    }

    /**
     * 判断单个接收用户标识是否非法，空值与非正值均视为非法输入。
     * @param userId 待检查的接收用户标识
     * @return 非法返回 true
     */
    private static boolean isInvalidUserId(Long userId) {
        return userId == null || userId <= 0;
    }
}

package com.apex.scaffold.office.off.infrastructure.persistence.po;

import com.apex.scaffold.common.persistence.po.BasePO;
import com.baomidou.mybatisplus.annotation.*;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.NoArgsConstructor;
import lombok.experimental.SuperBuilder;

/**
 * 办公部门持久化对象
 *
 * <p>对应数据库表 {@code off_department}，存储从第三方办公平台（飞书、钉钉、企业微信）同步的部门组织架构信息。
 * 继承 {@link BasePO} 获得通用字段（ID、创建时间、更新时间、逻辑删除等）。
 *
 * <h2>核心字段</h2>
 * <ul>
 *   <li>{@link #deptCode} - 部门编码，企业内唯一标识</li>
 *   <li>{@link #deptName} - 部门名称</li>
 *   <li>{@link #parentId} - 父部门 ID（0 表示根部门）</li>
 *   <li>{@link #deptPath} - 部门路径（如 "/1/2/5"，用于快速查询上级部门）</li>
 *   <li>{@link #deptLevel} - 部门层级（1=一级部门，2=二级部门，以此类推）</li>
 *   <li>{@link #sortOrder} - 排序号（同级部门按此字段升序排列）</li>
 *   <li>{@link #leaderId} - 部门负责人 ID（关联 {@code off_employee}）</li>
 *   <li>{@link #leaderName} - 部门负责人姓名（冗余字段，便于查询）</li>
 *   <li>{@link #phone} - 部门联系电话</li>
 *   <li>{@link #email} - 部门联系邮箱</li>
 *   <li>{@link #status} - 部门状态（ACTIVE=正常、DISABLED=停用）</li>
 *   <li>{@link #syncSource} - 同步来源平台（FEISHU=飞书、DINGTALK=钉钉、WECOM=企业微信）</li>
 *   <li>{@link #externalId} - 外部平台部门 ID（第三方平台的唯一标识）</li>
 *   <li>{@link #tenantId} - 租户标识（多租户隔离）</li>
 * </ul>
 *
 * <h2>树形结构</h2>
 * <p>部门采用树形结构存储，通过 {@code parentId} 构建父子关系：
 * <ul>
 *   <li>根部门：{@code parentId = 0}</li>
 *   <li>子部门：{@code parentId} 指向父部门 ID</li>
 *   <li>路径字段：{@code deptPath} 记录从根到当前节点的完整路径</li>
 *   <li>层级字段：{@code deptLevel} 记录部门在树中的深度</li>
 * </ul>
 *
 * <h2>业务场景</h2>
 * <ul>
 *   <li>组织架构同步：从第三方平台定期同步部门结构</li>
 *   <li>部门树查询：构建和展示完整的组织架构树</li>
 *   <li>员工归属：通过 {@code deptId} 关联员工所属部门</li>
 *   <li>权限控制：基于部门的数据权限过滤</li>
 * </ul>
 *
 * <h2>数据来源</h2>
 * <ul>
 *   <li>飞书（Lark）：通过飞书 API 同步部门架构</li>
 *   <li>钉钉（DingTalk）：通过钉钉 API 同步部门信息</li>
 *   <li>企业微信（WeChat Work）：通过企业微信 API 同步部门结构</li>
 * </ul>
 *
 * <h2>注意事项</h2>
 * <ul>
 *   <li>部门编码 {@code deptCode} 在租户内应保持唯一</li>
 *   <li>外部平台 ID {@code externalId} 用于数据同步的幂等性保证</li>
 *   <li>删除部门时需检查是否存在子部门和员工</li>
 *   <li>租户隔离通过 {@code tenantId} 字段实现</li>
 * </ul>
 *
 * @author Apex Team
 * @version 1.2.0
 * @since 1.2.0
 * @see BasePO
 * @see OffEmployeePO
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
@SuperBuilder
@EqualsAndHashCode(callSuper = true)
@TableName("off_department")
public class OffDepartmentPO extends BasePO {

    @TableField("dept_code")
    private String deptCode;

    @TableField("dept_name")
