 *   <li>{@link #birthday} - 生日</li>
 *   <li>{@link #hireDate} - 入职日期</li>
 *   <li>{@link #status} - 员工状态（ACTIVE=在职、RESIGNED=离职、SUSPENDED=停职）</li>
