package com.apex.scaffold.office.off.infrastructure.persistence.repository;

import com.apex.scaffold.common.context.TenantContext;
import com.apex.scaffold.common.exception.BusinessException;
import com.apex.scaffold.common.result.ResultCode;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.office.off.domain.entity.OffMessageEntity;
import com.apex.scaffold.office.off.domain.repository.MessageDeliveryRepository;
import com.apex.scaffold.office.off.infrastructure.persistence.converter.OffMessagePoConverter;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffEmployeeMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffMessageRecipientMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffEmployeePO;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffMessageRecipientPO;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import java.util.List;
import java.util.stream.Collectors;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import reactor.core.publisher.Mono;

/**
 * 在专用 JDBC 调度器上执行消息及接收人原子写入。
 * @author Apex Team
 * @version 1.3.1
 * @since 1.3.1
 */
@Repository
@RequiredArgsConstructor
public class MessageDeliveryRepositoryImpl implements MessageDeliveryRepository {
    /** 单次发送允许的最大接收人数量，与 SendMessageRequest 的校验上限保持一致。 */
    private static final int MAX_RECIPIENTS = 100;

    private final OffMessageMapper messageMapper;
    private final OffMessageRecipientMapper recipientMapper;
    private final OffMessagePoConverter converter;
    private final PlatformTransactionManager transactionManager;
    private final OffEmployeeMapper employeeMapper;

    /**
     * 单线程本地事务校验接收用户归属并写入，任一接收人失败使全部写入回滚。
     * JDBC 线程显式安装可信租户，结束后恢复原线程上下文。
     * @param message 待发送消息
     * @param recipients 去重后的接收用户，须在本租户绑定有效办公员工
     * @return 已完成事务提交的消息
     */
    @Override
    public Mono<OffMessageEntity> save(OffMessageEntity message, List<Long> recipients) {
        return Mono.deferContextual(context -> Mono.fromCallable(() -> {
                    String tenant = context.get(TenantContext.REACTOR_CONTEXT_KEY);
                    if (!tenant.equals(message.getTenantId())) {
                        throw new IllegalStateException("站内信写入租户不匹配");
                    }
                    String previous = TenantContext.setTenantId(tenant);
                    try {
                        return new TransactionTemplate(transactionManager).execute(status -> {
                            validateRecipients(tenant, recipients);
                            var po = converter.toPo(message);
                            var now = java.time.LocalDateTime.now();
                            po.setCreateTime(now);
                            po.setUpdateTime(now);
                            po.setVersion(0);
                            po.setDeleted(0);
                            if (messageMapper.insert(po) != 1) {
                                throw new IllegalStateException("消息写入失败");
                            }
                            message.setId(po.getId());
                            for (Long userId : recipients) {
                                var recipient = new OffMessageRecipientPO();
                                recipient.setMessageId(po.getId());
                                recipient.setRecipientId(userId);
                                recipient.setRecipientType("USER");
                                recipient.setTenantId(tenant);
                                recipient.setReadStatus(false);
                                recipient.setCreateTime(now);
                                recipient.setUpdateTime(now);
                                recipient.setVersion(0);
                                recipient.setDeleted(0);
                                if (recipientMapper.insert(recipient) != 1) {
                                    throw new IllegalStateException("消息接收人写入失败");
                                }
                            }
                            return message;
                        });
                    } finally {
                        TenantContext.restoreTenantId(previous);
                    }
                })
                .subscribeOn(BlockingIoSchedulers.jdbc()));
    }

    /**
     * 根据本地办公员工的用户绑定验证收件人归属，拒绝跨租户、未绑定或停用用户。
     * @param tenant 可信租户
     * @param recipients 接收用户标识，不能使用员工主键替代
     */
    private void validateRecipients(String tenant, List<Long> recipients) {
        boolean invalidSize = recipients.isEmpty() || recipients.size() > MAX_RECIPIENTS;
        boolean invalidId = recipients.stream().anyMatch(MessageDeliveryRepositoryImpl::isInvalidUserId);
        if (invalidSize || invalidId) {
            throw new BusinessException(ResultCode.PARAM_ERROR, "接收人参数无效");
        }
        var users = employeeMapper
                .selectList(new LambdaQueryWrapper<OffEmployeePO>()
                        .select(OffEmployeePO::getUserId)
                        .eq(OffEmployeePO::getTenantId, tenant)
                        .eq(OffEmployeePO::getStatus, "ACTIVE")
                        .in(OffEmployeePO::getUserId, recipients))
                .stream()
                .map(OffEmployeePO::getUserId)
                .collect(Collectors.toSet());
        if (!users.containsAll(recipients)) {
            throw new BusinessException(ResultCode.PARAM_ERROR, "接收人不存在或不属于当前租户");
        }
    }

    /**
     * 判断单个接收用户标识是否非法，空值与非正值均视为非法输入。
     * @param userId 待检查的接收用户标识
     * @return 非法返回 true
     */
    private static boolean isInvalidUserId(Long userId) {
        return userId == null || userId <= 0;
    }
}

package com.apex.scaffold.office.off.infrastructure.persistence.po;

import com.apex.scaffold.common.persistence.po.BasePO;
import com.baomidou.mybatisplus.annotation.*;
import java.time.LocalDateTime;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.NoArgsConstructor;
import lombok.experimental.SuperBuilder;

/**
 * 办公数据同步历史持久化对象
 *
 * <p>对应数据库表 {@code off_sync_history}，记录从第三方办公平台同步数据的历史记录和执行状态。
 * 继承 {@link BasePO} 获得通用字段（ID、创建时间、更新时间、逻辑删除等）。
 *
 * <h2>核心字段</h2>
 * <ul>
 *   <li>{@link #syncType} - 同步类型（EMPLOYEE=员工、DEPARTMENT=部门、FULL=全量同步）</li>
 *   <li>{@link #syncSource} - 同步来源平台（FEISHU=飞书、DINGTALK=钉钉、WECOM=企业微信）</li>
 *   <li>{@link #syncStatus} - 同步状态（SUCCESS=成功、FAILED=失败、IN_PROGRESS=进行中）</li>
 *   <li>{@link #startTime} - 同步开始时间</li>
 *   <li>{@link #endTime} - 同步结束时间</li>
 *   <li>{@link #duration} - 同步耗时（秒）</li>
 *   <li>{@link #deptCount} - 同步的部门数量</li>
 *   <li>{@link #employeeCount} - 同步的员工数量</li>
 *   <li>{@link #errorMessage} - 错误信息（同步失败时记录）</li>
 *   <li>{@link #tenantId} - 租户标识（多租户隔离）</li>
 * </ul>
 *
 * <h2>同步类型</h2>
 * <ul>
 *   <li>EMPLOYEE：仅同步员工信息</li>
 *   <li>DEPARTMENT：仅同步部门组织架构</li>
 *   <li>FULL：全量同步（包含部门和员工）</li>
 *   <li>INCREMENTAL：增量同步（仅同步变更数据）</li>
 * </ul>
 *
 * <h2>同步状态</h2>
 * <ul>
 *   <li>IN_PROGRESS：同步进行中</li>
 *   <li>SUCCESS：同步成功完成</li>
 *   <li>FAILED：同步失败</li>
 *   <li>PARTIAL_SUCCESS：部分成功（有失败记录但整体完成）</li>
 * </ul>
 *
 * <h2>业务场景</h2>
 * <ul>
 *   <li>同步记录：记录每次数据同步的执行情况</li>
 *   <li>失败追溯：查询同步失败的历史记录和原因</li>
 *   <li>性能监控：统计同步耗时和成功率</li>
 *   <li>数据对账：通过同步记录进行数据一致性检查</li>
 *   <li>定时任务：定时任务执行时创建同步历史记录</li>
 * </ul>
 *
 * <h2>统计指标</h2>
 * <ul>
 *   <li>同步成功率 = 成功次数 / 总次数</li>
 *   <li>平均耗时 = 总耗时 / 同步次数</li>
 *   <li>数据量统计 = 部门数量 + 员工数量</li>
 * </ul>
 *
 * <h2>注意事项</h2>
 * <ul>
 *   <li>同步历史记录通常保留而不物理删除，以维护审计完整性</li>
 *   <li>可定期归档或清理过期历史记录（如 90 天前的记录）</li>
 *   <li>同步耗时 {@code duration} 用于性能监控和优化</li>
 *   <li>租户隔离通过 {@code tenantId} 字段实现</li>
 * </ul>
 *
 * @author Apex Team
 * @version 1.2.0
 * @since 1.2.0
 * @see BasePO
 * @see OffEmployeePO
 * @see OffDepartmentPO
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
@SuperBuilder
@EqualsAndHashCode(callSuper = true)
@TableName("off_sync_history")
public class OffSyncHistoryPO extends BasePO {

    @TableField("sync_type")
    private String syncType;

    @TableField("sync_source")
    private String syncSource;

    @TableField("sync_status")
    private String syncStatus;

    @TableField("start_time")
    private LocalDateTime startTime;

    @TableField("end_time")
    private LocalDateTime endTime;

    @TableField("duration")
    private Integer duration;

    @TableField("dept_count")
    private Integer deptCount;

    @TableField("employee_count")
    private Integer employeeCount;

    @TableField("error_message")
    private String errorMessage;

    @TableField("tenant_id")
    private String tenantId;
}

package com.apex.scaffold.office.off.infrastructure.persistence.repository;

import com.apex.scaffold.common.dto.PageResponse;
import com.apex.scaffold.common.scheduler.BlockingIoSchedulers;
import com.apex.scaffold.office.off.domain.entity.OffSyncHistoryEntity;
import com.apex.scaffold.office.off.domain.repository.OffSyncHistoryRepository;
import com.apex.scaffold.office.off.infrastructure.persistence.converter.OffSyncHistoryPoConverter;
import com.apex.scaffold.office.off.infrastructure.persistence.mapper.OffSyncHistoryMapper;
import com.apex.scaffold.office.off.infrastructure.persistence.po.OffSyncHistoryPO;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Repository;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

/**
 * 同步历史Repository实现
 *
 * @author Apex Team
 * @since 1.2.0
 */
@Repository
@RequiredArgsConstructor
public class OffSyncHistoryRepositoryImpl implements OffSyncHistoryRepository {

    private final OffSyncHistoryMapper mapper;
    private final OffSyncHistoryPoConverter converter;

    @Override
    public Mono<OffSyncHistoryEntity> findById(Long id) {
        return Mono.fromCallable(() -> mapper.selectById(id))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(converter.toDomain(po)));
    }

    @Override
    public Flux<OffSyncHistoryEntity> findBySyncSource(String syncSource) {
        return Mono.fromCallable(() -> mapper.selectList(new LambdaQueryWrapper<OffSyncHistoryPO>()
                        .eq(OffSyncHistoryPO::getSyncSource, syncSource)
                        .orderByDesc(OffSyncHistoryPO::getStartTime)))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMapMany(Flux::fromIterable)
                .map(converter::toDomain);
    }

    @Override
    public Mono<OffSyncHistoryEntity> findLatestBySource(String syncSource) {
        return Mono.fromCallable(() -> mapper.selectOne(new LambdaQueryWrapper<OffSyncHistoryPO>()
                        .eq(OffSyncHistoryPO::getSyncSource, syncSource)
                        .orderByDesc(OffSyncHistoryPO::getStartTime)
                        .last("LIMIT 1")))
                .subscribeOn(BlockingIoSchedulers.jdbc())
                .flatMap(po -> po == null ? Mono.empty() : Mono.just(converter.toDomain(po)));
    }

    @Override
    public Mono<Integer> insert(OffSyncHistoryEntity entity) {
        return Mono.fromCallable(() -> {
                    OffSyncHistoryPO po = converter.toPo(entity);
                    mapper.insert(po);
                    entity.setId(po.getId());
                    return 1;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    @Override
    public Mono<Integer> update(OffSyncHistoryEntity entity) {
        return Mono.fromCallable(() -> mapper.updateById(converter.toPo(entity)))
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }

    @Override
    public Mono<PageResponse<OffSyncHistoryEntity>> findPage(
            Integer pageNum, Integer pageSize, String syncSource, String syncStatus) {
        return Mono.fromCallable(() -> {
                    Page<OffSyncHistoryPO> page = new Page<>(pageNum, pageSize);
                    LambdaQueryWrapper<OffSyncHistoryPO> wrapper = new LambdaQueryWrapper<>();
                    if (syncSource != null) {
                        wrapper.eq(OffSyncHistoryPO::getSyncSource, syncSource);
                    }
                    if (syncStatus != null) {
                        wrapper.eq(OffSyncHistoryPO::getSyncStatus, syncStatus);
                    }
                    wrapper.orderByDesc(OffSyncHistoryPO::getStartTime);
                    mapper.selectPage(page, wrapper);

                    PageResponse<OffSyncHistoryEntity> response = new PageResponse<>();
                    response.setTotal(page.getTotal());
                    response.setRecords(
                            page.getRecords().stream().map(converter::toDomain).toList());
                    return response;
                })
                .subscribeOn(BlockingIoSchedulers.jdbc());
    }
}
